window.CARDIO = window.CARDIO || {};
CARDIO.registry = CARDIO.registry || {};
CARDIO.registry.observation = [{"id":"douleur-thoracique","spe":"cardio","title":"Douleur thoracique","emoji":"🫀","items":["230","339","226","235"],"hook":"Une douleur thoracique, ça peut être un reflux... ou une urgence vitale : tu dois d'abord traquer les 4 urgences cardiovasculaires (PIED) avant de te rassurer.","intro":"La douleur thoracique est un motif très fréquent de recours aux soins, aux urgences comme en consultation, et les formes atypiques sont très fréquentes. Le Collège le dit : le terrain, l'âge, le contexte et l'examen clinique soigneux ont souvent plus de valeur que les détails de la douleur, que le patient décrit parfois très mal. Ton état d'esprit : 1) détresse vitale ? 2) PIED (Péricardite, Infarctus, Embolie pulmonaire, Dissection) ? 3) seulement ensuite, les autres causes.","steps":[{"key":"terrain","title":"Terrain et antécédents","goal":"Repérer le profil de risque qui oriente vers l'une des 4 urgences avant même de parler de la douleur.","questions":[{"ask":"« Avez-vous du tabac, du diabète, de la tension, du cholestérol, des antécédents de crise cardiaque dans la famille ? »","why":"Le terrain d'un SCA, ce sont les facteurs de risque cardiovasculaire : un terrain à risque augmente la probabilité diagnostique.","flag":"terrain","src":"339 p. 117 ; 230 p. 154"},{"ask":"« Avez-vous déjà eu un infarctus, des stents, un pontage, une artérite, un souffle dans le cou ? »","why":"Une coronaropathie, une artériopathie périphérique ou une atteinte des troncs supra-aortiques connues augmentent la probabilité d'un accident coronarien.","flag":"terrain","src":"339 p. 117"},{"ask":"« Avez-vous de la tension depuis longtemps ? Quelqu'un de la famille a-t-il eu un problème de l'aorte ? Avez-vous une maladie de Marfan, une valve aortique malade, déjà été opéré de l'aorte ? »","why":"Dissection : HTA ancienne et Marfan favorisent. Dans le score de probabilité, un point pour le terrain évocateur (Marfan, antécédent familial de maladie aortique, anévrisme thoracique ou valvulopathie aortique connus, chirurgie aortique).","flag":"orientation","src":"230 p. 155"},{"ask":"« Avez-vous été opéré récemment, alité, plâtré ? Avez-vous un cancer ? Avez-vous voyagé longtemps ? »","why":"Terrain évocateur d'embolie pulmonaire : cancer, postopératoire, alitement. Les facteurs de MTEV incluent aussi une chirurgie sous anesthésie générale récente, une fracture des membres inférieurs, une immobilisation, un voyage de plus de 6 h.","flag":"orientation","src":"230 p. 156 ; 226 p. 495"},{"ask":"« Prenez-vous la pilule ? Fumez-vous ? Êtes-vous enceinte ou avez-vous accouché récemment ? »","why":"Contraception œstroprogestative associée au tabac, grossesse et post-partum : terrain d'embolie pulmonaire (le traitement hormonal de la ménopause aussi).","flag":"orientation","src":"230 p. 156 ; 226 p. 495"},{"ask":"« Avez-vous déjà fait une phlébite ou une embolie pulmonaire ? Y en a-t-il dans votre famille ? »","why":"Les antécédents personnels ou familiaux de maladie thromboembolique évoquent le terrain d'EP (et comptent dans les scores de probabilité).","flag":"orientation","src":"230 p. 156 ; 226 p. 505"},{"ask":"« Avez-vous eu un virus, un rhume, de la fièvre ces dernières semaines ? Avez-vous déjà eu une péricardite ? »","why":"Péricardite : terrain de contexte viral, fièvre, ou forme récidivante avec antécédent de péricardite (sujet jeune, contage viral).","flag":"orientation","src":"230 p. 157 ; 235 p. 533"},{"ask":"« Avez-vous eu un infarctus récemment, il y a quelques jours ou semaines ? »","why":"Une péricardite peut compliquer un infarctus : précoce (J3-J5, après un infarctus transmural) ou tardive (syndrome de Dressler, 2e à 16e semaine).","flag":"orientation","src":"235 p. 534"},{"ask":"« Quels médicaments prenez-vous ? Des anticoagulants ? Avez-vous un pacemaker ? »","why":"Un patient sous anticoagulant est un facteur qui fait discuter l'hospitalisation en cas de péricardite. Un pacemaker rend l'ECG non interprétable pour le sus-décalage de ST.","flag":"terrain","src":"235 p. 532 ; 339 p. 118"}],"astuce":"Associe chaque urgence à son profil : coronaire = tuyauterie bouchée (facteurs de risque), aorte = tension, embolie = immobilité/cancer/pilule, péricarde = jeune avec un virus. Les 4 lettres de PIED te donnent le terrain à chaque fois."},{"key":"symptome","title":"La douleur, décortiquée","goal":"Caractériser la douleur (début, durée, siège, irradiation, type, circonstances, soulagement) pour classer ischémique ou non ischémique.","questions":[{"ask":"« Depuis quand avez-vous mal ? C'est venu d'un coup ou petit à petit ? »","why":"Mode de survenue : brutal pour le SCA et la dissection, progressif et associé à une dyspnée pour l'embolie pulmonaire.","flag":"orientation","src":"230 p. 158"},{"ask":"« La douleur dure depuis combien de temps sans s'arrêter ? »","why":"L'infarctus est à évoquer dès que la douleur dépasse 20 minutes ; douleur persistante classiquement au-delà de 30 minutes et non résolutive après trinitrine = SCA ST+. Ischémique : minutes ; non ischémique : secondes ou heures sans élévation de troponine.","flag":"gravite","src":"230 p. 154 ; 339 p. 117"},{"ask":"« Où avez-vous mal exactement ? Montrez-moi avec un doigt »","why":"Ischémique : rétrosternale ou médiothoracique. Non ischémique : sous-mammaire gauche, hémithorax gauche, punctiforme (montrée du doigt) ou dorsale (dissection).","flag":"orientation","src":"230 p. 154"},{"ask":"« Est-ce que ça irradie ? Dans la mâchoire, le cou, un bras ou les deux, le dos ? »","why":"Coronarienne : irradiation au cou, aux épaules, aux avant-bras, à la tête, à la mâchoire, au bras gauche, aux deux bras ou au bras droit. Dissection : irradiation dans le dos, migratrice, vers les lombes.","flag":"orientation","src":"339 p. 116 ; 230 p. 155"},{"ask":"« C'est plutôt un serrement, une brûlure, un coup de poignard, un déchirement ? »","why":"Constriction, pesanteur, brûlure : ischémique. Acérée, en coup de poignard, augmentée par la respiration : non ischémique. Déchirement intense : dissection.","flag":"orientation","src":"230 p. 154-155"},{"ask":"« Qu'est-ce qui la déclenche : l'effort, le stress, le froid, un repas ? Et ça passe en vous arrêtant ? »","why":"Ischémique : effort, stress, énervement, temps froid ; calmée à l'arrêt de l'effort. Non ischémique : survient après la fin de l'effort, soulagée par l'effort ou provoquée par un mouvement particulier. L'angor stable est déclenché par l'effort (ou un repas).","flag":"orientation","src":"230 p. 154, 158-159"},{"ask":"« Est-ce la première fois ? Les crises sont-elles de plus en plus fréquentes ou pour des efforts de plus en plus faibles ? »","why":"Angor de novo (inaugural récent, moins d'1 mois) ou crescendo (aggravation récente d'un angor d'effort) : tableaux de SCA sans sus-décalage de ST, comme une douleur spontanée prolongée de plus de 20 minutes ou un angor après un infarctus.","flag":"orientation","src":"339 p. 117"},{"ask":"« Avez-vous pris de la trinitrine ? Ça a soulagé ? En combien de temps ? »","why":"Angor stable : cède en 1 à 3 minutes après spray de trinitrine. SCA ST+ : douleur et sus-décalage persistent après trinitrine. Péricardite : résistante à la trinitrine. Attention : une douleur œsophagienne peut aussi être calmée par les dérivés nitrés, donc non spécifique.","flag":"orientation","src":"230 p. 159-160 ; 339 p. 116-117 ; 235 p. 529"},{"ask":"« Cette douleur, vous l'avez déjà eue ? Les épisodes durent combien de temps : des secondes, des minutes, des heures ? »","why":"La durée trie : minutes = ischémique, secondes = non ischémique, heures = non ischémique en l'absence d'élévation de troponine.","flag":"orientation","src":"230 p. 154"},{"ask":"« Avez-vous plutôt mal au ventre, à l'estomac, à la mâchoire, ou seulement un essoufflement, une grande fatigue ? »","why":"Forme atypique d'un SCA : douleur épigastrique ou absente (mime une indigestion), limitée aux irradiations (bras, mâchoire), simple brûlure, faible intensité, ou dyspnée/asthénie isolée. Fréquent chez la femme, le sujet âgé, le diabétique, l'insuffisant rénal ou le dément. La douleur peut siéger de la mandibule à l'ombilic.","flag":"orientation","src":"339 p. 116-117 ; 230 p. 154"},{"ask":"« Comment évaluez-vous l'intensité de 0 à 10 ? »","why":"Dissection : douleur aiguë, prolongée, intense. À l'inverse, un SCA peut être de faible intensité. L'intensité seule ne trie donc pas : elle se lit avec le reste.","flag":"terrain","src":"230 p. 155 ; 339 p. 116"}],"astuce":"Pense « SIRDE » pour ne rien oublier : Siège, Irradiation, Rythme (début, durée), Déclenchants, Effets du soulagement. Et rappelle-toi que ce qui compte pour le SCA, c'est >20 minutes, repos, ou effort croissant."},{"key":"associes","title":"Signes associés","goal":"Trouver les symptômes qui orientent vers une des 4 urgences ou vers une complication.","questions":[{"ask":"« Avez-vous eu des sueurs, des nausées, mal à l'estomac ? »","why":"Le cortège de la douleur ischémique : sueurs, nausées, gêne épigastrique.","flag":"orientation","src":"339 p. 116 ; 230 p. 154"},{"ask":"« Êtes-vous essoufflé ? Depuis quand, et est-ce apparu avec la douleur ? »","why":"La dyspnée accompagne un SCA (environ 10 % des cas), une embolie pulmonaire (douleur basithoracique + dyspnée aiguë avec polypnée) ou une tamponnade (dyspnée, polypnée puis orthopnée). Douleur + dyspnée + radio normale : penser EP.","flag":"orientation","src":"230 p. 154, 156-157"},{"ask":"« Avez-vous eu un malaise, une perte de connaissance ? »","why":"Un malaise lipothymique ou une syncope peut accompagner un SCA ; une syncope peut aussi révéler une dissection. Dans l'EP, la syncope est rare mais témoigne d'une réduction sévère du flux sanguin.","flag":"gravite","src":"339 p. 116 ; 230 p. 155 ; 226 p. 504"},{"ask":"« Avez-vous toussé du sang, ou eu des crachats noirâtres ? »","why":"Hémoptysie (tardive) dans l'EP, liée à l'infarctus pulmonaire : la douleur est alors basithoracique, pariétopleurale, fébrile (bon pronostic).","flag":"orientation","src":"230 p. 156 ; 226 p. 504"},{"ask":"« Avez-vous de la fièvre, des frissons, des courbatures ? »","why":"Péricardite virale : fièvre modérée d'emblée, myalgies, asthénie, souvent précédée d'un épisode grippal. Pneumopathie : la douleur peut être en coup de poignard de type pleural, avec fièvre. Fièvre > 38 °C = un des 4 facteurs prédictifs majeurs de complication d'une péricardite (hospitalisation).","flag":"orientation","src":"235 p. 529, 532 ; 230 p. 160"},{"ask":"« Avez-vous une jambe gonflée ou douloureuse ? »","why":"Signe de thrombose veineuse profonde : à rechercher car elle est absente à l'examen dans un tiers des EP, mais sa présence est très évocatrice.","flag":"orientation","src":"230 p. 156 ; 226 p. 497"},{"ask":"« Avez-vous une faiblesse d'un bras ou d'une jambe, un trouble de la parole, un membre froid, des douleurs du ventre ? »","why":"Une dissection peut être révélée par une complication : AVC, déficit neurologique, ischémie aiguë de membre, infarctus mésentérique avec douleur abdominale trompeuse, hémopéricarde avec tamponnade.","flag":"gravite","src":"230 p. 155"},{"ask":"« Avez-vous du mal à avaler, des nausées, le hoquet ? »","why":"La tamponnade peut s'accompagner de dysphagie, de nausées, de hoquet (en plus de la douleur, de la dyspnée, de la toux). La péricardite peut donner hoquet, dysphonie, toux sèche.","flag":"gravite","src":"230 p. 157 ; 235 p. 529"},{"ask":"« Avez-vous senti votre cœur battre vite ou irrégulièrement ? »","why":"Les 4 plaintes cardinales sont à renseigner dans les 4 urgences : douleur thoracique, dyspnée, syncope, palpitations. L'ECG permet de détecter une arythmie ventriculaire susceptible de dégrader en TV/FV (SCA).","flag":"terrain","src":"230 p. 158 ; 339 p. 118"}],"astuce":"Les 4 plaintes cardinales à toujours renseigner : douleur thoracique, dyspnée, syncope, palpitations (tableau 6.3 du Collège)."},{"key":"orientation","title":"Les questions qui orientent","goal":"Poser les questions qui font basculer vers un diagnostic précis, urgent ou non.","questions":[{"ask":"« La douleur augmente-t-elle quand vous respirez à fond, toussez ou vous allongez ? Est-elle soulagée penché en avant ? »","if":"Si oui → péricardite aiguë","why":"Péricardite : douleur augmentée à l'inspiration profonde, en décubitus, à la toux, calmée par la position assise penchée en avant (antéflexion), rétrosternale ou précordiale gauche, prolongée.","src":"235 p. 529 ; 230 p. 157"},{"ask":"« C'est comme un point de côté brutal, en bas du thorax, avec un essoufflement ? »","if":"Si oui → embolie pulmonaire","why":"EP : douleur pleurale typique de type point de côté brutal, basithoracique, avec dyspnée aiguë, polypnée, toux. Dans le cœur pulmonaire aigu, la douleur passe au second plan.","src":"226 p. 504 ; 230 p. 156"},{"ask":"« Est-ce une douleur qui déchire, qui part dans le dos et descend vers les lombes ? »","if":"Si oui → dissection aortique","why":"Douleur de dissection : aiguë, prolongée, intense, en déchirement, irradiant dans le dos, migratrice, descendant vers les lombes, parfois avec syncope.","src":"230 p. 155"},{"ask":"« Ça vous serre derrière le sternum à l'effort et ça passe en quelques minutes au repos ? »","if":"Si oui → angor d'effort (syndrome coronarien chronique)","why":"L'angor stable est caractéristique si constrictif, déclenché par l'effort (ou un repas), cédant à l'arrêt ou après trinitrine en 1 à 3 minutes. Ensuite, la probabilité clinique oriente le choix de l'examen.","src":"230 p. 158-159"},{"ask":"« Avez-vous du mal à l'effort, un étourdissement, des palpitations, ou une maladie du cœur connue (valve, muscle) ? »","if":"Si oui → angor fonctionnel : rétrécissement aortique serré, cardiomyopathie hypertrophique, tachycardie (FA), anémie, hyperthyroïdie","why":"Devant un angor d'effort, connaître les causes d'angor fonctionnel. Certaines HTAP sévères donnent aussi des douleurs angineuses par souffrance ischémique du VD.","src":"230 p. 152, 159"},{"ask":"« Est-ce qu'on déclenche la douleur en appuyant sur le sternum ou les côtes, ou en bougeant le bras ou le buste ? »","if":"Si oui → douleur pariétale (syndrome de Tietze, arthralgie chondrocostale, fracture de côte, muscle)","why":"Douleur pariétale : reproduite à la palpation (Tietze) ou provoquée par un mouvement particulier du corps (non ischémique).","src":"230 p. 154, 160"},{"ask":"« Ça vous brûle en remontant, ça coince quand vous avalez, c'est lié aux repas ? »","if":"Si oui → cause œsophagienne (RGO, œsophagite, spasme, dysphagie)","why":"Le spasme œsophagien donne une douleur d'allure angineuse le plus souvent déclenchée par la déglutition, et elle peut être calmée par les dérivés nitrés : piège. Une rupture de l'œsophage est exceptionnelle (douleur + dyspnée + emphysème sous-cutané).","src":"230 p. 153, 160"},{"ask":"« Avez-vous de la fièvre, de la toux, des crachats ? »","if":"Si oui → pneumopathie ou pleurésie","why":"Pneumopathie : douleur parfois intense en coup de poignard de type pleural, fièvre, syndrome de condensation (souffle tubaire entouré de crépitants), opacité radiologique.","src":"230 p. 160"},{"ask":"« C'est parti brutalement, sur le côté, en faisant un effort ? Vous êtes grand et mince, fumeur ? »","if":"Si oui → pneumothorax","why":"Pneumothorax : douleur de type pleural, parfois dyspnée, tympanisme et abolition du murmure vésiculaire ; terrain longiligne, tabac, emphysème, début brutal parfois à l'effort, douleur latérothoracique.","src":"230 p. 159 ; 203 p. 448"},{"ask":"« Avez-vous une douleur en ceinture avec une éruption sur la peau ? Ou mal au ventre, après les repas, avec des nausées ? »","if":"Si oui → zona intercostal ; ou cause abdominale projetée (lithiase vésiculaire, ulcère, pancréatite aiguë)","why":"Douleurs d'origine neurologique (zona intercostal, tassement vertébral) et abdominales projetées (lithiase vésiculaire, ulcère gastroduodénal, pancréatite aiguë, appendicite sous-hépatique, abcès sous-phrénique).","src":"230 p. 160"}],"astuce":"Réflexe d'orientation en 3 mots : Respire (péricardite, poumon), Bouge (paroi), Mange (œsophage, abdomen). Et pour les 4 non cardiaques souvent graves : les 4 P (pneumonie, pleurésie, pneumothorax, pancréatite)."},{"key":"examen","title":"Examen clinique ciblé","goal":"Chercher les signes physiques qui différencient les 4 urgences et dépister les complications.","questions":[{"ask":"Mesurer la PA aux deux bras et palper les pouls (membres, carotides)","why":"Asymétrie tensionnelle (différence > 20 mmHg) ou abolition d'un pouls : dissection aortique. La PA aux deux bras est systématique devant un SCA suspecté ; cherche aussi souffle carotidien ou fémoral pour d'autres localisations d'athérome.","flag":"orientation","src":"230 p. 154-155 ; 339 p. 117"},{"ask":"Prendre FC, FR, SpO2, température","why":"Tachycardie dans l'EP, polypnée et désaturation dans la détresse respiratoire, fébricule dans la péricardite, fièvre dans la pneumopathie.","flag":"terrain","src":"230 p. 152, 156"},{"ask":"Rechercher un pouls paradoxal (PAS d'inspiration < PAS d'expiration de 10 mmHg)","why":"Signe de la tamponnade : l'inspiration augmente le retour veineux, le VD se dilate et comprime le VG, d'où la baisse de PAS.","flag":"gravite","src":"230 p. 153, 157"},{"ask":"Ausculter le cœur : frottement péricardique ? bruits du cœur assourdis ?","why":"Frottement péricardique précoce, systolodiastolique, variant dans le temps et les positions (crissement de cuir neuf, froissement de soie, bruit de pas dans la neige fraîche), confirmant le diagnostic mais inconstant et fugace : son absence n'élimine pas. Bruits du cœur assourdis dans la tamponnade.","flag":"orientation","src":"235 p. 529, 535"},{"ask":"Ausculter à la recherche d'un souffle (insuffisance aortique, souffle systolique)","why":"Souffle d'insuffisance aortique : signe possible de dissection. Souffle systolique au foyer aortique : rétrécissement aortique (angor fonctionnel) ; chez un infarcté, penser à une complication mécanique (insuffisance mitrale, rupture septale).","flag":"orientation","src":"230 p. 155 ; 339 p. 117, 131-132"},{"ask":"Ausculter les poumons : crépitants, abolition du murmure, souffle tubaire ; percuter : tympanisme ou matité","why":"Crépitants : insuffisance cardiaque d'un SCA (Killip). Pneumothorax : tympanisme, abolition du murmure. Épanchement pleural : matité. Pneumopathie : souffle tubaire entouré de crépitants.","flag":"orientation","src":"230 p. 159-160 ; 339 p. 130"},{"ask":"Chercher des signes d'insuffisance cardiaque droite : turgescence jugulaire, reflux hépatojugulaire","why":"Tamponnade (signes droits) et cœur pulmonaire aigu de l'EP ; triade de l'infarctus du VD : hypotension, poumons clairs, turgescence jugulaire.","flag":"gravite","src":"230 p. 153, 157 ; 339 p. 131"},{"ask":"Examiner les membres inférieurs : œdème unilatéral, douleur du mollet","why":"Signes de thrombose veineuse : absents dans un tiers des EP (230 p. 156) mais très évocateurs quand ils sont là ; le tableau le plus évocateur est unilatéral ou asymétrique, d'autant plus brutal.","flag":"orientation","src":"230 p. 156 ; 226 p. 497"},{"ask":"Chercher un déficit neurologique focal, et un emphysème sous-cutané (crépitation neigeuse)","why":"Déficit neurologique : signe de dissection selon le siège. Emphysème sous-cutané ou pneumomédiastin avec douleur et dyspnée : rupture de l'œsophage, exceptionnelle mais urgence thérapeutique.","flag":"gravite","src":"230 p. 153, 155"},{"ask":"Palper la paroi thoracique : le sternum, les jonctions chondrocostales","why":"Syndrome de Tietze : inflammation du cartilage jonction sternum-côtes, douleur reproduite par la palpation.","flag":"orientation","src":"230 p. 160"}],"astuce":"Les 3 signes physiques à connaître par cœur : asymétrie tensionnelle (dissection), frottement péricardique (péricarde), pouls paradoxal (tamponnade). Un examen normal n'élimine pas un SCA : il est souvent normal."},{"key":"gravite","title":"Signes de gravité (à chercher d'emblée)","goal":"Dépister la détresse vitale en premier, avant tout diagnostic, et savoir qui transférer en urgence.","questions":[{"ask":"Détresse respiratoire ? Polypnée > 30/min ou bradypnée < 10/min, tirage, sueurs, cyanose, SpO2 < 90 %, encéphalopathie respiratoire","why":"Première étape obligatoire : une détresse respiratoire impose des mesures thérapeutiques urgentes.","flag":"gravite","src":"230 p. 152"},{"ask":"Détresse hémodynamique ? Arrêt circulatoire, état de choc (collapsus, pâleur, marbrures, oligurie), signes de cœur pulmonaire","why":"Arrêt circulatoire : pouls carotidien ou fémoral non perçu, patient inconscient. Choc : hypotension avec hypoperfusion périphérique.","flag":"gravite","src":"230 p. 153"},{"ask":"Troubles neurologiques ? Confusion, agitation, convulsions","why":"Atteinte neurologique ou trouble de la conscience = détresse vitale à prendre en charge avant tout.","flag":"gravite","src":"230 p. 153"},{"ask":"Douleur de plus de 20 minutes avec sus-décalage persistant de ST : transfert médicalisé, appel du 15","why":"Risque de fibrillation ventriculaire : transfert en Usic ou en salle de coronarographie par transfert médicalisé. Ne pas appeler le 15 est une faute grave (mortalité préhospitalière élevée).","flag":"gravite","src":"230 p. 153, 161"},{"ask":"Hypotension (PAS < 90 mmHg ou baisse de PAS ≥ 40 mmHg selon l'item 230, > 40 mmHg selon l'item 226, pendant plus de 15 minutes) avec suspicion d'EP","why":"Définit l'EP à haut risque (mortalité > 15 %) ; en l'absence de trouble du rythme, d'hypovolémie ou de sepsis.","flag":"gravite","src":"230 p. 156 ; 226 p. 509"},{"ask":"Signes de tamponnade : douleur + dyspnée, signes droits, choc avec tachycardie et PAS < 90, pouls paradoxal","why":"À la différence de la péricardite non compliquée, la tamponnade est une urgence vitale (risque d'arrêt cardiocirculatoire par adiastolie).","flag":"gravite","src":"230 p. 157 ; 235 p. 535"},{"ask":"Signes d'insuffisance ventriculaire gauche : crépitants, galop, choc cardiogénique ; ou infarctus du ventricule droit","why":"Killip : 1 sans crépitants, 2 crépitants aux bases, 3 crépitants > moitié des champs (OAP), 4 choc cardiogénique. IVD : hypotension, champs clairs, turgescence jugulaire, vasodilatateurs contre-indiqués.","flag":"gravite","src":"339 p. 130-131"},{"ask":"Complications d'une dissection : ischémie de membre, AVC, douleur abdominale, hémopéricarde","why":"Présentation trompeuse possible : une dissection peut se présenter par une ischémie mésentérique ou un AVC.","flag":"gravite","src":"230 p. 155, 162"},{"ask":"Rupture de l'œsophage ? Douleur thoracique + dyspnée + emphysème sous-cutané ou pneumomédiastin","why":"Exceptionnelle mais urgence thérapeutique à évoquer.","flag":"gravite","src":"230 p. 153"}],"astuce":"Avant de réfléchir au diagnostic : A-B-C-neuro. Respire ? Circule ? Pense ? S'il y a une détresse vitale, la douleur passe au second plan. Et pour toute douleur coronarienne : appel du 15, pas de taxi."},{"key":"examens","title":"Examens de 1re intention","goal":"Savoir quoi prescrire, dans quel ordre et ce que tu cherches sur chaque examen.","questions":[{"ask":"ECG 12 dérivations (+ V3R, V4R, V7, V8, V9) sans délai, dans les 10 minutes suivant l'arrivée aux urgences","why":"Il conditionne la prise en charge. Faire un dosage de troponine avant l'ECG est une notion inacceptable. Il détecte aussi une arythmie ventriculaire.","flag":"gravite","src":"230 p. 153, 162 ; 339 p. 117-118"},{"ask":"Rechercher un SCA ST+ : sus-décalage de ST ≥ 2 mm en V2-V3 (≥ 2,5 mm chez l'homme < 40 ans, ≥ 1,5 mm chez la femme), ≥ 1 mm ailleurs, dans au moins 2 dérivations contiguës","why":"Confirme l'occlusion coronarienne aiguë ; miroir fréquent ; onde Q à partir de la 6e heure. Dérivations droites V3R-V4R si sus-décalage inférieur (extension au VD). Sous-décalage V1-V3 : enregistrer V7-V9 (sus-décalage ≥ 0,5 mm confirme).","flag":"orientation","src":"339 p. 118"},{"ask":"Savoir qu'un ECG normal n'élimine rien : le répéter à 1-2 h ; BBG et BBD = équivalent de ST+ si douleur persistante ; pacemaker ininterprétable","why":"Un ECG percritique normal n'élimine pas le diagnostic ; le territoire circonflexe peut être électriquement muet (V7-V9) ; l'ECG post-critique est normal chez plus de 30 % des SCA ST-. Si angor persistant et ECG non contributif : coronarographie au plus vite.","flag":"gravite","src":"230 p. 154 ; 339 p. 118, 121-122"},{"ask":"Reconnaître les ECG des autres urgences : péricardite, EP, tamponnade","why":"Péricardite : sus-ST concave diffus sans miroir ni onde Q, sous-décalage de PQ. EP : tachycardie sinusale, S1Q3, BBD, T négatives en V1-V3 (V1-V4). Tamponnade : microvoltage, alternance électrique.","flag":"orientation","src":"230 p. 156-157 ; 235 p. 529 ; 226 p. 504"},{"ask":"Troponine ultrasensible, répétée à 1-2 h si pas de sus-décalage persistant de ST","why":"Inutile et ne doit pas retarder la reperfusion si ST+. Sans ST+ : intérêt diagnostique et pronostique ; Tn basse sans augmentation = diagnostic différentiel ; Tn élevée ou en augmentation = SCA ST- à haut risque. Spécificité limitée (EP, dissection, myocardite, IC, tachyarythmie...). Péricardite : la doser, une élévation oriente vers une myopéricardite.","flag":"orientation","src":"230 p. 155 ; 339 p. 122 ; 235 p. 530"},{"ask":"Radiographie thoracique","why":"Systématique. Normale et souvent inutile dans un SCA typique. Dissection : élargissement du médiastin, double contour aortique, épanchement pleural. EP : souvent normale ; douleur + dyspnée + radio normale = penser EP. Péricardite : parfois silhouette élargie ; tamponnade : cœur en carafe.","flag":"orientation","src":"230 p. 155-157"},{"ask":"Échocardiographie transthoracique","why":"Épanchement péricardique (péricardite, tamponnade avec collapsus des cavités droites), cinétique segmentaire (SCA), signes de cœur pulmonaire (EP), dissection (ETT/ETO uniquement si stable). Elle peut être normale dans une péricardite sèche : la répéter.","flag":"orientation","src":"230 p. 156-157 ; 235 p. 530 ; 339 p. 123"},{"ask":"Bilan biologique de dissection : NFS, plaquettes, CRP, D-dimères, troponine, CK, créatininémie","why":"Il est rare d'avoir une dissection et des D-dimères normaux. Les CK recherchent une rhabdomyolyse.","flag":"terrain","src":"230 p. 156"},{"ask":"Estimer la probabilité d'EP (Wells ou Genève révisé) puis D-dimères ou angioscanner","why":"Faible/intermédiaire : D-dimères (seuil 500 µg/L ou âge × 10 après 50 ans), négatifs = EP éliminée. Forte : angioscanner d'emblée. En haut risque : scanner si disponible, sinon échocardiographie. Traitement anticoagulant avant confirmation si probabilité intermédiaire ou haute.","flag":"orientation","src":"230 p. 156-157 ; 226 p. 505-506"},{"ask":"Angioscanner thoracique si suspicion de dissection ; coronarographie en cas de SCA","why":"Le scanner confirme la dissection et prépare la chirurgie (porte d'entrée, extension, atteinte carotide, mésentérique, rénale) ; urgence chirurgicale si aorte ascendante (type A). La coronarographie guide la reperfusion du SCA.","flag":"orientation","src":"230 p. 156 ; 339 p. 124"}],"astuce":"Ordre d'or : ECG avant troponine, toujours. Puis radio, troponine, et l'examen ciblé selon la suspicion (scanner pour dissection ou EP, écho pour péricarde). Un SCA ST+ ne se dose pas : on reperfuse."}],"synthese":"Monsieur D., 62 ans, hypertendu, diabétique et fumeur, consulte pour une douleur rétrosternale constrictive apparue au repos il y a 2 h, irradiant dans le bras gauche et la mâchoire, avec sueurs et dyspnée, non soulagée par la trinitrine. Il est stable (PA 135/80 aux deux bras, FC 95, SpO2 96 %), l'examen cardiopulmonaire est normal, sans signe de TVP. Hypothèses : syndrome coronarien aigu en premier (ECG à faire dans les 10 min, V3R-V4R, V7-V9 si besoin), puis dissection aortique (pas d'asymétrie de PA ici), embolie pulmonaire (pas de terrain), péricardite aiguë (pas de syndrome viral).","hypotheses":[{"dx":"Syndrome coronarien aigu (ST+ ou ST-)","pour":"Facteurs de risque CV, douleur constrictive rétrosternale de repos > 20 min irradiant bras/mâchoire, sueurs/nausées, non soulagée par trinitrine, ECG (ST, T, Q) mais peut être normal","danger":true,"src":"230 p. 154 ; 339 p. 116-118"},{"dx":"Dissection aortique","pour":"HTA ancienne ou Marfan, douleur brutale intense déchirante dorsale migratrice, asymétrie de PA > 20 mmHg, abolition de pouls, souffle d'IA, déficit neurologique, élargissement du médiastin, D-dimères élevés","danger":true,"src":"230 p. 155-156"},{"dx":"Embolie pulmonaire","pour":"Terrain (cancer, alitement, post-opératoire, pilule + tabac, post-partum, ATCD de MTEV), douleur basithoracique pleurale + dyspnée + radio normale, tachycardie, signes de TVP, S1Q3/BBD/T négatives V1-V3","danger":true,"src":"230 p. 156-157 ; 226 p. 504"},{"dx":"Péricardite aiguë (non compliquée)","pour":"Sujet jeune, contage viral, fièvre, douleur inspiratoire/décubitus calmée par l'antéflexion, frottement, sus-ST concave diffus sans miroir et sous-PQ","danger":false,"src":"230 p. 157 ; 235 p. 529"},{"dx":"Tamponnade péricardique","pour":"Douleur + dyspnée/orthopnée, turgescence jugulaire, choc avec PAS < 90, bruits assourdis, pouls paradoxal, microvoltage, cœur en carafe","danger":true,"src":"230 p. 157 ; 235 p. 535"},{"dx":"Myopéricardite","pour":"Douleur péricarditique mimant un SCA, élévation prolongée de troponine, trouble cinétique du VG, coronarographie normale","danger":false,"src":"230 p. 158 ; 235 p. 530"},{"dx":"Pneumothorax","pour":"Longiligne, tabac, emphysème, début brutal, douleur pleurale latérothoracique, tympanisme, abolition du murmure, hyperclarté","danger":true,"src":"230 p. 159 ; 203 p. 448"},{"dx":"Pneumopathie, pleurésie","pour":"Fièvre, douleur pleurale en coup de poignard, souffle tubaire et crépitants, opacité systématisée","danger":false,"src":"230 p. 160"},{"dx":"Pancréatite aiguë, ulcère compliqué, cholécystite","pour":"Douleur projetée d'origine abdominale ; attention : un infarctus inférieur peut mimer une gastroentérite","danger":true,"src":"230 p. 160-162"},{"dx":"Angor stable ou fonctionnel (RA serré, CMH, FA, anémie, hyperthyroïdie)","pour":"Douleur constrictive d'effort cédant en 1-3 min au repos ou à la trinitrine ; souffle systolique aortique, anémie, tachycardie","danger":false,"src":"230 p. 158-159"},{"dx":"Cause pariétale ou œsophagienne","pour":"Douleur reproduite à la palpation (Tietze), liée à la déglutition (spasme œsophagien, RGO)","danger":false,"src":"230 p. 160"},{"dx":"Douleur psychogène","pour":"Anxiété, névrose ; diagnostic fréquent mais à évoquer avec la plus grande prudence","danger":false,"src":"230 p. 160, 162"}],"pieges":["Ne jamais attendre la troponine pour traiter un ST+ : faire l'ECG avant tout dosage.","ECG percritique normal n'élimine pas un SCA : le répéter, et penser V7-V9 (circonflexe muette).","BBG ou BBD avec angor persistant = équivalent ST+ ; pacemaker = ECG non interprétable.","Formes atypiques de SCA chez la femme, le sujet âgé, le diabétique : épigastralgie, dyspnée, fatigue.","Trinitrine soulage aussi un spasme œsophagien : son efficacité n'est pas spécifique.","Douleur + dyspnée + radio thorax normale = embolie pulmonaire jusqu'à preuve du contraire.","Un infarctus inférieur peut mimer une gastroentérite ; une dissection peut se présenter en abdomen aigu ou AVC.","Ne pas appeler le 15 devant une douleur coronarienne est une faute grave."],"src":"230 p. 151-162 ; 339 p. 112-124, 130-131 ; 226 p. 495-509 ; 235 p. 527-537"},{"id":"dyspnee","spe":"cardio","title":"Dyspnée","emoji":"🫁","items":["203","234","226"],"hook":"Une dyspnée aiguë, c'est le trio OAP, embolie pulmonaire, décompensation d'une pathologie respiratoire : tu dois vite repérer une détresse et savoir laquelle des trois c'est.","intro":"La dyspnée est un symptôme très fréquent, subjectif : un inconfort respiratoire pour un niveau d'activité qui n'en entraîne normalement aucun. Ne la confonds pas avec l'insuffisance respiratoire (on peut avoir l'une sans l'autre, par exemple dyspnée d'une anémie aiguë). Ton état d'esprit : aiguë ou chronique ? signes de gravité ? puis inspiratoire ou expiratoire, crépitants, syndrome pleural, ou dyspnée isolée.","steps":[{"key":"terrain","title":"Terrain et antécédents","goal":"Cerner le terrain cardiaque, respiratoire ou thromboembolique et les facteurs qui ont pu déclencher la dyspnée.","questions":[{"ask":"« Avez-vous une maladie du cœur : infarctus, valve malade, tension depuis longtemps, rythme irrégulier ? »","why":"OAP : terrain de cardiopathie connue, antécédent d'infarctus, facteur déclenchant comme une FA. L'HTA est un facteur direct ou indirect d'IC (hypertrophie, fibrose) : mécanisme fréquent dans l'IC à FE préservée, qui représente au moins 50 % des IC, en particulier chez la femme ou le sujet âgé.","flag":"terrain","src":"203 p. 446 ; 234 p. 469, 473"},{"ask":"« Fumez-vous ? Avez-vous une bronchite chronique (BPCO), un emphysème, de l'asthme ? »","why":"L'exacerbation de BPCO concerne le patient avec tabagisme, BPCO ou emphysème connus ; la crise d'asthme se caractérise par un antécédent. Le pneumothorax survient chez un sujet longiligne, fumeur, avec notion d'emphysème.","flag":"terrain","src":"203 p. 447-448 ; 234 p. 472"},{"ask":"« Avez-vous été opéré, alité, plâtré ou en voyage de longue durée récemment ? »","why":"L'embolie pulmonaire fait rechercher un contexte favorisant : alitement, voyage de longue durée, immobilisation sous plâtre, contexte postopératoire.","flag":"orientation","src":"203 p. 447 ; 226 p. 495"},{"ask":"« Avez-vous déjà fait une phlébite ou une embolie ? Avez-vous un cancer, une grossesse récente, la pilule ? »","why":"Antécédent de TVP/EP et cancer actif sont des critères des scores de probabilité clinique d'EP ; contraception œstroprogestative, grossesse, post-partum sont des facteurs majeurs de MTEV. 20 à 30 % des EP sont spontanées.","flag":"orientation","src":"226 p. 495, 504-505"},{"ask":"« Avez-vous bien pris vos médicaments ? Avez-vous mangé trop salé ces derniers jours ? »","why":"Devant tout épisode d'insuffisance cardiaque aiguë, rechercher les facteurs favorisants : le premier est la rupture de traitement ou de régime sans sel.","flag":"terrain","src":"234 p. 473"},{"ask":"« Prenez-vous des anti-inflammatoires, du diltiazem ou du vérapamil, de l'amiodarone, des bêtabloquants ? »","why":"Facteurs déclenchants d'IC (encadré 18.2) : causes iatrogènes (antiarythmique déprimant la fonction cardiaque, bêtabloquants, AINS, inhibiteurs calciques diltiazem/vérapamil, diminution trop importante de la précharge par diurétiques/vasodilatateurs), dysthyroïdie (amiodarone).","flag":"terrain","src":"234 p. 473"},{"ask":"« Avez-vous eu récemment une infection des bronches, une anémie, une poussée de tension, des palpitations ? »","why":"Facteurs déclenchants d'IC : surinfection bronchique, troubles du rythme (FA), anémie, EP, poussée hypertensive, SCA. La surinfection est aussi la circonstance classique de l'exacerbation de BPCO.","flag":"terrain","src":"234 p. 473 ; 203 p. 448"},{"ask":"« Buvez-vous beaucoup d'alcool, prenez-vous des drogues (cocaïne, amphétamines) ? Avez-vous reçu une chimiothérapie ? »","why":"Causes de cardiomyopathie dilatée : toxiques (alcool, amphétamines, cocaïne), chimiothérapie (anthracyclines, trastuzumab). Cardiomyopathie du péripartum après une grossesse.","flag":"terrain","src":"234 p. 470"},{"ask":"« Avez-vous respiré un produit, une fumée, une allergie connue, un chauffage récent ? Avez-vous avalé de travers ? »","why":"Facteurs saisonniers, climatiques, environnementaux ou toxiques à rechercher ; œdème de Quincke dans un contexte de choc anaphylactique ; inhalation de corps étranger (surtout l'enfant) ; intoxication au monoxyde de carbone parmi les causes.","flag":"terrain","src":"203 p. 443, 449"}],"astuce":"Trio de la dyspnée aiguë de l'adulte : Cœur (OAP), Caillot (EP), Chronique décompensée (BPCO). Chaque terrain te renvoie à l'un des trois : cardiopathie, immobilité/cancer, tabac."},{"key":"symptome","title":"Le symptôme, décortiqué","goal":"Caractériser la dyspnée : rapidité, circonstances, position, intensité (NYHA / MRC), phase respiratoire.","questions":[{"ask":"« Depuis quand êtes-vous essoufflé : quelques heures, quelques jours, quelques semaines, quelques mois ? »","why":"Rapidité d'installation : aiguë (heures ou jours) ou chronique (semaines ou mois) ; la prise en charge et le bilan en dépendent (le bilan d'une dyspnée chronique peut se faire sans urgence).","flag":"orientation","src":"203 p. 443, 450"},{"ask":"« C'est arrivé d'un coup, ou ça s'est installé progressivement ? »","why":"L'EP est en règle très brutale (203) mais peut aussi s'installer sur plusieurs semaines (226) ; l'OAP est une dyspnée aiguë de repos ; l'IC donne une dyspnée d'effort fréquente mais peu spécifique, qui peut s'aggraver progressivement.","flag":"orientation","src":"203 p. 447 ; 234 p. 461-462, 472 ; 226 p. 504"},{"ask":"« Êtes-vous essoufflé au repos ou seulement à l'effort ? »","why":"Circonstances de survenue : repos ou effort. Une dyspnée de repos est un signe de gravité dans l'exacerbation de BPCO ; la dyspnée d'effort est fréquente mais peu spécifique dans l'IC.","flag":"orientation","src":"203 p. 443, 448 ; 234 p. 461"},{"ask":"« Quelle distance marchez-vous avant de souffler ? Combien d'étages montez-vous sans vous arrêter ? »","why":"Quantifie la gêne avec la classification NYHA : I aucune gêne ; II efforts importants (marche rapide, côte, ≥ 2 étages) ; III efforts peu intenses (marche à plat, < 2 étages) ; IV repos ou efforts minimes (se laver, s'habiller). L'échelle MRC, utilisée en pneumologie, s'en rapproche.","flag":"terrain","src":"203 p. 443 ; 234 p. 461"},{"ask":"« Combien d'oreillers utilisez-vous la nuit ? Êtes-vous obligé de dormir à moitié assis ? »","why":"L'orthopnée (dyspnée de décubitus obligeant à surélever la tête) est plus spécifique de l'insuffisance cardiaque : redistribution du sang vers le thorax en décubitus avec hausse de pression capillaire pulmonaire.","flag":"orientation","src":"234 p. 461 ; 203 p. 443"},{"ask":"« Vous réveillez-vous la nuit en manquant d'air, obligé de vous lever ? »","why":"La dyspnée paroxystique nocturne est spécifique de l'IC : début d'œdème pulmonaire.","flag":"orientation","src":"234 p. 462"},{"ask":"« Êtes-vous plus gêné debout que couché ? »","why":"Platypnée (dyspnée en orthostatisme) associée à une désaturation : syndrome de platypnée-orthodéoxie, faisant chercher un shunt droite-gauche (foramen ovale perméable).","flag":"orientation","src":"203 p. 443, 452"},{"ask":"« Y a-t-il une saison, un lieu, un moment de la journée où c'est pire ? »","why":"Il faut rechercher les facteurs saisonniers, climatiques, environnementaux ou toxiques et l'horaire (asthme, exposition).","flag":"terrain","src":"203 p. 443"},{"ask":"« Est-ce plus difficile de faire entrer l'air ou de le faire sortir ? Entendez-vous un sifflement ? »","why":"Dyspnée inspiratoire (avec bradypnée inspiratoire, cornage, tirage) : cause laryngotrachéale ; dyspnée expiratoire avec sibilants : asthme, BPCO, ou pseudo-asthme cardiaque (bradypnée expiratoire sifflante).","flag":"orientation","src":"203 p. 444, 449-450 ; 234 p. 462"},{"ask":"« Vous toussez ? Plutôt à l'effort ou allongé ? »","why":"Une toux électivement à l'effort ou au décubitus doit faire évoquer une insuffisance cardiaque.","flag":"orientation","src":"234 p. 462"},{"ask":"« Est-ce de pire en pire, ou stable depuis des semaines ? »","why":"Aggravation progressive de la dyspnée devenue invalidante, avec apparition ou aggravation de signes congestifs (œdèmes) : forme moins aiguë d'insuffisance cardiaque aiguë. La dyspnée peut aussi aggraver une dyspnée chronique sur maladie cardiorespiratoire préexistante (EP).","flag":"gravite","src":"234 p. 472 ; 226 p. 504"}],"astuce":"Quatre mots pour caractériser : Début (aigu/chronique), Contexte (repos/effort), Position (orthopnée/platypnée), Phase (inspi/expi). Et NYHA pour dire sa gravité en un chiffre."},{"key":"associes","title":"Signes associés","goal":"Chercher les symptômes qui orientent vers le cœur, le poumon, l'embolie, l'ORL ou une cause extrathoracique.","questions":[{"ask":"« Avez-vous mal dans la poitrine ? Où, et comment ? »","why":"Une dyspnée aiguë associée à une douleur thoracique : l'EP est généralement associée à une douleur thoracique, le pneumothorax donne une douleur latérothoracique, la pneumopathie peut donner une douleur thoracique. Un SCA s'accompagne d'une dyspnée dans 10 % des cas ; dyspnée + douleur thoracique + radio normale : penser EP (item 230).","flag":"orientation","src":"203 p. 444, 447-448 ; 226 p. 504 ; 230 p. 154, 156"},{"ask":"« Toussez-vous ? Crachez-vous ? De quelle couleur ? »","why":"Expectoration rose saumonée et mousseuse : OAP. Expectoration purulente avec toux majorée : pneumopathie. Majoration de la toux, du volume ou de la purulence : exacerbation de BPCO.","flag":"orientation","src":"203 p. 446, 448 ; 234 p. 472"},{"ask":"« Avez-vous craché du sang ? »","why":"Les hémoptysies, rarement isolées, traduisent l'hypertension veineuse pulmonaire dans l'IC ; elles peuvent aussi accompagner une EP (infarctus pulmonaire).","flag":"orientation","src":"234 p. 462 ; 226 p. 504"},{"ask":"« Avez-vous de la fièvre, des frissons, perdu du poids ? »","why":"Signes généraux à rechercher : fièvre, frissons, amaigrissement ; la fièvre avec syndrome de condensation oriente vers la pneumopathie.","flag":"orientation","src":"203 p. 444, 449"},{"ask":"« Avez-vous les chevilles gonflées, pris du poids, le ventre ballonné ? »","why":"Prise de poids avec œdèmes, signes de rétention hydrosodée et d'IC. Le patient doit consulter si prise de 2-3 kg en 2-3 jours, orthopnée, œdèmes des membres inférieurs ou météorisme abdominal.","flag":"orientation","src":"234 p. 462, 476"},{"ask":"« Avez-vous des palpitations, un malaise, une syncope ? »","why":"Palpitations associées dans l'IC ; troubles du rythme supraventriculaires et TV peuvent s'accompagner d'une dyspnée ; la syncope dans l'EP témoigne d'une réduction sévère du flux systémique.","flag":"orientation","src":"234 p. 462 ; 203 p. 447 ; 226 p. 504"},{"ask":"« Avez-vous une douleur au côté droit du ventre, une pesanteur sous les côtes ? Une grande fatigue ? »","why":"Hépatalgie d'effort (puis de repos) par distension de la capsule hépatique dans l'insuffisance cardiaque droite ; fatigue de repos liée à l'hypotension artérielle ou à l'effort ; en IC sévère, troubles digestifs (douleurs abdominales, nausées, vomissements).","flag":"orientation","src":"234 p. 462"},{"ask":"« Avez-vous une jambe gonflée ou douloureuse ? »","why":"Signes de thrombose veineuse profonde à rechercher à l'examen cardiovasculaire complet (EP).","flag":"orientation","src":"203 p. 444 ; 226 p. 497"},{"ask":"« Avez-vous la voix modifiée, le visage ou les lèvres qui gonflent, une gêne à la gorge ? »","why":"Dysphonie fréquente en cas d'origine laryngée ; œdème de Quincke (œdème de la glotte) souvent dans un contexte de choc anaphylactique.","flag":"gravite","src":"203 p. 449"},{"ask":"« Avez-vous une faiblesse musculaire, une difficulté à parler ou à avaler ? »","why":"Atteinte neuromusculaire (bulbaire, polyradiculonévrite, myasthénie) : la dyspnée est tardive et peut précéder de peu l'arrêt respiratoire ; faiblesse musculaire aussi dans l'IC.","flag":"gravite","src":"203 p. 449 ; 234 p. 462"}],"astuce":"Un seul signe associé peut valoir un diagnostic : crachats roses = OAP, point de côté + alitement = EP, fièvre + crachats purulents = pneumopathie, voix qui change = larynx."},{"key":"orientation","title":"Les questions qui orientent","goal":"Suivre l'arbre décisionnel du Collège : choc, inspiratoire, expiratoire, crépitants, syndrome pleural, dyspnée isolée.","questions":[{"ask":"« Êtes-vous obligé de dormir assis ? Avez-vous craché des crachats roses et mousseux ? »","if":"Si oui → œdème aigu du poumon (OAP) cardiogénique","why":"OAP : orthopnée, wheezing, crépitants bilatéraux, expectoration rose saumonée, cardiopathie connue ; réponse au diurétique ou à la trinitrine IV en faveur. Origine cardiaque la plus fréquente.","src":"203 p. 446 ; 234 p. 472"},{"ask":"« Avez-vous des sifflements en expirant, une toux avec crachats, et vous fumez depuis des années ? »","if":"Si oui → BPCO exacerbée ou asthme","why":"Dyspnée expiratoire avec ronchi/sibilants oriente vers l'asthme ou la BPCO ; exacerbation sur surinfection bronchique ; hippocratisme digital possible. Attention : ne pas conclure à un OAP par excès chez un BPCO encombré.","src":"203 p. 447-449, 453"},{"ask":"« L'essoufflement est-il arrivé brutalement, avec un point de côté, après une immobilisation ? »","if":"Si oui → embolie pulmonaire","why":"EP : début très brutal, intensité variable, généralement douleur thoracique associée, auscultation souvent normale ; contexte favorisant. Une dyspnée isolée fait rechercher l'EP.","src":"203 p. 447, 449"},{"ask":"« Avez-vous de la fièvre, de la toux avec crachats purulents ? »","if":"Si oui → pneumopathie infectieuse","why":"Syndrome infectieux : fièvre + toux majorée ou expectoration purulente ou douleur thoracique ; foyer de crépitants ± condensation ; BNP normal ou peu augmenté.","src":"203 p. 448 ; 234 p. 472"},{"ask":"« C'est parti d'un coup, avec une douleur sur le côté, chez quelqu'un de grand et mince ? »","if":"Si oui → pneumothorax","why":"Pneumothorax : sujet longiligne, tabac, emphysème, début brutal parfois à l'effort, douleur latérothoracique, abolition des vibrations vocales et du murmure, tympanisme, hyperclarté à la radio.","src":"203 p. 448"},{"ask":"« L'air a du mal à entrer, vous avez un bruit en inspirant, la voix a changé ? »","if":"Si oui → cause laryngotrachéale (Quincke, corps étranger, tumeur trachéale)","why":"Dyspnée inspiratoire avec bradypnée, cornage, tirage ; dysphonie si laryngée. Garder le patient assis et éviter l'examen de l'oropharynx. Progressive, elle évoque une cause néoplasique.","src":"203 p. 449"},{"ask":"« L'essoufflement est-il isolé, sans toux, sans douleur, sans sifflement ? »","if":"Si oui → EP, sepsis sévère, anémie, acidose métabolique, ou psychogène par élimination","why":"Arbre décisionnel : dyspnée isolée sans choc, sans signe laryngé, sans expiratoire, sans crépitants, sans syndrome pleural. Les causes extrathoraciques donnent plus une polypnée qu'une dyspnée.","src":"203 p. 449-450, 453"},{"ask":"« L'essoufflement s'aggrave depuis des semaines avec les jambes qui gonflent et la prise de poids ? »","if":"Si oui → insuffisance cardiaque chronique décompensée","why":"Aggravation progressive de la dyspnée invalidante avec apparition ou aggravation de signes congestifs (œdèmes) ; un BNP normal rend l'IC peu probable.","src":"234 p. 472 ; 203 p. 451"},{"ask":"« Votre essoufflement a-t-il commencé avec un choc, un état de faiblesse, un malaise ? »","if":"Si oui → état de choc : la dyspnée s'efface devant la prise en charge du choc","why":"Dans la dyspnée avec état de choc, c'est le choc qu'il faut traiter d'abord (premier nœud de l'arbre décisionnel).","src":"203 p. 449-450"},{"ask":"« L'essoufflement apparaît-il seulement debout et s'améliore couché ? »","if":"Si oui → penser au syndrome de platypnée-orthodéoxie (shunt droite-gauche, FOP)","why":"Dyspnée en orthostatisme avec désaturation : chercher un shunt droite-gauche, notamment un foramen ovale perméable.","src":"203 p. 452"}],"astuce":"L'arbre en 6 questions : choc ? inspiratoire ? expiratoire ? crépitants ? syndrome pleural ? sinon dyspnée isolée = EP, sepsis, anémie, acidose, psychogène."},{"key":"examen","title":"Examen clinique ciblé","goal":"Caractériser la dyspnée à l'examen (fréquence, rythme, auscultation) et rechercher des signes d'IC ou de TVP.","questions":[{"ask":"Compter la fréquence respiratoire, observer le rythme","why":"Tachypnée/polypnée > 20/min, bradypnée < 10/min. Rythme : dyspnée de Kussmaul (acidose métabolique) ; Cheyne-Stokes (IC grave, bas débit aux centres respiratoires). Amplitude : hyperpnée ou hypopnée.","flag":"orientation","src":"203 p. 444"},{"ask":"Repérer la phase respiratoire concernée : inspiratoire, expiratoire ou les deux ; bruits associés (wheezing, cornage)","why":"Inspiratoire = laryngé ; expiratoire avec sibilants = asthme/BPCO. Orientation étiologique.","flag":"orientation","src":"203 p. 444, 449"},{"ask":"Ausculter les poumons : crépitants, sibilants, ronchi, murmure vésiculaire","why":"Crépitants bilatéraux, « marée montante » dans l'OAP ; sibilants en cas d'asthme, BPCO ou pseudo-asthme cardiaque ; abolition du murmure dans le pneumothorax ou l'asthme aigu grave ; foyer de crépitants dans la pneumopathie.","flag":"orientation","src":"203 p. 444 ; 234 p. 462, 472"},{"ask":"Percuter : matité ou tympanisme","why":"Anomalie de percussion : matité (épanchement pleural) ou tympanisme (pneumothorax).","flag":"orientation","src":"203 p. 444, 448 ; 230 p. 160"},{"ask":"Ausculter le cœur : B3 (galop), éclat de B2, souffles, rythme irrégulier","why":"IC : tachycardie souvent absente sous bêtabloquants, galop protodiastolique B3, éclat du B2 pulmonaire (HTAP), souffle d'IM/IT fonctionnelles ou valvulopathie organique. Tamponnade : bruits du cœur assourdis.","flag":"orientation","src":"234 p. 462-463 ; 203 p. 447"},{"ask":"Prendre la PA et le pouls","why":"PAS < 100 mmHg dans l'IC est un facteur de gravité ; la PA peut être élevée dans un OAP hypertensif. Tachycardie > 120/min = signe de gravité d'une dyspnée aiguë.","flag":"gravite","src":"234 p. 463 ; 203 p. 444"},{"ask":"Rechercher des signes d'insuffisance cardiaque droite : turgescence jugulaire, reflux hépatojugulaire, hépatomégalie, œdèmes, ascite","why":"Turgescence jugulaire (très spécifique, difficile chez l'obèse) et RHJ se recherchent demi-assis ; œdèmes mous, blancs, indolores, prenant le godet, déclives ; ascite souvent tardive.","flag":"orientation","src":"234 p. 463"},{"ask":"Chercher des signes de thrombose veineuse profonde","why":"Examen cardiovasculaire complet à la recherche d'IC et de TVP.","flag":"orientation","src":"203 p. 444 ; 226 p. 497"},{"ask":"Rechercher un pouls paradoxal et une tachycardie avec turgescence jugulaire et auscultation pulmonaire normale","why":"Tamponnade : orthopnée, tachycardie, bruits du cœur assourdis, poumons clairs, turgescence jugulaire, pouls paradoxal ; tableau de collapsus avec signes d'insuffisance ventriculaire droite.","flag":"gravite","src":"203 p. 447"},{"ask":"Examen ORL, thyroïdien et neuromusculaire ; chercher un hippocratisme digital","why":"Examens complémentaires cliniques de la dyspnée ; hippocratisme digital parfois dans la BPCO.","flag":"terrain","src":"203 p. 444, 448"}],"astuce":"Ton fil rouge à l'auscultation : Crépitants = poumon qui se noie (IVG, pneumopathie), Sibilants = bronches qui se ferment (asthme, BPCO, pseudo-asthme cardiaque), Silence = pneumothorax ou asthme aigu grave."},{"key":"gravite","title":"Signes de gravité (à chercher d'emblée)","goal":"Repérer un épuisement ventilatoire, une hypoxémie/hypercapnie ou une défaillance circulatoire avant d'aller plus loin.","questions":[{"ask":"Signes de lutte respiratoire : tirage sus-sternal ou sus-claviculaire, creusement intercostal, battement des ailes du nez, balancement thoracoabdominal, contracture expiratoire abdominale","why":"Mise en jeu des muscles respiratoires accessoires : signe d'épuisement ventilatoire.","flag":"gravite","src":"203 p. 444"},{"ask":"Cyanose, sueurs, tachycardie > 120/min, marbrures, angoisse, SpO2 < 90 %","why":"Signes de détresse ; une SpO2 < 90 % témoigne d'une hypoxémie et indique l'administration d'oxygène.","flag":"gravite","src":"203 p. 444-445"},{"ask":"Retentissement neurologique : astérixis, agitation, somnolence, coma","why":"Retentissement neurologique : encéphalopathie respiratoire (astérixis), agitation, somnolence, coma = signe de gravité d'une dyspnée aiguë.","flag":"gravite","src":"203 p. 444"},{"ask":"Asthme aigu grave : thorax bloqué en inflation, silence auscultatoire, pouls paradoxal, élocution impossible","why":"Les sibilants ne sont plus retrouvés ni le murmure vésiculaire : urgence vitale à distinguer de la crise simple.","flag":"gravite","src":"203 p. 447"},{"ask":"BPCO décompensée : dyspnée de repos, cyanose, désaturation, polypnée > 25/min, défaillance hémodynamique, signes neurologiques, hypercapnie","why":"Signes faisant évoquer une décompensation engageant le pronostic vital.","flag":"gravite","src":"203 p. 448"},{"ask":"OAP : polypnée, orthopnée, sueurs, cyanose, grésillement laryngé, tirage, crépitants qui montent","why":"Détresse respiratoire aiguë par inondation alvéolaire : une des grandes urgences cardiovasculaires, prise en charge immédiate, sans retarder le traitement pour les examens.","flag":"gravite","src":"234 p. 472"},{"ask":"Choc cardiogénique : PAS < 90 mmHg (ou chute > 30 mmHg pendant ≥ 30 min), extrémités froides, cyanosées, marbrées, oligurie < 20 mL/h, sueurs, altération de la conscience","why":"Tableau ultime de défaillance cardiaque avec mauvais pronostic : la dyspnée s'efface devant la prise en charge du choc.","flag":"gravite","src":"234 p. 473 ; 203 p. 449"},{"ask":"EP à haut risque : hypotension PAS < 90 mmHg ou baisse > 40 mmHg pendant plus de 15 minutes, choc ; signes de cœur pulmonaire","why":"Mortalité > 15 %. Risque intermédiaire (mortalité 3 à 15 %) : marqueurs de dysfonction du VD, troponine élevée ; autres signes de sévérité : tachycardie > 110, PAS < 100, FR ≥ 30/min, SpO2 < 90 %, trouble de la conscience. sPESI : 1 point par âge > 80, SpO2 < 90, PAS < 100, FC > 110, cancer, insuffisance cardiaque ou maladie pulmonaire chronique.","flag":"gravite","src":"226 p. 509"},{"ask":"Cause laryngée ou neuromusculaire : cornage, dysphonie, œdème de Quincke, polyradiculonévrite","why":"Leur gravité est fréquemment sous-estimée ; la dyspnée neuromusculaire est tardive et précède de peu l'arrêt respiratoire.","flag":"gravite","src":"203 p. 449, 453"}],"astuce":"Retiens la trilogie des gravités : ventiler (tirage, SpO2 < 90 %), circuler (choc, marbrures), penser (astérixis, coma). Si un des trois est atteint, on traite avant d'étiqueter."},{"key":"examens","title":"Examens de 1re intention","goal":"Prescrire en urgence le bon bilan, puis les examens de 2e intention selon l'orientation, sans en oublier un.","questions":[{"ask":"Gazométrie artérielle (hypoxémie, hypercapnie)","why":"Apprécie la gravité (insuffisance respiratoire) et parfois l'étiologie ; hypoxie-hypocapnie (effet shunt) dans l'EP et l'OAP. Une SpO2 < 90 % indique l'oxygène.","flag":"gravite","src":"203 p. 444-446 ; 234 p. 472 ; 226 p. 504"},{"ask":"ECG","why":"Cherche EP, coronaropathie, trouble du rythme (FA rapide), onde Q de nécrose. Dans l'EP : tachycardie sinusale, S1Q3, BBD, T négatives V1-V4. Peu contributif au diagnostic d'IC mais oriente l'étiologie.","flag":"orientation","src":"203 p. 445 ; 234 p. 463 ; 226 p. 504"},{"ask":"Radiographie thoracique","why":"Systématique devant une dyspnée aiguë. IC : cardiomégalie (RCT > 0,5), redistribution vasculaire, lignes de Kerley B, opacités floconneuses en ailes de papillon, épanchement pleural. Absence de cardiomégalie n'exclut pas l'IC (FE préservée). Radio normale n'élimine pas l'EP.","flag":"orientation","src":"203 p. 445 ; 234 p. 464-465 ; 226 p. 504"},{"ask":"BNP ou NT-proBNP","why":"En dyspnée aiguë : BNP < 100 ou NT-proBNP < 300 pg/mL rend l'IC très improbable ; ≥ 100 / ≥ 300 en faveur. Seuils en faveur d'une origine cardiaque selon l'âge : NT-proBNP > 450 pg/mL (< 50 ans pour l'item 234, < 55 ans pour l'item 203), > 900 pg/mL (50-75 ans ; 55-75 ans pour 203), > 1 800 pg/mL (> 75 ans). Seuils plus bas hors urgence : BNP < 35 / NT-proBNP < 125 pg/mL. Concentrations majorées par l'âge, l'insuffisance rénale, la FA ; diminuées par l'obésité.","flag":"orientation","src":"203 p. 445 ; 234 p. 465"},{"ask":"NFS-plaquettes, ionogramme sanguin, glycémie","why":"Bilan biologique de première intention de la dyspnée ; toujours éliminer une anémie avant de se lancer dans des bilans plus poussés. En cas d'IC : créatininémie, natrémie, kaliémie, bilan hépatique, TSH, ferritine/saturation transferrine, lipides, HbA1c.","flag":"terrain","src":"203 p. 445, 450 ; 234 p. 467"},{"ask":"Évaluer la probabilité d'EP (Wells ou Genève révisé), puis D-dimères","why":"D-dimères < 500 µg/L excluent l'EP si probabilité faible ou intermédiaire ; seuil adapté à l'âge après 50 ans (âge × 10). Inutiles si forte probabilité : angioscanner d'emblée. Probabilité de l'EP : faible 10 %, modérée 30 %, forte 65 % (texte) ; le tableau 19.2 (Genève révisé) indique < 10 %, 30-40 %, > 60 %.","flag":"orientation","src":"226 p. 505-506"},{"ask":"Angioscanner pulmonaire si EP probable ou D-dimères positifs ; échodoppler veineux des membres inférieurs","why":"Scanner multicoupe négatif exclut l'EP si probabilité faible/intermédiaire. Échodoppler : une TVP proximale suffit à confirmer l'EP ; un échodoppler normal ne l'élimine pas. Scintigraphie V/P en alternative.","flag":"orientation","src":"226 p. 506-507"},{"ask":"Échocardiographie-doppler","why":"Examen clé en cas d'IC : FEVG (≤ 40, 41-49, ≥ 50 %), étiologie, pressions de remplissage. Cœur pulmonaire aigu dans l'EP (dilatation VD, septum paradoxal) ; en EP à haut risque, elle suffit si scanner indisponible.","flag":"orientation","src":"234 p. 466 ; 226 p. 507"},{"ask":"Pour une dyspnée chronique : EFR + gazométrie, épreuve d'effort avec gaz respiratoires, scanner thoracique, cathétérisme cardiaque","why":"Le bilan peut se faire sans urgence ; l'épreuve d'effort métabolique oriente vers une cause plutôt cardiaque ou pulmonaire. Lorsque le diagnostic d'IC est suspecté, une échocardiographie doit être réalisée.","flag":"orientation","src":"203 p. 450-451"},{"ask":"Troponine ultrasensible et recherche d'un SCA si le contexte l'évoque","why":"Une élévation modérée de troponine peut se voir dans l'OAP même sans pathologie coronarienne aiguë ; mais un SCA peut déclencher l'IC aiguë.","flag":"terrain","src":"234 p. 472-473"}],"astuce":"Kit de la dyspnée aiguë à réciter : gaz du sang, ECG, radio, NFS, ionogramme, BNP, D-dimères. Le BNP bas rend l'IC très improbable ; les D-dimères négatifs excluent l'EP si la probabilité est faible ou intermédiaire."}],"synthese":"Madame M., 74 ans, hypertendue, consulte pour une dyspnée apparue en quelques jours, d'effort pour un étage (NYHA III), avec orthopnée et deux oreillers, sans fièvre ni douleur. FC 100, PA 150/90, SpO2 93 %, crépitants des deux bases, turgescence jugulaire, œdèmes des chevilles, pas de signe de TVP. Hypothèses : décompensation cardiaque gauche ou globale (OAP/subœdème) en premier, embolie pulmonaire (à éliminer par probabilité clinique et D-dimères), pneumopathie ou exacerbation de BPCO.","hypotheses":[{"dx":"OAP / insuffisance cardiaque décompensée","pour":"Cardiopathie ou HTA, orthopnée, DPN, crépitants bilatéraux, crachats roses saumonés, B3, œdèmes, BNP élevé, cardiomégalie/ailes de papillon","danger":true,"src":"203 p. 446 ; 234 p. 461-465, 472"},{"dx":"Embolie pulmonaire","pour":"Terrain (alitement, chirurgie, cancer, voyage), début brutal, douleur, dyspnée isolée, auscultation normale, tachycardie, hypoxie-hypocapnie, D-dimères/angioscanner","danger":true,"src":"203 p. 447 ; 226 p. 504-506"},{"dx":"Exacerbation de BPCO / crise d'asthme","pour":"Tabagisme, antécédents, dyspnée expiratoire avec sibilants, toux, expectoration, surinfection","danger":false,"src":"203 p. 447-448"},{"dx":"Pneumopathie infectieuse","pour":"Fièvre, toux, crachats purulents, foyer de crépitants, opacité systématisée","danger":false,"src":"203 p. 448"},{"dx":"Pneumothorax / épanchement pleural","pour":"Début brutal, longiligne, tabac, douleur latérale, tympanisme ou matité, abolition du murmure","danger":true,"src":"203 p. 448"},{"dx":"Tamponnade","pour":"Orthopnée, tachycardie, bruits assourdis, poumons clairs, turgescence jugulaire, pouls paradoxal","danger":true,"src":"203 p. 447"},{"dx":"Cause laryngotrachéale (Quincke, corps étranger)","pour":"Dyspnée inspiratoire, cornage, tirage, dysphonie, contexte allergique","danger":true,"src":"203 p. 449"},{"dx":"SDRA","pour":"Œdème lésionnel après pneumopathie, sepsis, inhalation, EP, traumatisme ; réanimation","danger":true,"src":"203 p. 448"},{"dx":"Anémie, acidose métabolique, sepsis sévère, cause psychogène","pour":"Dyspnée isolée ; polypnée plus que dyspnée ; psychogène par élimination","danger":false,"src":"203 p. 449, 453"}],"pieges":["L'OAP est souvent porté par excès chez un BPCO encombré (crépitants ≠ toujours cœur).","Pseudo-asthme cardiaque : sibilants et orthopnée, c'est un équivalent d'OAP, pas un asthme.","EP sur terrain bronchoemphysémateux : auscultation souvent normale, dyspnée isolée.","Radio de thorax normale n'élimine pas l'EP ; BNP bas rend l'IC improbable.","Cardiomégalie absente n'exclut pas l'IC (FE préservée).","Gravité des causes laryngées et neuromusculaires fréquemment sous-estimée.","Dyspnée de choc : on traite le choc d'abord ; oublier les examens de 1re intention est inacceptable."],"src":"203 p. 441-453 ; 234 p. 458-477 ; 226 p. 495-509"},{"id":"palpitations","spe":"cardio","title":"Palpitations","emoji":"💓","items":["237","232","231","236"],"hook":"Un symptôme banal qui peut cacher une tachycardie ventriculaire : avant de chercher la cause, tu cherches ce qui peut tuer (terrain, tolérance, ECG).","intro":"Les palpitations sont une perception subjective, très peu spécifique : de la tachycardie sinusale sans gravité à la TV qui menace la vie. Ton interrogatoire fait le plus gros du travail et tu poursuis toujours le même objectif : obtenir un ECG pendant la crise (la corrélation électroclinique). Ordre de réflexion : gravité d'abord, cardiopathie ensuite, cause extracardiaque en dernier.","steps":[{"key":"terrain","title":"Terrain et antécédents","goal":"Repérer en 2 minutes si le cœur est déjà malade, s'il y a un risque génétique de mort subite, et ce que le patient prend ou consomme.","questions":[{"ask":"« Avez-vous déjà eu un infarctus, de la tension, une maladie du muscle cardiaque ou une autre maladie du cœur ? »","why":"Un antécédent d'infarctus, d'HTA ou de cardiopathie fait suspecter une cardiopathie sous-jacente : c'est un critère d'anamnèse alarmante.","flag":"gravite","src":"237 p. 420"},{"ask":"« Vous a-t-on déjà dit que vous aviez un trouble du rythme ? Avez-vous un pacemaker ou un défibrillateur ? »","why":"Un trouble du rythme connu ou un appareillage (stimulateur, défibrillateur) fait partie de l'anamnèse alarmante.","flag":"gravite","src":"237 p. 420"},{"ask":"« Dans votre famille, quelqu'un est-il mort brutalement, surtout enfant, adolescent ou avant 35 ans ? »","why":"Un antécédent familial de mort subite avant 35 ans (ou du nourrisson) oriente vers une arythmie génétique : Brugada, QT long, dysplasie arythmogène du ventricule droit. Il faut faire l'arbre généalogique.","flag":"gravite","src":"237 p. 420"},{"ask":"« Prenez-vous un médicament pour le rythme du cœur, ou un traitement qui peut allonger le QT ? »","why":"Un antiarythmique ou un traitement allongeant le QT est un facteur de gravité (risque de torsade de pointes).","flag":"gravite","src":"237 p. 420, 231 p. 404"},{"ask":"« Prenez-vous des hormones thyroïdiennes, des médicaments type sympathomimétiques (décongestionnants, bronchodilatateurs) ? »","why":"Sympathomimétiques et hormones thyroïdiennes sont des causes extracardiaques à rechercher.","flag":"terrain","src":"237 p. 422"},{"ask":"« Combien d'alcool, de tabac, de café par jour ? Avez-vous déjà pris de la cocaïne, des amphétamines ou d'autres drogues ? »","why":"Les excitants (alcool, tabac, cocaïne, amphétamines) sont des causes extracardiaques classiques de palpitations.","flag":"terrain","src":"237 p. 422"},{"ask":"« (Chez une femme) Existe-t-il une possibilité de grossesse ? »","why":"Les signes de grossesse sont à rechercher parmi les causes extracardiaques ; la β-hCG fait partie des tests biologiques de routine.","flag":"terrain","src":"237 p. 422"},{"ask":"« Avez-vous de l'hypertension, du diabète, un surpoids important, de l'apnée du sommeil (ronflements, fatigue malgré une nuit complète) ? »","why":"Chez le patient obèse, diabétique ou hypertendu, il existe une association entre extrasystoles et FA (holters à répéter) ; obésité, diabète, HTA et SAOS sont des facteurs de prédisposition modifiables de la FA ; le SAOS est aussi une cause extracardiaque de palpitations.","flag":"terrain","src":"237 p. 422, 427 ; 232 p. 332-333"},{"ask":"« Quelqu'un de votre famille a-t-il une fibrillation atriale ? »","why":"Un antécédent de FA chez un apparenté du 1er degré augmente de 40 % la probabilité d'atteinte.","flag":"terrain","src":"232 p. 333"}],"astuce":"Trois blocs de terrain : mon cœur (cardiopathie, rythme connu, appareil), ma famille (mort subite jeune), mes produits (médicaments, excitants, grossesse)."},{"key":"symptome","title":"Le symptôme, décortiqué","goal":"Reconstituer l'épisode comme un enregistrement : forme, durée, début, fin, rythme. Chaque réponse oriente vers un mécanisme.","questions":[{"ask":"« Pouvez-vous me montrer en tapotant sur la table ce que vous sentez ? »","why":"Il est souvent utile de faire mimer la perception en tapotant du doigt sur le bord d'une table (le rythme perçu orientera : régulier, irrégulier, rapide).","flag":"orientation","src":"237 p. 420"},{"ask":"« Combien de temps dure un épisode : quelques secondes, minutes, heures ? »","why":"La durée de l'épisode (secondes, minutes, heures) fait partie des points obligatoires de l'interrogatoire.","flag":"orientation","src":"237 p. 419"},{"ask":"« Comment ça démarre et comment ça s'arrête : d'un coup, comme un interrupteur, ou progressivement ? »","why":"Un début brutal et une fin brutale évoquent une tachycardie jonctionnelle ; un début et une fin progressifs évoquent plutôt une tachycardie sinusale.","flag":"orientation","src":"237 p. 419, 422, 428"},{"ask":"« C'est présent en permanence ou par crises ? »","why":"Il faut préciser le caractère permanent ou paroxystique des palpitations.","flag":"orientation","src":"237 p. 419"},{"ask":"« Qu'est-ce qui déclenche les crises : un effort, une émotion, un changement brusque de position, de l'alcool ? Ou ça vient au repos ? »","why":"On cherche un facteur déclenchant et on précise effort ou repos. Un démarrage au changement brusque de position évoque une tachycardie jonctionnelle ; des palpitations uniquement à l'effort justifient une épreuve d'effort.","flag":"orientation","src":"237 p. 419, 422"},{"ask":"« À quelle fréquence ça arrive : tous les jours, toutes les semaines, quelques fois par an ? »","why":"La fréquence des crises est à préciser et conditionne l'enregistrement : holter 24-96 h si les palpitations sont fréquentes, ECG ambulatoire de longue durée (jusqu'à 21 jours) si < 1 fois/semaine, holter implantable si les crises sont peu fréquentes.","flag":"orientation","src":"237 p. 419, 423-424"},{"ask":"« Quand vous prenez votre pouls ou que vous tapotez, c'est régulier comme un métronome ou irrégulier ? »","why":"Le caractère régulier ou irrégulier des sensations est un élément d'orientation. Sur l'ECG en tachycardie : régulière à QRS fins = jonctionnelle, sinusale, flutter ou tachycardie atriale ; régulière à QRS larges = TV ou tachycardie supraventriculaire avec anomalie de conduction ; irrégulière = FA.","flag":"orientation","src":"237 p. 419, 423"},{"ask":"« Avez-vous la sensation que le cœur bat trop fort, trop vite, ou qu'il se débat dans la poitrine ? »","why":"Les palpitations sont la sensation que le cœur bat trop fort, trop vite ou irrégulièrement ; l'éréthisme cardiaque est à préciser.","flag":"orientation","src":"237 p. 419-420"},{"ask":"« Où le sentez-vous : dans le cou, dans la poitrine, sur le côté ? »","why":"La localisation n'est pas spécifique mais des battements ressentis dans le cou peuvent accompagner une tachycardie par réentrée intranodale.","flag":"terrain","src":"237 p. 419, 429"},{"ask":"« À la fin d'une crise, avez-vous eu une grosse envie d'uriner ? »","why":"Une crise polyurique finale évoque une tachycardie jonctionnelle.","flag":"orientation","src":"237 p. 422, 429"},{"ask":"« Avez-vous déjà réussi à arrêter une crise en toussant, en soufflant fort bouche fermée ou en buvant de l'eau froide ? »","why":"Une crise arrêtée par manœuvre vagale est très évocatrice d'une tachycardie jonctionnelle (Valsalva, boisson d'eau froide).","flag":"orientation","src":"237 p. 421, 429, 231 p. 390"}],"astuce":"Le trio qui fait gagner du temps : durée, début/fin (brutal ou progressif), régulier ou irrégulier. Avec ça, tu as déjà 3 à 4 hypothèses."},{"key":"associes","title":"Signes associés","goal":"Chercher ce qui accompagne les palpitations : un symptôme plus grave peut passer devant (syncope, douleur thoracique, dyspnée) et orienter vers une cause extracardiaque.","questions":[{"ask":"« Avez-vous eu mal ou une gêne dans la poitrine pendant les palpitations ? »","why":"Un angor, parfois fonctionnel, est un signe de gravité et peut accompagner une FA ou une tachycardie rapide.","flag":"gravite","src":"237 p. 420, 232 p. 330"},{"ask":"« Étiez-vous essoufflé, plus que d'habitude pour monter des escaliers ? »","why":"Une dyspnée est un signe d'insuffisance cardiaque ; la dyspnée d'effort est un symptôme usuel de la FA.","flag":"gravite","src":"237 p. 420, 232 p. 330"},{"ask":"« Avez-vous eu un malaise, des vertiges, failli tomber dans les pommes ou perdu connaissance ? »","why":"Une syncope ou une lipothymie traduit une mauvaise tolérance (baisse du débit) ; elle prend le pas sur les palpitations.","flag":"gravite","src":"237 p. 420"},{"ask":"« Avez-vous eu une faiblesse d'un bras ou d'une jambe, des difficultés à parler, des troubles visuels ? »","why":"Des signes neurologiques évoquent un infarctus cérébral par embolie sur fibrillation atriale.","flag":"gravite","src":"237 p. 420, 232 p. 330"},{"ask":"« Êtes-vous fatigué sans raison, sans énergie à l'effort ? »","why":"L'asthénie inexpliquée et l'angor fonctionnel sont des symptômes usuels de la FA ; les signes peuvent être absents ou intermittents.","flag":"terrain","src":"232 p. 330"},{"ask":"« Avez-vous de la fièvre, des diarrhées, des vomissements, des saignements récents ? »","why":"Fièvre et déshydratation sont des causes extracardiaques de palpitations (tachycardie sinusale adaptative).","flag":"terrain","src":"237 p. 422, 428"},{"ask":"« Avez-vous un problème de thyroïde ? Prenez-vous des hormones thyroïdiennes ? »","why":"L'hyperthyroïdie et la prise d'hormones thyroïdiennes font partie des causes extracardiaques à rechercher devant des palpitations ; l'hyperthyroïdie est aussi un facteur de prédisposition modifiable de la FA.","flag":"terrain","src":"237 p. 422 ; 232 p. 332"},{"ask":"« Ressentez-vous de l'angoisse, de l'oppression, des sueurs, la peur de mourir pendant les crises ? »","why":"Les causes psychiatriques (névrose cardiaque, attaques de panique) sont à envisager si le bilan cardiaque est normal. L'anxiété est aussi une cause d'extrasystoles.","flag":"orientation","src":"237 p. 418, 426, 435"},{"ask":"« Avez-vous des chutes inexpliquées, des accès de faiblesse, des bouffées de chaleur ? »","why":"Chez la personne âgée, la FA peut se manifester de façon trompeuse : lipothymies, chutes inexpliquées, impression que le cœur bat trop lentement, bouffées de chaleur, œdèmes.","flag":"terrain","src":"232 p. 330"}],"astuce":"Palpitations plus un de ces signes : douleur, dyspnée, malaise, déficit. Chacun est un signe de mauvaise tolérance et change complètement la prise en charge."},{"key":"orientation","title":"Les questions qui orientent","goal":"Sortir 2 ou 3 hypothèses avant même l'ECG, grâce aux réponses qui discriminent.","questions":[{"ask":"« C'est parti d'un coup, il y a eu une vraie envie d'uriner à la fin, et ça s'arrête d'un coup ? »","if":"Si oui → pense à la tachycardie jonctionnelle (maladie de Bouveret)","why":"Début et fin brutaux, polyurie finale, arrêt par manœuvre vagale ou adénosine : tableau typique de la réentrée intranodale, chez un sujet jeune à cœur sain.","flag":"orientation","src":"237 p. 422, 429"},{"ask":"« Vous êtes jeune ? Vous avez déjà eu un ECG qui montrait quelque chose de particulier ? »","if":"Si pré-excitation à l'ECG → pense à une voie accessoire (Wolff-Parkinson-White)","why":"Les tachycardies sur voie accessoire touchent de jeunes patients à cœur sain. Attention au risque de FA rapide avec lipothymie, syncope ou mort subite.","flag":"orientation","src":"237 p. 431-434"},{"ask":"« C'est irrégulier, avec des coups plus forts, des pauses ? Ou irrégulier en continu ? »","if":"Si irrégulier → pense aux extrasystoles ou à la fibrillation atriale","why":"Les extrasystoles sont des activations prématurées, isolées, bigéminées ou trigéminées ; la FA est une tachycardie irrégulière, dont la dyspnée d'effort est un symptôme usuel.","flag":"orientation","src":"237 p. 426 ; 232 p. 328, 330"},{"ask":"« Ça monte et ça descend progressivement, avec la fièvre, de l'alcool, une anémie ? »","if":"Si progressif et contexte → tachycardie sinusale adaptative","why":"Début et fin progressifs, FC > 100 au repos : tachycardie sinusale, réponse physiologique à une cause (fièvre, sepsis, anémie, hypovolémie, hypoxie, hyperthyroïdie, grossesse, sevrage alcoolique, sevrage brutal en bêtabloquants, médicaments).","flag":"orientation","src":"237 p. 428-429"},{"ask":"« Avez-vous arrêté brutalement un bêtabloquant ou de l'alcool ? Pris un nouveau médicament ? »","if":"Si oui → tachycardie sinusale adaptative (sevrage, médicament)","why":"Sevrage brutal en bêtabloquants, sevrage alcoolique et médicaments (sympathomimétiques, vasodilatateurs, atropiniques) sont des causes de tachycardie sinusale.","flag":"orientation","src":"237 p. 428-429"},{"ask":"« Les palpitations surviennent seulement pendant un effort ? »","if":"Si oui → épreuve d'effort pour les reproduire et éliminer un angor","why":"L'épreuve d'effort reproduit les palpitations survenant exclusivement à l'effort et documente un doute sur un angor.","flag":"orientation","src":"237 p. 422, 424"},{"ask":"« Avez-vous eu une syncope pendant ou juste après les palpitations ? Le cœur ralentit-il parfois fortement entre les crises ? »","if":"Si alternance rapide et lent chez un sujet âgé → pense à la maladie de l'oreillette (syndrome tachycardie-bradycardie)","why":"FA paroxystique associée à une dysfonction sinusale ; les médicaments bradycardisants sont périlleux, d'où le recours fréquent à un stimulateur.","flag":"orientation","src":"232 p. 338, 236 p. 346"},{"ask":"« Les crises durent-elles des heures, avec des palpitations persistantes et une dyspnée inhabituelle, chez un patient de 50-60 ans hypertendu ? »","if":"Si oui → pense à la fibrillation atriale","why":"Un quinquagénaire qui se plaint de palpitations avec angor fonctionnel ou dyspnée d'effort est le tableau typique de FA ; l'HTA est la cause la plus fréquente.","flag":"orientation","src":"232 p. 328, 333, 337"},{"ask":"« Tous les examens ont été normaux et vous avez beaucoup d'angoisse ? »","if":"Si bilan strictement normal → pense à la névrose cardiaque (avis psychiatrique)","why":"Diagnostic évoqué quand les examens cliniques et paracliniques sont normaux, avec ECG strictement normal pendant les symptômes ; il faut savoir stopper les investigations.","flag":"orientation","src":"237 p. 435"}],"astuce":"Brutal-brutal-pipi = jonctionnelle. Irrégulier = FA ou extrasystoles. Progressif avec contexte = sinusale. Normal partout + angoisse = névrose cardiaque, en dernier."},{"key":"examen","title":"Examen clinique ciblé","goal":"Évaluer la tolérance, chercher une cardiopathie sous-jacente et les causes extracardiaques.","questions":[{"ask":"Prendre la fréquence cardiaque et la pression artérielle","why":"Une FC > 150 bpm, une hypotension ou des signes d'hypoperfusion sont des signes cliniques de gravité.","flag":"gravite","src":"237 p. 420"},{"ask":"Ausculter le cœur : rythme régulier ou irrégulier, souffle","why":"L'auscultation retrouve des bruits du cœur irréguliers et un rythme plus ou moins rapide en cas de FA ; on cherche aussi des signes en faveur d'une cardiopathie sous-jacente.","flag":"orientation","src":"232 p. 331"},{"ask":"Évaluer la tolérance : diurèse, fréquence respiratoire, état de conscience","why":"La prise en charge initiale apprécie la tolérance : fréquence cardiaque, PA, diurèse, fréquence respiratoire, état de conscience.","flag":"gravite","src":"232 p. 331"},{"ask":"Chercher un OAP ou des signes d'insuffisance cardiaque (râles crépitants, œdèmes)","why":"On recherche d'emblée une complication de la FA : OAP ou signes d'insuffisance cardiaque.","flag":"gravite","src":"232 p. 331"},{"ask":"Examen artériel et neurologique","why":"On recherche une embolie artérielle systémique (examen artériel et neurologique).","flag":"gravite","src":"232 p. 331"},{"ask":"Prendre la température, chercher une déshydratation","why":"Fièvre et déshydratation sont des facteurs déclenchants et des causes de tachycardie sinusale.","flag":"terrain","src":"237 p. 422, 232 p. 331"},{"ask":"Chercher des signes d'hyperthyroïdie et de grossesse","why":"Hyperthyroïdie et signes de grossesse font partie de la recherche d'une cause extracardiaque.","flag":"terrain","src":"237 p. 422"},{"ask":"Pendant une crise : faire une manœuvre vagale (Valsalva, eau froide) sous ECG","why":"Elle bloque transitoirement le nœud AV : arrêt brutal = tachycardie jonctionnelle ; ralentissement qui démasque l'activité atriale = FA, flutter, tachycardie atriale ; pas d'effet = TV. Ne pas faire de compression carotidienne en cas d'athérome ou de souffle carotidien.","flag":"orientation","src":"237 p. 421, 231 p. 390"}],"astuce":"Pouls, tension, cœur, poumons, artères/neuro, température : 6 gestes pour juger la tolérance et dépister la complication."},{"key":"gravite","title":"Signes de gravité (à chercher d'emblée)","goal":"Éliminer l'arythmie ventriculaire potentiellement létale (TV, FV) avant tout le reste.","questions":[{"ask":"Antécédent d'infarctus, d'HTA ou de cardiopathie, trouble du rythme connu, stimulateur ou défibrillateur","why":"Antécédents personnels qui rendent l'anamnèse alarmante.","flag":"gravite","src":"237 p. 420"},{"ask":"Mort subite dans la famille, surtout enfant ou adolescent, ou avant 35 ans","why":"Oriente vers une arythmie génétique : Brugada, QT long, dysplasie arythmogène du VD. Faire l'arbre généalogique.","flag":"gravite","src":"237 p. 420"},{"ask":"Traitement antiarythmique ou allongeant le QT","why":"Facteur de gravité d'anamnèse (risque de torsade de pointes).","flag":"gravite","src":"237 p. 420"},{"ask":"Tachycardie > 150 bpm, hypotension artérielle ou signes d'hypoperfusion périphérique","why":"Signes cliniques de mauvaise tolérance : baisse du débit cardiaque.","flag":"gravite","src":"237 p. 420"},{"ask":"Angor (même fonctionnel), dyspnée ou signes d'insuffisance cardiaque","why":"Mauvaise tolérance ou complication de l'arythmie.","flag":"gravite","src":"237 p. 420"},{"ask":"Signes neurologiques d'infarctus cérébral, trouble de conscience","why":"Embolie sur fibrillation atriale, ou bas débit.","flag":"gravite","src":"237 p. 420"},{"ask":"Syncope ou lipothymie","why":"Signe de gravité clinique ; le malaise prend le pas sur les palpitations.","flag":"gravite","src":"237 p. 420"},{"ask":"ECG : tachycardie régulière à QRS larges","why":"TV jusqu'à preuve du contraire : urgence absolue, se préparer à réanimer.","flag":"gravite","src":"237 p. 421, 231 p. 398"},{"ask":"ECG : anomalie de repolarisation faisant craindre un SCA, ou tachycardie à QRS fins > 150 bpm avec signes de gravité","why":"Autres anomalies ECG graves ; le tableau peut correspondre à un angor fonctionnel, surtout si FC > 200 bpm.","flag":"gravite","src":"237 p. 421"},{"ask":"ECG : extrasystoles ventriculaires à couplage court (phénomène R/T), QT long, aspect de Brugada, pré-excitation","why":"Le couplage court est un indicateur majeur de risque rythmique (démarrage d'une arythmie ventriculaire maligne). Brugada, QT long (torsade de pointes) et pré-excitation sont des aspects à rechercher sur l'ECG de repos ; une FA rapide sur voie accessoire (super-Wolff) expose à lipothymie, syncope, mort subite.","flag":"gravite","src":"237 p. 422, 427-428, 434"}],"astuce":"Gravité = terrain (cœur malade, famille, médicaments) + tolérance (FC > 150, PA, angor, dyspnée, neuro, syncope) + ECG (QRS larges réguliers = TV)."},{"key":"examens","title":"Examens de 1re intention","goal":"Attraper le rythme et chercher la cardiopathie ou la cause extracardiaque. Le but ultime : la corrélation électroclinique.","questions":[{"ask":"ECG 12 dérivations, systématique","why":"Pierre angulaire du diagnostic. Le plus souvent normal, mais à faire toujours : il peut montrer des signes d'orientation (extrasystoles, pré-excitation, Brugada, QT long, cardiopathie ischémique ou hypertrophique). On cherche un tracé pendant la crise.","flag":"orientation","src":"237 p. 421-422"},{"ask":"Échocardiographie transthoracique systématique","why":"Recherche une cardiopathie sous-jacente (cinétique VG, FEVG, cardiopathie dilatée ou hypertrophique, taille des oreillettes).","flag":"orientation","src":"237 p. 421"},{"ask":"Biologie : ionogramme, NFS, alcoolémie, bêta-hCG, TSH","why":"Tests de routine à la recherche d'une cause extracardiaque (troubles ioniques, anémie, alcool, grossesse, hyperthyroïdie).","flag":"terrain","src":"237 p. 422"},{"ask":"Si FA découverte : ionogramme, créatinine, TSHus, NFS, radiographie de thorax, échographie","why":"Bilan étiologique et biologique de première intention de la FA.","flag":"orientation","src":"232 p. 332-333"},{"ask":"Holter ECG 24 à 96 h si les palpitations sont fréquentes","why":"Plus l'enregistrement est long, meilleure est la sensibilité ; adapter à la fréquence des crises.","flag":"orientation","src":"237 p. 422-423, 231 p. 415"},{"ask":"ECG ambulatoire de longue durée (jusqu'à 21 jours) si palpitations < 1 fois par semaine","why":"Intéressant en cas de palpitations peu fréquentes, par exemple pour dépister une FA paroxystique.","flag":"orientation","src":"237 p. 424"},{"ask":"Holter implantable (3 à 5 ans) ou montre connectée si crises peu fréquentes","why":"Permet d'établir la corrélation électroclinique ; la montre ECG simple piste (D1) enregistre automatiquement ou à l'action du patient. Le diagnostic de FA par photopléthysmographie reste non valide.","flag":"orientation","src":"237 p. 424, 232 p. 329"},{"ask":"Épreuve d'effort si palpitations à l'effort ou doute sur un angor","why":"Double intérêt : reproduire les palpitations et dépister une ischémie.","flag":"orientation","src":"237 p. 424"},{"ask":"Étude électrophysiologique endocavitaire, IRM myocardique, coronarographie (sur avis spécialisé)","why":"Selon le contexte : l'EEP confirme une dualité nodale ou une voie accessoire et traite dans le même temps ; IRM et coronarographie selon la suspicion.","flag":"orientation","src":"237 p. 424-426"}],"astuce":"Pas d'ECG en crise ? Choisis l'enregistrement selon la fréquence : crises quotidiennes = holter, hebdomadaires = 21 jours, rares = implantable ou montre."}],"synthese":"Mme L., 28 ans, sans antécédent ni traitement, consulte pour des épisodes de palpitations régulières et rapides de début et de fin brutaux, durant 20 minutes, avec envie d'uriner à la fin et arrêtés une fois par une boisson d'eau froide. Pas de syncope, de douleur thoracique ni d'antécédent familial de mort subite. Examen cardiovasculaire normal, PA 120/70, FC 70, ECG de repos normal, TSH normale. Hypothèses : tachycardie jonctionnelle par réentrée intranodale (principale), voie accessoire à éliminer, tachycardie sinusale ou cause extracardiaque peu probables ; on documente la crise (holter ou ECG longue durée).","hypotheses":[{"dx":"Tachycardie jonctionnelle (réentrée intranodale)","pour":"Sujet jeune à cœur sain, début et fin brutaux, polyurie finale, arrêt par manœuvre vagale, QRS fins réguliers 130-250 bpm","danger":false,"src":"237 p. 429-430"},{"dx":"Wolff-Parkinson-White (voie accessoire)","pour":"Jeune, PR court < 120 ms avec onde delta ; risque de FA rapide, syncope ou mort subite (super-Wolff)","danger":true,"src":"237 p. 431-434, 231 p. 411"},{"dx":"Tachycardie ventriculaire","pour":"Cardiopathie ou antécédent familial de mort subite, tachycardie régulière à QRS larges, syncope, FC > 150","danger":true,"src":"237 p. 421, 231 p. 398"},{"dx":"Fibrillation atriale ou flutter","pour":"Palpitations irrégulières, âge mûr, HTA, dyspnée d'effort, ECG sans onde P (FA)","danger":false,"src":"232 p. 328-331"},{"dx":"Extrasystoles (atriales ou ventriculaires)","pour":"Palpitations isolées, bigéminisme/trigéminisme, causes extracardiaques à chercher ; toute cardiopathie peut en donner : chercher une cardiopathie sous-jacente","danger":false,"src":"237 p. 426-428"},{"dx":"Tachycardie sinusale adaptative","pour":"Début et fin progressifs, contexte de fièvre, anémie, hypovolémie, hyperthyroïdie, grossesse, sevrage","danger":false,"src":"237 p. 428-429"},{"dx":"Torsade de pointes sur QT long","pour":"Traitement allongeant le QT, hypokaliémie, bradycardie extrême, QT long congénital","danger":true,"src":"231 p. 403-404"},{"dx":"Maladie de l'oreillette (tachycardie-bradycardie)","pour":"Sujet âgé, FA paroxystique, bradycardie sinusale, lipothymies ou syncopes","danger":false,"src":"232 p. 338, 236 p. 346"},{"dx":"Névrose cardiaque","pour":"Anxiété, attaques de panique, ECG strictement normal, tous examens normaux","danger":false,"src":"237 p. 435"}],"pieges":["Les palpitations s'effacent derrière une syncope, une douleur thoracique ou une dyspnée : traite d'abord ce symptôme.","Tachycardie régulière à QRS larges = TV jusqu'à preuve du contraire, même si le patient est bien toléré.","ECG de repos normal ne rassure pas : cherche toujours la corrélation électroclinique.","Pouls et description des palpitations corrèlent mal avec la FA réelle : il faut un ECG.","Adénosine : contre-indiquée en cas d'asthme et d'HTA non contrôlée (item 237, p. 421) ; l'item 231 (p. 390) cite asthme ou hypotension artérielle ; aussi en cas de FA sur voie accessoire (super-Wolff).","Ne conclus à la névrose cardiaque qu'après un bilan strictement normal."],"src":"237 p. 418-435 ; 232 p. 328-338 ; 231 p. 390, 398-404, 411, 415 ; 236 p. 346"},{"id":"syncope-malaise","spe":"cardio","title":"Syncope et malaise","emoji":"😵","items":["342","236","233","237"],"hook":"« Docteur, j'ai fait un malaise » : tout l'enjeu est de savoir si le cœur est malade, car la syncope peut être l'élément annonciateur d'une mort subite par tachycardie ventriculaire.","intro":"« Malaise » n'est pas un terme médical : c'est une plainte. Ton premier travail est de la traduire : y a-t-il eu une perte de connaissance brève (PDCB) ? Si oui, syncope, épilepsie ou PDCB psychogène ? Interrogatoire, examen et ECG résolvent plus de la moitié des cas : le but est de savoir s'il existe une cardiopathie sous-jacente et un risque de mort subite par trouble du rythme ventriculaire.","steps":[{"key":"terrain","title":"Terrain et antécédents","goal":"Savoir d'emblée si le cœur est malade, si la famille a un risque génétique et si un médicament ou une dysautonomie peut tout expliquer.","questions":[{"ask":"« Quel âge avez-vous ? »","why":"L'âge est un élément clé d'orientation, mais trompeur : une syncope vasovagale n'est pas réservée aux jeunes, ni exclue chez le sujet âgé.","flag":"terrain","src":"342 p. 318, 324"},{"ask":"« Avez-vous une maladie du cœur : infarctus, insuffisance cardiaque, cœur « fatigué » à l'échographie ? »","why":"Antécédent de cardiopathie, d'insuffisance cardiaque, d'infarctus ou FEVG altérée connue : critère de gravité. Le diagnostic final est le plus souvent une TV ou un BAV chez un patient avec antécédent (parfois très lointain) d'infarctus ou de cardiomyopathie dilatée.","flag":"gravite","src":"342 p. 318, 322, 324"},{"ask":"« Dans votre famille, y a-t-il eu des morts subites, surtout chez des jeunes ? »","why":"Un antécédent familial de mort subite oriente vers une cause génétique ; c'est un critère de gravité.","flag":"gravite","src":"342 p. 318, 322"},{"ask":"« Avez-vous un pacemaker ou un défibrillateur ? Depuis quand ? »","why":"La défaillance d'un stimulateur (sonde déplacée ou rompue, usure de la batterie) est une cause rythmique de syncope.","flag":"gravite","src":"342 p. 314"},{"ask":"« Prenez-vous des médicaments pour la tension, un diurétique, des dérivés nitrés, un traitement pour le cœur, des psychotropes ? Quelque chose a-t-il changé récemment ? »","why":"Les médicaments hypotenseurs (vasodilatateurs, inhibiteurs calciques, SRAA, diurétiques, psychotropes, antiparkinsoniens) sont une cause majeure d'hypotension orthostatique ; on cherche une modification récente. Bêtabloquants et autres bradycardisants (même en collyre) peuvent induire une dysfonction sinusale.","flag":"orientation","src":"342 p. 315, 318; 236 p. 346, 348"},{"ask":"« Avez-vous du diabète, une maladie de Parkinson ? »","why":"Diabète et Parkinson sont des causes de dysautonomie, donc d'hypotension orthostatique.","flag":"terrain","src":"342 p. 315, 318"},{"ask":"« Avez-vous déjà eu des malaises similaires, notamment avant 40 ans ? »","why":"L'interrogatoire retrouve souvent un passé ancien de syncopes répétées survenues avant l'âge de 40 ans dans les syncopes réflexes.","flag":"orientation","src":"342 p. 323"},{"ask":"« Avez-vous un rétrécissement de la valve aortique, une prothèse valvulaire mécanique ? »","why":"Un RA serré donne des syncopes à l'effort ; une thrombose de valve mécanique est une cause obstructive.","flag":"gravite","src":"342 p. 313-314; 233 p. 199"}],"astuce":"Terrain en 3 mots : cœur (cardiopathie, appareil, valve), famille (mort subite), médicaments et dysautonomie."},{"key":"symptome","title":"Le symptôme, décortiqué","goal":"Confirmer la perte de connaissance, puis reconstituer la scène avec les témoins : posture, déclencheur, prodromes, durée, réveil.","questions":[{"ask":"« Avez-vous perdu connaissance, ou était-ce juste une impression de malaise ? Vous souvenez-vous de la chute ? »","why":"Une PDCB associe amnésie, perte du contrôle de la motricité et perte de réactivité, de courte durée. Sans PDCB et avec prodromes seuls, c'est une lipothymie.","flag":"orientation","src":"342 p. 311"},{"ask":"« Dans quelle position étiez-vous : debout, assis, couché ? »","why":"La posture est à préciser. Une syncope survenue en position couchée est un critère de gravité (cause cardiaque).","flag":"gravite","src":"342 p. 318, 322"},{"ask":"« Que faisiez-vous : effort, repos, après un effort ? »","why":"L'activité guide : à l'effort ou juste après, cause cardiaque (RA, CMH obstructive, BAV à l'effort) ; après un effort, plutôt syncope réflexe.","flag":"gravite","src":"342 p. 313, 318, 320, 322"},{"ask":"« Qu'est-ce qui s'est passé juste avant : douleur, émotion, vue du sang, prise de sang, repas, chaleur, station debout prolongée, foule, transports ? »","why":"Facteurs déclenchants et situations propices à une syncope réflexe (vasovagale).","flag":"orientation","src":"342 p. 318, 323"},{"ask":"« Avez-vous eu des signes avant : nausées, sueurs froides, vue qui se brouille, jambes qui flanchent, tête vide, sensation de froid ? »","why":"Prodromes typiques de la syncope vasovagale. Sans prodrome, la syncope est dite « à l'emporte-pièce » ; l'ancienne « syncope de Stokes-Adams » (sans prodrome, avec pâleur, moins de 30 secondes, retour abrupt à la conscience) avait une cause généralement rythmique.","flag":"orientation","src":"342 p. 311, 316, 318"},{"ask":"« Avez-vous senti votre cœur battre vite ou irrégulièrement juste avant ? »","why":"Une syncope précédée de palpitations est un critère de gravité (arythmie).","flag":"gravite","src":"342 p. 316, 322"},{"ask":"« (Au témoin) Combien de temps a-t-il perdu connaissance ? Comment s'est-il réveillé : d'un coup ou progressivement ? »","why":"Durée et mode de réveil : récupération en 10-30 s pour la syncope, plusieurs minutes pour l'épilepsie. L'amnésie passagère peut égarer le patient sur la durée.","flag":"orientation","src":"342 p. 316, 318"},{"ask":"« (Au témoin) A-t-il fait des mouvements anormaux ? Ils ont commencé tout de suite ou après un moment ? Combien de secousses ? »","why":"En épilepsie : plus de 20 mouvements tonicocloniques synchrones, dès le début de la PDCB. En syncope : myoclonies inconstantes (moins de 10), tardives, asymétriques. Éviter le terme « syncope convulsivante ».","flag":"orientation","src":"342 p. 313, 316, 318"},{"ask":"« (Au témoin) Il était pâle ou bleu ? »","why":"Tégument normal ou pâle dans la syncope ; cyanosé dans l'épilepsie.","flag":"orientation","src":"342 p. 316"},{"ask":"« Vous êtes-vous mordu la langue ? Où ? Avez-vous des courbatures, des maux de tête, des douleurs musculaires après ? »","why":"Morsure du bord latéral de la langue, courbatures et douleurs musculaires évoquent une crise comitiale ; morsure du bout de la langue : syncope.","flag":"orientation","src":"342 p. 316, 318, 324"},{"ask":"« Cela s'est-il produit en vous rasant, en tournant la tête, avec un col serré ? Ou en urinant, en toussant, à la selle, en vomissant ? »","why":"Syndrome du sinus carotidien (striction cervicale) et syncopes situationnelles (miction, toux, défécation, vomissements, effort intense).","flag":"orientation","src":"342 p. 315, 323"},{"ask":"« Cela s'est-il produit en vous levant, ou juste après un repas ? »","why":"L'hypotension orthostatique survient dans les 1 à 3 minutes après le passage à l'orthostatisme ; elle est favorisée par la période postprandiale, l'effort, l'alitement.","flag":"orientation","src":"342 p. 315, 323"}],"astuce":"PDCB = trois pertes : souvenir (amnésie), contrôle de la motricité, réactivité. Reconstitue la scène en 5 mots : posture, activité, déclencheur, prodromes, réveil."},{"key":"associes","title":"Signes associés","goal":"Voir si le malaise n'est pas un autre symptôme déguisé (douleur thoracique, dyspnée) ou le signe d'une urgence non cardiaque.","questions":[{"ask":"« Aviez-vous mal dans la poitrine ? »","why":"Une douleur thoracique associée oriente vers des diagnostics prioritaires : le « malaise » peut en fait être une douleur thoracique, et la syncope peut être due à un syndrome coronarien aigu ou un infarctus.","flag":"gravite","src":"342 p. 318-320, 322"},{"ask":"« Étiez-vous essoufflé, brutalement ? »","why":"Une dyspnée brutale est un symptôme grave associé (critère de gravité) ; le « malaise » peut en fait être une dyspnée.","flag":"gravite","src":"342 p. 318-319, 322"},{"ask":"« Avez-vous eu un violent mal de tête ou mal au ventre ? »","why":"Céphalées sévères (hémorragie sous-arachnoïdienne) ou douleur abdominale sont des symptômes graves associés.","flag":"gravite","src":"342 p. 311-312, 322"},{"ask":"« Avez-vous eu des vertiges, une vision double, des difficultés à parler, une faiblesse d'un membre ? »","why":"Un déficit neurologique focal fait sortir du domaine des syncopes : urgence neurovasculaire ; l'AIT vertébrobasilaire est une cause très rare de PDCB.","flag":"gravite","src":"342 p. 311, 320"},{"ask":"« Avez-vous vomi, eu la diarrhée, saigné, peu bu récemment ? »","why":"Déplétion, hémorragie, déshydratation : causes d'hypotension orthostatique par hypovolémie.","flag":"orientation","src":"342 p. 313, 315"},{"ask":"« Vous êtes-vous blessé en tombant ? »","why":"Une chute avec traumatisme grave est un critère de gravité et à distinguer d'une PDCB d'origine traumatique.","flag":"gravite","src":"342 p. 311, 315, 322"},{"ask":"« Cela vous est-il arrivé en faisant des mouvements intenses et répétés du bras gauche ? »","why":"Un syndrome de vol sous-clavier donne un AIT déclenché par des mouvements répétés du membre supérieur gauche, avec une différence de PA entre les deux bras.","flag":"orientation","src":"342 p. 311-312"},{"ask":"« Avez-vous eu un sommeil perturbé, de l'alcool, arrêté un traitement, ou été exposé à des lumières clignotantes ? »","why":"Privation de sommeil, alcool, stimulation lumineuse, sevrage médicamenteux ou éthylique orientent vers une crise comitiale.","flag":"orientation","src":"342 p. 316, 318"}],"astuce":"Syncope + douleur thoracique, dyspnée, céphalée ou déficit : tu quittes le terrain de la syncope banale, et tu penses SCA, EP, HSA, AVC."},{"key":"orientation","title":"Les questions qui orientent","goal":"Classer le mécanisme : obstacle mécanique, rythmique, hypotension orthostatique, réflexe, ou PDCB non syncopale.","questions":[{"ask":"« Station debout prolongée, chaleur, émotion, douleur, avec des nausées et des sueurs avant ? »","if":"Si oui → syncope vasovagale","why":"Contexte typique : sujet jeune, anxieux, prodromes (nausées, vue trouble, faiblesse des jambes, sueurs, pâleur). C'est la syncope la plus fréquente sur cœur sain et ECG normal.","flag":"orientation","src":"342 p. 323"},{"ask":"« Vous vous êtes levé d'un coup, ou vous prenez un nouveau médicament pour la tension ? »","if":"Si oui → hypotension orthostatique","why":"Première cause de syncope : chute de PAS ≥ 20 mmHg ou de PAD ≥ 10 mmHg, ou PAS < 90 mmHg dans les 1 à 3 minutes. Souvent iatrogène (vasodilatateurs, diurétiques, psychotropes, antiparkinsoniens).","flag":"orientation","src":"342 p. 315, 323"},{"ask":"« C'est arrivé en vous rasant, avec une cravate ou un col serré, en tournant la tête ? »","if":"Si oui → syndrome du sinus carotidien (homme âgé)","why":"Syncope déclenchée par striction cervicale (baroréflexe). Attention : il s'agit du sinus (glomus) carotidien, pas du nœud sinusal.","flag":"orientation","src":"342 p. 315, 323"},{"ask":"« C'était pendant un effort, ou juste après ? Avez-vous une douleur dans la poitrine ou un essoufflement à l'effort ? »","if":"Si effort + souffle → pense au rétrécissement aortique serré ou à la CMH obstructive","why":"RA serré : syncope d'effort, avec dyspnée et angor d'effort (3 maîtres symptômes). CMH obstructive : syncope à l'effort ou juste après, avec souffle systolique éjectionnel au bord gauche du sternum.","flag":"orientation","src":"342 p. 313; 233 p. 199"},{"ask":"« Ça s'est passé couché, sans aucun signe avant, ou après des palpitations ? »","if":"Si oui → pense à une cause rythmique (TV, BAV, pause)","why":"Survenue à l'effort, en position couchée ou précédée de palpitations : on suspecte TV ou BAV, surtout chez un patient avec antécédent d'infarctus ou de cardiomyopathie dilatée.","flag":"gravite","src":"342 p. 324"},{"ask":"« Êtes-vous porteur d'un pacemaker ou d'un défibrillateur ? »","if":"Si oui → défaillance d'appareil à discuter","why":"Pauses cardiaques et signes de défaillance du stimulateur ou du défibrillateur font le diagnostic à l'ECG.","flag":"orientation","src":"342 p. 314, 319"},{"ask":"« (Au témoin) Le visage était bleu ? Il y a eu beaucoup de secousses dès le début ? Il est resté confus plusieurs minutes ? »","if":"Si oui → pense à une crise épileptique généralisée","why":"Cyanose, mouvements nombreux dès le début, récupération en plusieurs minutes, amnésie de fixation : arguments pour l'épilepsie. L'aura (déjà-vu, sensation épigastrique, hallucinations) la précède.","flag":"orientation","src":"342 p. 316"},{"ask":"« Les épisodes durent longtemps, les yeux sont fermés et résistent à l'ouverture, ça se répète dans la semaine ? »","if":"Si oui → pense à une PDCB psychogène","why":"Résistance à l'ouverture des yeux, durée > 15 minutes, répétition fréquente dans la même semaine ; rythme et PA normaux.","flag":"orientation","src":"342 p. 316"},{"ask":"« Vous avez vu un médecin qui a trouvé un bloc de branche ou un souffle ? »","if":"Si bloc bifasciculaire + syncope → hospitalisation avec télémétrie","why":"Un bloc bifasciculaire suggère un risque de BAV complet infrahissien (troisième branche qui dysfonctionne par intermittence), pouvant induire syncope voire mort subite : syncope + bloc bifasciculaire = hospitalisation en cardiologie avec télémétrie. Chez un patient cardiaque, un bloc de branche isolé ne suffit pas à affirmer le BAV paroxystique : une TV reste possible.","flag":"gravite","src":"231 p. 383 ; 236 p. 358"}],"astuce":"Quatre tiroirs : obstacle (RA, CMH, EP, tamponnade), rythme (TV, BAV, dysfonction sinusale), tension (orthostatique), réflexe (vasovagale, carotidien, situationnelle). Le reste : épilepsie, psychogène."},{"key":"examen","title":"Examen clinique ciblé","goal":"Repérer une cause mécanique, mesurer la tension couché puis debout, et éliminer un déficit neurologique.","questions":[{"ask":"Prendre la PA et le pouls couché après 5 à 10 min, puis debout à 1, 2 et 3 minutes","why":"Recherche l'hypotension orthostatique : chute ≥ 20 mmHg de PAS, ≥ 10 mmHg de PAD ou PAS < 90 mmHg. Des symptômes reproduits renforcent l'imputabilité.","flag":"orientation","src":"342 p. 318-319, 324"},{"ask":"Mesurer la PA tout de suite après la syncope, rechercher une hypotension prolongée","why":"Une hypotension prolongée au décours oriente vers une cause iatrogène ou réflexe.","flag":"orientation","src":"342 p. 318"},{"ask":"Ausculter le cœur : souffle systolique (RA, CMH), signes de cœur pulmonaire aigu, bruits assourdis d'une prothèse mécanique","why":"L'examen cardiovasculaire identifie souvent les causes mécaniques à ce stade. Un souffle systolique éjectionnel est un critère de gravité.","flag":"gravite","src":"342 p. 318, 322; 233 p. 199"},{"ask":"Palper un frémissement, chercher le choc de pointe et ausculter les carotides","why":"Un RA significatif donne un frémissement au foyer aortique et un souffle irradiant aux vaisseaux du cou. B2 aboli dans les RA serrés calcifiés.","flag":"orientation","src":"233 p. 199"},{"ask":"Examen neurologique : déficit focal, confusion prolongée, morsure latérale de langue","why":"Un déficit ou une altération prolongée de conscience fait sortir du domaine cardiovasculaire. Morsure profonde du bord latéral de la langue : crise comitiale.","flag":"gravite","src":"342 p. 318"},{"ask":"Mesurer la PA aux deux bras et chercher un souffle carotidien","why":"Une différence de PA entre les deux bras accompagne le vol sous-clavier ; le souffle carotidien contre-indique la compression carotidienne.","flag":"orientation","src":"342 p. 311-312; 231 p. 390"},{"ask":"Chercher des signes de cœur pulmonaire aigu (embolie pulmonaire)","why":"L'examen cardiovasculaire identifie souvent les causes mécaniques, dont les signes de cœur pulmonaire aigu. Attention : l'insuffisance cardiaque sévère n'est jamais une cause de syncope en soi (elle peut donner confusion ou trouble de conscience).","flag":"gravite","src":"342 p. 314, 318"},{"ask":"Glycémie capillaire","why":"L'hypoglycémie figure parmi les causes neurologiques de malaise (rang A) et de confusion mentale (désordre métabolique) : à éliminer.","flag":"terrain","src":"342 p. 309-310, 312"}],"astuce":"Le trio qui rapporte : PA couché-debout (3 minutes), auscultation cardiaque (souffle ?), examen neuro rapide."},{"key":"gravite","title":"Signes de gravité (à chercher d'emblée)","goal":"Décider qui reste hospitalisé et qui rentre : tout se joue sur le risque de mort subite par trouble du rythme ventriculaire.","questions":[{"ask":"Antécédent familial de mort subite à un jeune âge","why":"Critère justifiant un maintien aux urgences, en unité de syncope ou hospitalisation.","flag":"gravite","src":"342 p. 322"},{"ask":"Cardiopathie connue, insuffisance cardiaque, infarctus, FEVG altérée","why":"Critère de gravité. Attention au diagnostic de syncope vasovagale chez un cardiaque : diagnostic d'élimination, après prise en charge complète et examens spécialisés (EEP, MEI).","flag":"gravite","src":"342 p. 322, 325"},{"ask":"Syncope à l'effort, précédée de palpitations ou survenue en position couchée","why":"Caractéristiques de syncope cardiaque.","flag":"gravite","src":"342 p. 322"},{"ask":"Douleur thoracique, douleur abdominale, céphalées, dyspnée brutale, ou chute avec traumatisme grave","why":"Symptôme grave associé qui impose le maintien en milieu hospitalier.","flag":"gravite","src":"342 p. 322"},{"ask":"Souffle systolique éjectionnel","why":"Évoque RA ou CMH obstructive ; critère de gravité.","flag":"gravite","src":"342 p. 322"},{"ask":"ECG : dysfonction sinusale avec bradycardie < 40 bpm ou pauses > 3 s chez un patient éveillé","why":"Anomalie ECG qui fait le diagnostic.","flag":"gravite","src":"342 p. 319"},{"ask":"ECG : BAV complet ou Mobitz 2, bloc de branche alternant, TV, torsades, TSV rapide > 150 bpm","why":"Autres anomalies à valeur diagnostique immédiate ; le bloc alternant est un équivalent de BAV complet paroxystique infrahissien.","flag":"gravite","src":"342 p. 319; 236 p. 357"},{"ask":"ECG : brady 40-50 bpm ou pauses < 3 s, Mobitz 1, BBG, bloc bifasciculaire, WPW, ESV nombreuses, QT long, Brugada, HVG ou onde Q","why":"Anomalies d'orientation : BAV paroxystique, TV, torsade, FV ; ou séquelle d'infarctus.","flag":"gravite","src":"342 p. 319"},{"ask":"Hospitalisation urgente en cas de BAV 3, Mobitz 2, haut degré, bloc alternant, BSA 3 ou syncope avec trouble conductif à l'ECG","why":"Troubles conductifs à risque vital : surveillance au scope, soins intensifs de cardiologie.","flag":"gravite","src":"236 p. 358"},{"ask":"Retour à domicile possible : syncope réflexe évidente (épisodes identiques anciens), HTO corrigée, examen et ECG normaux, pas de cardiopathie","why":"Situations à risque faible autorisant le retour et une consultation ultérieure.","flag":"orientation","src":"342 p. 322"}],"astuce":"Maintien hospitalier si : famille, cœur malade, effort/palpitations/couché, symptôme grave associé, souffle, ECG anormal. Sinon, ECG normal + cœur sain + réflexe évident = retour possible."},{"key":"examens","title":"Examens de 1re intention","goal":"Voir le rythme, chercher la cardiopathie, puis choisir la 2e intention selon le risque.","questions":[{"ask":"ECG 12 dérivations chez tous","why":"Examen clé : certaines anomalies font le diagnostic (voir gravité), d'autres l'orientent. Plus de 50 % des causes sont identifiées dès l'interrogatoire, l'examen et l'ECG.","flag":"orientation","src":"342 p. 319-320"},{"ask":"Monitorage ECG aux urgences si cause cardiaque suspectée","why":"Le monitorage ECG externe est obligatoire aux urgences en cas de situation à risque vital avéré ou suspecté (causes cardiaques).","flag":"gravite","src":"342 p. 320"},{"ask":"Échocardiographie quasi systématique","why":"Peut faire le diagnostic (thrombose de valve, CMH obstructive, RA, EP) ou montrer une séquelle d'infarctus ; si FEVG altérée, un défibrillateur peut être proposé en prévention.","flag":"orientation","src":"342 p. 320; 233 p. 200"},{"ask":"BNP ou NT-proBNP, troponine, ionogramme et créatinine","why":"BNP/NT-proBNP et troponine sont utiles pour identifier une cause cardiaque. Ionogramme et créatinine font partie de l'enquête d'une dysfonction sinusale sévère symptomatique, et l'hyperkaliémie est une cause réversible de troubles conductifs.","flag":"orientation","src":"342 p. 320 ; 236 p. 346, 349, 358"},{"ask":"Épreuve d'effort si syncope pendant ou après un effort","why":"Pendant ou juste après l'effort : cause cardiaque (BAV à l'effort) ; après l'effort : plutôt réflexe.","flag":"orientation","src":"342 p. 320"},{"ask":"Holter ECG (24 h à 3 semaines) si syncopes fréquentes et patient non à haut risque","why":"Sensible pour la dysfonction sinusale et les BAV nodaux, mais un holter normal n'écarte pas un trouble ventriculaire ni un BAV hissien/infrahissien paroxystique.","flag":"orientation","src":"342 p. 320"},{"ask":"Massage du sinus carotidien si syncope réflexe probable sans cause identifiée","why":"Couché puis debout, 5 à 10 s, unilatéral. Positif si pause > 3 s ou chute de PAS > 50 mmHg reproduisant les symptômes. Contre-indiqué après AIT, AVC ou en cas de sténose carotidienne.","flag":"orientation","src":"342 p. 320"},{"ask":"Étude électrophysiologique endocavitaire si syncope non élucidée avec cardiopathie ou anomalie ECG (bloc bifasciculaire, BBG)","why":"Mesure l'intervalle HV (≥ 70 ms = atteinte infrahissienne, indication de stimulateur) et recherche une TV par stimulation ventriculaire programmée ; non proposée si cœur et ECG normaux.","flag":"orientation","src":"342 p. 320-321 ; 236 p. 357"},{"ask":"Test d'inclinaison (tilt-test), MAPA","why":"Le tilt-test reproduit les syncopes vasovagales mais est contesté dans les syncopes inexpliquées ; la MAPA peut suggérer une hypotension orthostatique.","flag":"orientation","src":"342 p. 321"},{"ask":"Moniteur ECG implantable (holter sous-cutané) si syncopes espacées et EEP négative","why":"Associe les symptômes à une anomalie ECG ; non indiqué si haut risque de mort subite (défibrillateur ou stimulateur).","flag":"orientation","src":"342 p. 322"}],"astuce":"Ordre : ECG puis écho puis holter avant EEP. Holter sous-cutané en fin de parcours si EEP négative. Cherche la cardiopathie, puis le mécanisme."}],"synthese":"M. R., 74 ans, hypertendu traité par trois antihypertenseurs dont un diurétique dont la dose a été augmentée il y a 10 jours, perd connaissance quelques secondes en se levant après le repas, avec sueurs et vision trouble avant, récupération rapide. Pas de douleur thoracique, de dyspnée ni de palpitations. Cœur et neuro normaux, PA couchée 145/80, debout à 1 min 115/70 avec vertiges reproduits, ECG normal. Hypothèses : hypotension orthostatique iatrogène (principale), syncope réflexe, cause cardiaque à ne pas oublier chez un sujet âgé avec écho systématique.","hypotheses":[{"dx":"Hypotension artérielle orthostatique","pour":"Au lever, postprandial, médicament hypotenseur récent, déshydratation ou dysautonomie, baisse de PAS ≥ 20 mmHg","danger":false,"src":"342 p. 315, 323-324"},{"dx":"Syncope vasovagale","pour":"Jeune, déclencheur (douleur, émotion, chaleur, station debout), prodromes, pâleur, récupération rapide, ECG normal","danger":false,"src":"342 p. 315, 323"},{"dx":"Syndrome du sinus carotidien / syncope situationnelle","pour":"Rasage, col serré, miction, toux, défécation, homme âgé","danger":false,"src":"342 p. 315, 323"},{"dx":"Rétrécissement aortique serré / CMH obstructive","pour":"Syncope à l'effort, souffle systolique éjectionnel, dyspnée et angor d'effort","danger":true,"src":"342 p. 313; 233 p. 199"},{"dx":"BAV paroxystique ou dysfonction sinusale","pour":"Sans prodrome, bloc de branche ou bifasciculaire, pauses > 3 s, bradycardie < 40, sujet âgé","danger":true,"src":"342 p. 314, 319; 236 p. 346, 358"},{"dx":"Tachycardie ventriculaire / torsade de pointes","pour":"Antécédent d'infarctus ou cardiomyopathie, FEVG altérée, palpitations avant, effort ou couché, QT long","danger":true,"src":"342 p. 314, 324; 231 p. 398-404"},{"dx":"Embolie pulmonaire / tamponnade","pour":"Dyspnée brutale, douleur thoracique, signes de cœur pulmonaire aigu, état de choc","danger":true,"src":"342 p. 313-314, 322"},{"dx":"Défaillance de stimulateur ou défibrillateur","pour":"Porteur d'appareil, pauses à l'ECG","danger":true,"src":"342 p. 314, 319"},{"dx":"Crise d'épilepsie généralisée","pour":"Aura, cyanose, > 20 secousses dès le début, morsure latérale, confusion de plusieurs minutes","danger":false,"src":"342 p. 316"},{"dx":"PDCB psychogène","pour":"Durée > 15 min, résistance à l'ouverture des yeux, répétitions fréquentes, ECG et PA normaux","danger":false,"src":"342 p. 316"}],"pieges":["Le mot « malaise » n'est pas un diagnostic : cherche la PDCB, sinon c'est peut-être une douleur thoracique, un vertige, une dyspnée.","L'insuffisance cardiaque sévère n'est jamais cause de syncope en soi ; elle donne confusion ou trouble de conscience.","Syncope vasovagale chez un cardiaque : diagnostic d'élimination, après bilan complet.","Les myoclonies de syncope sont brèves, tardives, peu nombreuses : ne dis pas « syncope convulsivante ».","Pouls « absent » rapporté par un témoin en panique : peu fiable, l'hypotension rend le pouls imperceptible.","Holter normal n'élimine pas une TV ni un BAV infrahissien paroxystique ; compression carotidienne contre-indiquée après AIT/AVC ou sténose."],"src":"342 p. 309-325 ; 236 p. 346, 357-358 ; 233 p. 199-200 ; 231 p. 383-384, 390 ; 237 p. 420"},{"id":"oedemes-mi","spe":"cardio","title":"Œdèmes des membres inférieurs","emoji":"🦵","items":["234","226","203"],"hook":"Une jambe gonflée : un seul côté, pense phlébite et embolie ; les deux côtés avec essoufflement, pense cœur. Dans les deux cas, ne rate pas ce qui peut tuer.","intro":"Le Collège cardio ne consacre pas d'item entier aux œdèmes des membres inférieurs, mais il en donne les deux grandes lectures cardiologiques : l'œdème bilatéral de l'insuffisance cardiaque (droite ou globale) et l'œdème unilatéral de la thrombose veineuse profonde. Les causes rénales, hépatiques ou lymphatiques ne sont que citées en diagnostic différentiel dans ces items : cette fiche reste dans le périmètre cardio. Ton état d'esprit : unilatéral ou bilatéral ? douloureux ou non ? signes d'IC ? et d'abord, risque d'embolie ?","steps":[{"key":"terrain","title":"Terrain et antécédents","goal":"Chercher une cardiopathie connue ou un contexte thrombogène, et ce qui a pu déstabiliser un patient déjà connu.","questions":[{"ask":"« Avez-vous une maladie du cœur connue : infarctus, valve malade, tension depuis longtemps, rythme irrégulier ? »","why":"Toutes les pathologies cardiovasculaires peuvent conduire à l'insuffisance cardiaque ; les œdèmes font partie des symptômes et signes cliniques du syndrome. Cardiopathies ischémiques (1re cause), HTA, valvulopathies, troubles du rythme.","flag":"terrain","src":"234 p. 458, 469-471"},{"ask":"« Avez-vous été opéré, plâtré, alité, ou voyagé longtemps récemment ? »","why":"Facteurs de MTEV : chirurgie sous anesthésie générale (> 30 min dans les 3 mois), fracture des membres inférieurs, immobilisation > 3 jours pour motif médical, voyage > 6 h. Wells : parésie/paralysie/plâtre récent, chirurgie < 4 semaines ou alitement > 3 jours.","flag":"orientation","src":"226 p. 495, 498"},{"ask":"« Avez-vous un cancer, êtes-vous enceinte ou avez-vous accouché récemment, prenez-vous la pilule ou un traitement hormonal ? »","why":"Cancer actif (facteur persistant) ; contraception œstroprogestative, grossesse, post-partum, traitement hormonal de la ménopause (facteurs temporaires majeurs) ; cancer évolutif = 1 point du score de Wells. Une compression extrinsèque (adénopathies, tumeur, utérus gravide) fait aussi gonfler une jambe.","flag":"orientation","src":"226 p. 495, 498"},{"ask":"« Avez-vous déjà eu une phlébite ou une embolie pulmonaire ? Quelqu'un de votre famille ? »","why":"Antécédent de TVP/EP = 1 point du score de Wells ; une récidive se manifeste souvent de la même façon que le premier épisode et est plus fréquente si la MTEV est non provoquée.","flag":"orientation","src":"226 p. 497-498"},{"ask":"« Depuis une ancienne phlébite, votre jambe est-elle restée lourde, avec des varices, une peau foncée, un ulcère ? »","why":"Le syndrome post-thrombotique apparaît quelques mois ou années après une TVP : lourdeur de jambe, dilatations veineuses superficielles, œdème de cheville, troubles trophiques (dermite ocre, atrophie blanche), ulcères sus-malléolaires.","flag":"orientation","src":"226 p. 503"},{"ask":"« Prenez-vous des anti-inflammatoires, du diltiazem ou du vérapamil, ou avez-vous arrêté vos diurétiques ? »","why":"Facteurs déclenchant une poussée d'IC : AINS, inhibiteurs calciques (diltiazem, vérapamil), rupture ou observance imparfaite du traitement, diminution inadaptée de la précharge (diurétiques, vasodilatateurs). Attention : le Collège les cite comme facteurs de décompensation.","flag":"terrain","src":"234 p. 473"},{"ask":"« Avez-vous fait des écarts de régime, mangé très salé ? »","why":"Les écarts de régime font partie des principaux facteurs déclenchants d'insuffisance cardiaque (encadré 18.2) ; le régime hyposodé vise à ne pas dépasser 5 à 6 g de sel par jour.","flag":"terrain","src":"234 p. 473, 476"},{"ask":"« Avez-vous une maladie du poumon (BPCO, embolie ancienne), une hypertension pulmonaire ? »","why":"Cause d'insuffisance cardiaque droite isolée : pathologies pulmonaires avec hypoxémie (cœur pulmonaire), séquelles d'EP, HTAP primitive ou liée à une connectivité (sclérodermie).","flag":"terrain","src":"234 p. 471 ; 203 p. 451-452"},{"ask":"« Avez-vous eu une chirurgie cardiaque, une péricardite, de la radiothérapie sur le thorax ? »","why":"Péricardite chronique constrictive : la chirurgie cardiaque en est actuellement la première cause ; elle donne un tableau d'insuffisance cardiaque droite avec turgescence jugulaire et ascite. L'irradiation thoracique figure parmi les causes de péricardite.","flag":"terrain","src":"235 p. 535-536"}],"astuce":"Deux cases à cocher : « mon patient a-t-il un cœur malade ? » (IC) et « mon patient est-il dans un contexte thrombogène ? » (TVP). Les deux peuvent être vraies."},{"key":"symptome","title":"Le symptôme, décortiqué","goal":"Caractériser l'œdème : côté, installation, étendue, douleur, aspect, évolution, prise de poids.","questions":[{"ask":"« Depuis quand vos jambes sont-elles gonflées ? Est-ce apparu d'un coup ou progressivement ? »","why":"Le tableau de TVP est plus évocateur lorsque la survenue est brutale ; l'IC s'installe avec aggravation progressive et prise de poids.","flag":"orientation","src":"226 p. 497 ; 234 p. 472"},{"ask":"« Est-ce qu'une seule jambe est gonflée, ou les deux ? »","why":"TVP : œdème typiquement unilatéral ou asymétrique. IC : œdèmes périphériques bilatéraux, prédominant aux parties déclives. C'est la question qui trie.","flag":"orientation","src":"226 p. 497 ; 234 p. 463"},{"ask":"« Jusqu'où ça monte : cheville, mollet, cuisse, toute la jambe ? »","why":"L'œdème de la TVP est d'autant plus étendu que la thrombose est proximale (différence de circonférence > 3 cm avec le membre controlatéral) ; le risque d'EP est beaucoup plus important en cas de TVP proximale.","flag":"orientation","src":"226 p. 494-497"},{"ask":"« Avez-vous mal à la jambe, spontanément ou quand on touche le mollet ? »","why":"Signes évocateurs de TVP : douleur spontanée ou provoquée du membre inférieur, sensibilité le long du trajet veineux profond. L'œdème de l'IC est indolore.","flag":"orientation","src":"226 p. 497-498 ; 234 p. 463"},{"ask":"« La peau est-elle rouge, chaude, tendue ? »","why":"Signes inflammatoires évocateurs de TVP, mais érysipèle, lymphangite, cellulite sont des diagnostics différentiels de la jambe gonflée.","flag":"orientation","src":"226 p. 497-498"},{"ask":"« Voyez-vous des veines superficielles dilatées, des varices ? »","why":"Dilatation des veines superficielles, circulation collatérale superficielle non variqueuse (point de Wells) dans la TVP ; varices et insuffisance veineuse primaire en diagnostic différentiel.","flag":"orientation","src":"226 p. 497-498"},{"ask":"« Les gonflements sont-ils plus marqués en bas, aux chevilles ? Les lombes sont-elles gonflées quand vous restez couché ? »","why":"Les œdèmes de l'IC prédominent dans les parties déclives du corps : membres inférieurs, région lombaire chez le patient alité.","flag":"orientation","src":"234 p. 463"},{"ask":"« Avez-vous pris du poids ? Combien en combien de jours ? »","why":"Prise de poids associée aux œdèmes dans l'IC ; une prise de 2 à 3 kg en 2 à 3 jours doit alerter ; à l'inverse, une perte de poids progressive sans œdème signe une dénutrition de mauvais pronostic.","flag":"orientation","src":"234 p. 462, 476"},{"ask":"« Avez-vous remarqué que vos jambes sont lourdes ou que vous urinez peu ? »","why":"Lourdeur de jambe dans le syndrome post-thrombotique ; oligurie à un stade très avancé d'IC (bas débit).","flag":"terrain","src":"226 p. 503 ; 234 p. 463"}],"astuce":"Question d'or : un côté ou deux ? Un côté + douleur = pense phlébite ; deux côtés + mou + indolore = pense insuffisance cardiaque."},{"key":"associes","title":"Signes associés","goal":"Chercher les signes de congestion et de retentissement d'une IC, et les signes d'embolie pulmonaire.","questions":[{"ask":"« Êtes-vous essoufflé ? À quel effort ? Combien d'étages ? »","why":"La dyspnée d'effort est fréquente et reflète la gravité (classification NYHA) ; stades I à IV selon l'effort provoquant la gêne.","flag":"orientation","src":"234 p. 461"},{"ask":"« Dormez-vous avec plusieurs oreillers ? Vous réveillez-vous en manquant d'air ? »","why":"Orthopnée et dyspnée paroxystique nocturne, plus spécifiques de l'IC.","flag":"orientation","src":"234 p. 461-462"},{"ask":"« Toussez-vous à l'effort ou allongé ? »","why":"Une toux électivement à l'effort ou au décubitus doit faire évoquer une insuffisance cardiaque.","flag":"orientation","src":"234 p. 462"},{"ask":"« Avez-vous une pesanteur douloureuse sous les côtes à droite, le ventre ballonné ? »","why":"Hépatalgie d'effort puis de repos par distension de la capsule hépatique (IC droite) ; météorisme abdominal = signe d'alerte du patient insuffisant cardiaque ; ascite tardive.","flag":"orientation","src":"234 p. 462, 476"},{"ask":"« Êtes-vous très fatigué, nauséeux, sans appétit ? »","why":"Fatigue de repos liée à l'hypotension artérielle ou à l'effort ; troubles digestifs (douleurs abdominales, nausées, vomissements) dans l'IC sévère ou terminale ; état cachectique à un stade très avancé.","flag":"terrain","src":"234 p. 462-463"},{"ask":"« Avez-vous senti votre cœur s'emballer ou fait un malaise ? »","why":"Palpitations parmi les symptômes de l'IC ; les troubles du rythme (fibrillation atriale) figurent parmi les facteurs déclenchants d'une poussée d'IC.","flag":"orientation","src":"234 p. 462, 473"},{"ask":"« Avez-vous eu un point de côté brutal, un essoufflement soudain ou craché du sang ? »","why":"Une EP peut compliquer ou accompagner la TVP (dyspnée, douleur thoracique, syncope, hémoptysie) ; la TVP peut même être asymptomatique et découverte au bilan d'une EP.","flag":"gravite","src":"226 p. 497, 504"}],"astuce":"À chaque fois, cherche d'un côté les signes d'IC (essoufflement, orthopnée, prise de poids), de l'autre les signes d'embolie (essoufflement brutal, douleur thoracique, syncope)."},{"key":"orientation","title":"Les questions qui orientent","goal":"Départager l'IC, la TVP, le syndrome post-thrombotique et les diagnostics différentiels cités par le Collège.","questions":[{"ask":"« Est-ce brutal, sur une seule jambe, douloureux, dans un contexte d'immobilisation ou d'opération ? »","if":"Si oui → thrombose veineuse profonde (phlegmatia alba dolens)","why":"Tableau le plus évocateur : atteinte typiquement unilatérale ou asymétrique, d'autant plus évocatrice que la survenue est brutale. La clinique seule n'a qu'une valeur d'orientation et ne confirme pas.","src":"226 p. 497"},{"ask":"« Les deux jambes sont-elles gonflées, molles, sans douleur, avec essoufflement et prise de poids ? »","if":"Si oui → insuffisance cardiaque droite ou globale","why":"Œdèmes mous, blancs, indolores, prenant le godet, bilatéraux et déclives, avec dyspnée, orthopnée ; les signes d'IC droite traduisent la rétention hydrosodée et la hausse de pression veineuse.","src":"234 p. 462-463"},{"ask":"« La jambe est-elle lourde de longue date, avec varices et peau foncée, depuis une phlébite ? »","if":"Si oui → syndrome post-thrombotique (ou insuffisance veineuse)","why":"SPT : lourdeur, œdème de cheville, dilatations veineuses, troubles trophiques, ulcère sus-malléolaire ; l'échodoppler montre obstruction et reflux. La contention veineuse instaurée dès la phase initiale et pendant au moins 3 mois réduit de 50 % le risque de SPT.","src":"226 p. 497, 503"},{"ask":"« Le gonflement est-il apparu après un effort violent, un traumatisme, un claquage ? »","if":"Si oui → lésion musculaire ou tendineuse (diagnostic différentiel de TVP quand les signes sont dissociés)","why":"Lorsque les signes sont dissociés, évoquer lésion musculaire ou tendineuse, kyste synovial (affection ostéoarticulaire), sciatique (neurologique).","src":"226 p. 498"},{"ask":"« La jambe est-elle rouge, chaude, avec de la fièvre ou une traînée rouge ? »","if":"Si oui → érysipèle, lymphangite, cellulite","why":"Diagnostics différentiels cités de la TVP.","src":"226 p. 498"},{"ask":"« Avez-vous une masse dans le ventre ou le pelvis, des ganglions, êtes-vous enceinte ? »","if":"Si oui → compression extrinsèque (adénopathies, tumeur, utérus gravide)","why":"Cause de gonflement unilatéral citée en diagnostic différentiel de la TVP ; l'échodoppler, voire l'angioscanner abdominopelvien, permet de trancher.","src":"226 p. 498-500"},{"ask":"« Avez-vous le ventre gonflé avec le foie sensible, et vos veines du cou sont-elles gonflées ? Une chirurgie du cœur ou une péricardite avant ? »","if":"Si oui → péricardite chronique constrictive","why":"Tableau d'insuffisance cardiaque droite souvent prédominante (turgescence jugulaire, ascite) ; la chirurgie cardiaque en est la première cause actuelle. Diagnostic échographique.","src":"235 p. 535-536"},{"ask":"« Avez-vous une maladie des poumons ou une hypertension pulmonaire connue ? »","if":"Si oui → cœur pulmonaire, IC droite isolée","why":"Causes d'IC droite isolée : pathologies pulmonaires avec hypoxémie (cœur pulmonaire chronique), séquelles d'EP, HTAP, pathologies tricuspidiennes isolées, infarctus du VD, constriction péricardique.","src":"234 p. 471 ; 203 p. 451-452"},{"ask":"« Avez-vous une maladie du foie ou des reins connue ? »","if":"Si oui → penser à une origine rénale ou hépatique (diagnostic différentiel)","why":"Le Collège cardio cite l'insuffisance cardiaque droite, rénale ou hépatique parmi les diagnostics différentiels d'un gonflement de jambe et précise que l'ascite de l'IC peut orienter à tort vers une cause hépatique ; le détail de ces causes relève d'autres spécialités.","src":"226 p. 498 ; 234 p. 463"}],"astuce":"Vérifie toujours le piège inverse : une ascite avec œdèmes n'est pas forcément du foie, ça peut être du cœur droit (ou un péricarde constrictif)."},{"key":"examen","title":"Examen clinique ciblé","goal":"Qualifier l'œdème, mesurer l'asymétrie, chercher la congestion droite et les signes de TVP ou d'EP.","questions":[{"ask":"Comparer les deux jambes et mesurer la circonférence des mollets à 10 cm sous la tubérosité tibiale antérieure","why":"Œdème du mollet > 3 cm par rapport au côté opposé : critère du score de Wells (TVP) ; œdème généralisé du membre : un autre point.","flag":"orientation","src":"226 p. 497-498"},{"ask":"Presser la peau (godet) et noter la consistance : mou, blanc, indolore ?","why":"Œdèmes de l'IC : mous, blancs, indolores, prenant le godet, prédominant aux parties déclives. Un œdème unilatéral prenant le godet est un critère du score de Wells.","flag":"orientation","src":"234 p. 463 ; 226 p. 498"},{"ask":"Palper le trajet veineux profond et le mollet ; chercher une circulation collatérale non variqueuse","why":"Sensibilité le long du trajet veineux profond et circulation collatérale superficielle non variqueuse : points de Wells.","flag":"orientation","src":"226 p. 498"},{"ask":"Regarder la peau : rougeur, chaleur, troubles trophiques, ulcère","why":"Signes inflammatoires (TVP, érysipèle) ; troubles trophiques sans ulcère (hypodermite, dermite ocre, atrophie blanche) ou ulcère sus-malléolaire (SPT).","flag":"orientation","src":"226 p. 497, 503"},{"ask":"Examiner la région lombaire chez un patient alité","why":"Les œdèmes déclives se retrouvent dans la région lombaire chez le patient alité.","flag":"terrain","src":"234 p. 463"},{"ask":"Chercher une turgescence jugulaire (patient demi-assis) et un reflux hépatojugulaire","why":"Turgescence jugulaire : signe très spécifique d'IC droite (difficile chez l'obèse) ; reflux hépatojugulaire recherché dans la même position après compression du foie.","flag":"orientation","src":"234 p. 463"},{"ask":"Palper le foie et chercher une ascite","why":"Hépatomégalie régulière, ferme, douloureuse ; ascite souvent tardive (sauf atteinte tricuspide organique ou péricardite constrictive), pouvant orienter à tort vers le foie.","flag":"orientation","src":"234 p. 463"},{"ask":"Ausculter le cœur (B3, souffles, éclat de B2) et les poumons (crépitants, épanchement pleural)","why":"IC : galop B3, souffle d'insuffisance mitrale/tricuspide, éclat de B2 en cas d'HTAP ; râles crépitants le plus souvent bilatéraux ; épanchement pleural transsudatif possible.","flag":"orientation","src":"234 p. 462-463"},{"ask":"Prendre PA, fréquence cardiaque et poids","why":"PAS < 100 mmHg = facteur de gravité d'une IC ; la tachycardie peut manquer sous bêtabloquants ; le poids sert au suivi de la rétention hydrosodée.","flag":"gravite","src":"234 p. 463, 476"},{"ask":"Rechercher un pouls paradoxal (PAS d'inspiration < PAS d'expiration de 10 mmHg)","why":"Signe de tamponnade (péricardite avec épanchement), à connaître devant des signes droits avec baisse de PA.","flag":"gravite","src":"235 p. 535 ; 203 p. 447"}],"astuce":"Deux rituels : le mètre (mollet > 3 cm de différence) pour la TVP, et le patient demi-assis (jugulaires, RHJ) pour le cœur droit. Un œdème seul n'est pas un diagnostic : on le qualifie."},{"key":"gravite","title":"Signes de gravité (à chercher d'emblée)","goal":"Repérer l'embolie pulmonaire, le bas débit et la décompensation sévère derrière un simple gonflement de jambes.","questions":[{"ask":"Dyspnée aiguë, douleur thoracique, syncope, tachycardie, hypoxie : signes d'embolie pulmonaire","why":"L'EP est la complication précoce de la TVP (3 à 7 jours après son début) ; dans 90 % des cas, elle est suspectée devant une dyspnée, une douleur thoracique ou une syncope ; environ 50 % des TVP proximales ont une EP asymptomatique.","flag":"gravite","src":"226 p. 494-497, 504"},{"ask":"Hypotension ou choc avec signes de cœur pulmonaire aigu : EP à haut risque","why":"PAS < 90 mmHg ou baisse > 40 mmHg pendant plus de 15 minutes : mortalité > 15 %.","flag":"gravite","src":"226 p. 509"},{"ask":"OAP : crise d'étouffement, orthopnée, crépitants jusqu'aux sommets, crachats mousseux saumonés","why":"Forme typique d'IC aiguë, grande urgence cardiovasculaire, prise en charge immédiate.","flag":"gravite","src":"234 p. 472"},{"ask":"Choc cardiogénique : PAS < 90 mmHg, extrémités froides/marbrées, oligurie, confusion","why":"Tableau ultime d'une défaillance aiguë et sévère ; mauvais pronostic.","flag":"gravite","src":"234 p. 473"},{"ask":"Présence de signes physiques d'IC malgré le traitement, PAS < 100 mmHg, hospitalisation récente pour décompensation","why":"La présence de signes physiques d'IC est en soi un élément de gravité ; une PAS < 100 et une hospitalisation pour décompensation sont des facteurs de gravité.","flag":"gravite","src":"234 p. 462-463, 475"},{"ask":"Tamponnade : signes droits + choc + pouls paradoxal","why":"Urgence vitale, drainage urgent.","flag":"gravite","src":"235 p. 535"},{"ask":"Anasarque, oligurie, cachexie : IC terminale","why":"À un stade très avancé : pouls alternant, oligurie, fonte musculaire (état cachectique) ; accumulation de liquide dans d'autres séreuses.","flag":"gravite","src":"234 p. 463"}],"astuce":"Un gonflement de jambe, c'est comme une alarme incendie : la phlébite menace le poumon (EP), le cœur gauche décompensé noie le poumon (OAP). Pose toujours la question « et le souffle ? »."},{"key":"examens","title":"Examens de 1re intention","goal":"Confirmer ou exclure la TVP et l'IC avec les examens recommandés par le Collège.","questions":[{"ask":"Score de probabilité clinique de Wells (TVP) : faible (0), intermédiaire (1-2), forte (≥ 3)","why":"Probabilité de TVP de 3 %, 17 % ou 75 %. À faire a priori, avant les tests paracliniques. Critères : paralysie/plâtre, chirurgie récente ou alitement, cancer évolutif, antécédent de TVP, sensibilité le long du trajet veineux, œdème généralisé, mollet > 3 cm, œdème unilatéral prenant le godet, circulation collatérale, diagnostic alternatif aussi probable (−2).","flag":"orientation","src":"226 p. 498"},{"ask":"D-dimères (Elisa, seuil < 500 ng/mL) si probabilité faible ou intermédiaire","why":"Utiles à l'élimination d'une TVP (sensibilité > 95 %, VPN > 95 %) ; spécificité faible (âge, inflammation, cancer, traumatisme, postopératoire, grossesse). Utilisés essentiellement pour exclure la MTEV si probabilité faible ou intermédiaire ; négatifs = TVP éliminée. Algorithme (fig. 19.1) : pas de dosage si âge ≥ 80 ans, cancer ou chirurgie < 30 jours.","flag":"orientation","src":"226 p. 499-500, 519"},{"ask":"Échodoppler veineux des membres inférieurs","why":"Examen de 1re intention pour confirmer ou infirmer la TVP (sensibilité et spécificité > 95 %) ; image du thrombus, incompressibilité de la veine, modifications du signal doppler.","flag":"orientation","src":"226 p. 499"},{"ask":"Probabilité intermédiaire ou forte : contention élastique + HBPM ou fondaparinux curatif, puis échodoppler veineux systématique dans les 24-48 h ou si possible en urgence","why":"Algorithme de la TVP (fig. 19.1), si D-dimères positifs ou non dosés : probabilité faible = contention élastique puis échodoppler ; intermédiaire ou forte = traitement curatif sans attendre l'échodoppler.","flag":"gravite","src":"226 p. 500"},{"ask":"BNP ou NT-proBNP","why":"Recommandé en 1re intention pour le diagnostic d'IC. Pour des œdèmes des membres inférieurs en consultation (non aigu) : BNP < 35 pg/mL ou NT-proBNP < 125 pg/mL rendent l'IC peu probable ; au-dessus, ou si IC fortement suspectée : échocardiographie. Majorés par l'âge, l'insuffisance rénale, la FA ; diminués par l'obésité.","flag":"orientation","src":"234 p. 465, 467"},{"ask":"Échocardiographie transthoracique avec doppler","why":"Examen clé de l'IC : type selon la FEVG (≤ 40, 41-49, ≥ 50 %), recherche d'une étiologie, conséquences hémodynamiques ; évalue le VG (taille, fonction), le VD, la veine cave inférieure, les atriums, les valves et les pressions de remplissage.","flag":"orientation","src":"234 p. 466"},{"ask":"ECG et radiographie thoracique","why":"ECG peu contributif au diagnostic d'IC mais oriente l'étiologie (onde Q, troubles du rythme, QRS > 120 ms) ; radio : cardiomégalie, stase pulmonaire, épanchement pleural.","flag":"terrain","src":"234 p. 463-465"},{"ask":"Bilan biologique de l'IC : natrémie, kaliémie, créatininémie, glycémie à jeun/HbA1c, bilan lipidique, bilan hépatique, TSH, NFS, ferritine et coefficient de saturation de la transferrine","why":"Examens biologiques simples recommandés devant une IC avérée ou suspectée (ESC 2021).","flag":"terrain","src":"234 p. 467"},{"ask":"Angioscanner abdominopelvien si l'échodoppler ne conclut pas","why":"Peut compléter l'échodoppler au niveau abdominopelvien.","flag":"terrain","src":"226 p. 500"}],"astuce":"Deux examens à relier aux deux grands diagnostics : échodoppler veineux pour une jambe (TVP), BNP puis échocardiographie pour deux jambes (IC). Les D-dimères servent à exclure, jamais à confirmer."}],"synthese":"Monsieur R., 78 ans, hypertendu et en FA, consulte pour des jambes gonflées des deux côtés depuis 2 semaines, avec prise de poids de 4 kg, dyspnée d'effort NYHA III et orthopnée avec trois oreillers. Œdèmes mous, indolores, prenant le godet jusqu'aux genoux, turgescence jugulaire, crépitants des bases, PA 110/70, FC 105 irrégulière, SpO2 94 %. Hypothèses : insuffisance cardiaque globale décompensée sur FA rapide (BNP, ECG, radio, échocardiographie) ; sans oublier l'embolie pulmonaire (dyspnée, FA) et, si une seule jambe avait été touchée, la TVP (score de Wells, D-dimères, échodoppler).","hypotheses":[{"dx":"Insuffisance cardiaque droite ou globale","pour":"Œdèmes bilatéraux mous indolores prenant le godet, déclives ; prise de poids, dyspnée d'effort, orthopnée, turgescence jugulaire, RHJ, hépatomégalie, ascite ; BNP élevé","danger":true,"src":"234 p. 462-465"},{"dx":"Thrombose veineuse profonde","pour":"Œdème unilatéral ou asymétrique brutal, douleur, signes inflammatoires, veines superficielles dilatées, contexte thrombogène, Wells élevé, D-dimères positifs, échodoppler","danger":true,"src":"226 p. 497-500"},{"dx":"Embolie pulmonaire associée","pour":"Dyspnée aiguë, douleur thoracique, syncope, tachycardie chez un patient avec TVP ou facteurs de MTEV","danger":true,"src":"226 p. 497, 504"},{"dx":"Syndrome post-thrombotique","pour":"Antécédent de TVP, lourdeur, œdème de cheville, varices, troubles trophiques, ulcère sus-malléolaire ; reflux à l'échodoppler","danger":false,"src":"226 p. 503"},{"dx":"Péricardite chronique constrictive / tamponnade","pour":"IC droite prédominante, turgescence jugulaire, ascite ; antécédent de chirurgie cardiaque ; pouls paradoxal en cas de tamponnade","danger":true,"src":"235 p. 535-536"},{"dx":"Cœur pulmonaire / HTAP","pour":"Pathologie pulmonaire, hypoxémie, séquelles d'EP, connectivité ; signes droits isolés, éclat de B2","danger":false,"src":"234 p. 471 ; 203 p. 451-452"},{"dx":"Diagnostics différentiels de la jambe gonflée","pour":"Lésion musculaire, kyste synovial, sciatique, érysipèle/lymphangite/cellulite, lymphœdème, insuffisance veineuse, compression extrinsèque, atteinte rénale ou hépatique","danger":false,"src":"226 p. 498"}],"pieges":["La clinique seule ne confirme pas la TVP : elle oriente, il faut une méthode objective (échodoppler).","Une TVP peut être asymptomatique et découverte au bilan d'une EP.","Les D-dimères excluent, ils ne confirment pas : ils sont élevés dans de nombreuses situations.","Les signes d'IC peuvent disparaître rapidement sous traitement : leur absence n'élimine pas l'IC.","L'ascite de l'IC peut orienter à tort vers une cause hépatique.","Perte de poids sans œdème chez un insuffisant cardiaque : dénutrition, mauvais pronostic.","Œdème unilatéral + dyspnée brutale : pense à l'embolie pulmonaire (complication de la TVP)."],"src":"234 p. 458-477 ; 226 p. 494-509 ; 235 p. 535-536 ; 203 p. 451-452"},{"id":"hta","spe":"cardio","title":"HTA : consultation et poussée hypertensive","emoji":"🩸","items":["224"],"hook":"Une PA haute au cabinet ne fait pas une HTA : il faut la confirmer hors cabinet, sauf si un organe souffre (urgence) ; là, on traite sans attendre.","intro":"L'HTA est le plus souvent totalement silencieuse : on la découvre au détour d'une consultation, et c'est ton interrogatoire qui fait la différence. En consultation, tu fais le tri entre HTA confirmée, retentissement sur les organes cibles, cause secondaire et facteurs aggravants. Devant une PA très élevée, ta première question n'est pas « combien ? » mais « est-ce qu'un organe souffre ? ».","steps":[{"key":"terrain","title":"Terrain et antécédents","goal":"Poser le terrain : ancienneté de l'HTA, autres facteurs de risque, antécédents d'organes cibles, traitement en cours.","questions":[{"ask":"« Depuis quand votre tension est-elle élevée ? Quelles étaient les valeurs avant ? »","why":"L'interrogatoire précise l'ancienneté de l'HTA et les valeurs antérieures.","flag":"terrain","src":"224 p. 91"},{"ask":"« Fumez-vous ? Êtes-vous diabétique ? Avez-vous un cholestérol élevé ? »","why":"On cherche les facteurs de risque cardiovasculaire associés : dyslipidémie, diabète, tabagisme.","flag":"terrain","src":"224 p. 91"},{"ask":"« Dans votre famille, quelqu'un a-t-il eu un infarctus, un AVC ou une artérite à un âge jeune ? »","why":"Les antécédents familiaux cardiovasculaires précoces font partie des facteurs de risque à recueillir ; le niveau de PA est aussi un trait partiellement héritable.","flag":"terrain","src":"224 p. 87, 91"},{"ask":"« Avez-vous déjà eu un infarctus, un angor, une insuffisance cardiaque, un AVC ou un AIT, un problème aux artères des jambes, une maladie rénale ? »","why":"Le Collège classe d'emblée à risque cardiovasculaire élevé le patient hypertendu avec antécédent de maladie coronarienne, AVC, AIT, AOMI, insuffisance cardiaque, insuffisance rénale modérée ou sévère, atteinte d'organe cible cardiaque ou vasculaire, ou hypercholestérolémie familiale.","flag":"terrain","src":"224 p. 91, 94"},{"ask":"« (Chez une femme) Votre grossesse s'est-elle bien passée : tension, diabète gestationnel, prééclampsie, accouchement prématuré, fausses couches à répétition ? »","why":"Les antécédents de grossesse compliquée sont à rechercher chez toute patiente hypertendue.","flag":"terrain","src":"224 p. 91"},{"ask":"« Prenez-vous déjà un traitement pour la tension ? Le prenez-vous tous les jours, à quelle heure ? »","why":"L'observance est un point clé : un traitement mal pris est une cause d'échec, et une HTA n'est dite résistante qu'après avoir vérifié l'observance.","flag":"orientation","src":"224 p. 99, 101, 102"},{"ask":"« Êtes-vous enceinte ou envisagez-vous une grossesse ? »","why":"Certains antihypertenseurs sont contre-indiqués pendant la grossesse (IEC, ARA2, thiazidiques ou apparentés) : on dose la β-hCG en cas de suspicion de grossesse.","flag":"terrain","src":"224 p. 93, 98"}],"astuce":"Pense « PA + 4 questions de terrain » : fumeur ? diabétique ? cholestérol ? famille précoce ? Tu as déjà le début du risque cardiovasculaire global."},{"key":"symptome","title":"Les circonstances de découverte et les symptômes","goal":"Savoir comment l'HTA a été trouvée et éviter l'erreur de mettre sur le compte de l'HTA des symptômes qui ne sont pas spécifiques.","questions":[{"ask":"« Comment a-t-on découvert votre tension élevée : par hasard, lors d'un bilan, chez le médecin du travail, à la pharmacie ? »","why":"Le plus souvent l'HTA est totalement latente et découverte lors d'un examen systématique.","flag":"terrain","src":"224 p. 90"},{"ask":"« Avez-vous des maux de tête ? Où ? À quel moment de la journée ? »","why":"Céphalées occipitales légèrement battantes, matinales, qui résistent volontiers aux antalgiques habituels et cèdent en quelques minutes au lever ou progressivement dans la matinée : classiques mais non spécifiques, elles n'affirment pas l'HTA.","flag":"orientation","src":"224 p. 90"},{"ask":"« Vous sentez-vous plus fatigué que d'habitude, nerveux, avez-vous du mal à dormir ? »","why":"Fatigabilité anormale, nervosité et insomnie font partie des symptômes non spécifiques évoquant l'HTA.","flag":"terrain","src":"224 p. 90"},{"ask":"« Voyez-vous des petits éclairs ou des points lumineux devant les yeux ? »","why":"Phosphènes : symptôme non spécifique de l'HTA.","flag":"terrain","src":"224 p. 90"},{"ask":"« Saignez-vous du nez facilement ? »","why":"Épistaxis : symptôme non spécifique cité par le Collège ; il n'est pas certain que l'HTA en soit la cause et le diagnostic ne peut pas reposer dessus.","flag":"terrain","src":"224 p. 90"},{"ask":"« Avez-vous mesuré votre tension chez vous ? Avec quel appareil ? »","why":"L'automesure tensionnelle est l'examen recommandé en France pour confirmer le diagnostic ; il faut savoir quel appareil et quelle méthode (brassard huméral, règle des 3).","flag":"orientation","src":"224 p. 84, 91"},{"ask":"« Comment mangez-vous : beaucoup de sel, de charcuterie, peu de fruits et légumes ? »","why":"Une alimentation riche en graisses animales, en sel et pauvre en fruits et légumes aggrave l'HTA.","flag":"terrain","src":"224 p. 91"},{"ask":"« Buvez-vous de l'alcool ? Combien de verres par semaine ? Faites-vous du sport ? Avez-vous pris du poids récemment ? »","why":"Alcool, sédentarité, faible activité physique et surpoids (prise de poids récente) sont des facteurs aggravants à rechercher ; la cible est moins de 10 unités d'alcool par semaine.","flag":"terrain","src":"224 p. 91, 96"},{"ask":"« Vous arrive-t-il de ronfler, de faire des pauses respiratoires la nuit ? Votre conjoint le remarque-t-il ? »","why":"Ronflements et pauses nocturnes (interroger le conjoint) évoquent un syndrome d'apnées obstructives du sommeil, facteur aggravant et cause d'HTA résistante.","flag":"orientation","src":"224 p. 91, 102, 105"}],"astuce":"Piège de fond : ces symptômes sont banals. Tu ne poses pas le diagnostic dessus et tu ne traites pas sur eux seuls : tu mesures, tu confirmes hors cabinet, puis tu bilantes."},{"key":"associes","title":"Signes associés : le retentissement sur les organes cibles","goal":"Passer en revue le cerveau, le cœur, les reins et les artères : l'HTA se juge à ce qu'elle abîme.","questions":[{"ask":"« Avez-vous des vertiges, des troubles de la vue, une faiblesse ou un engourdissement d'un côté du corps, des troubles de la mémoire ? »","why":"Atteinte neurovasculaire : céphalées, vertiges, troubles visuels, déficit sensitif ou moteur, troubles cognitifs (MMSE).","flag":"orientation","src":"224 p. 91"},{"ask":"« Avez-vous des palpitations, des douleurs dans la poitrine, un essoufflement, les jambes qui gonflent ? »","why":"Atteinte cardiaque : palpitations, douleur thoracique, dyspnée, œdèmes des membres inférieurs.","flag":"orientation","src":"224 p. 91"},{"ask":"« Avez-vous très soif, urinez-vous beaucoup, vous levez-vous la nuit pour uriner, avez-vous déjà vu du sang dans les urines ? »","why":"Atteinte rénale : soif, polyurie, nycturie, hématurie, œdèmes des membres inférieurs.","flag":"orientation","src":"224 p. 91"},{"ask":"« Avez-vous les pieds ou les mains froids, mal aux mollets à la marche ? »","why":"Atteinte des artères périphériques : extrémités froides, claudication intermittente.","flag":"orientation","src":"224 p. 91"},{"ask":"« Avez-vous déjà eu une fibrillation atriale, un trouble du rythme ? »","why":"L'HTA est la première cause de fibrillation atriale (70 % des patients en FA sont hypertendus) et un facteur de risque thromboembolique.","flag":"terrain","src":"224 p. 89"},{"ask":"« Avez-vous déjà eu un bilan de vos reins (analyse d'urine, prise de sang) ? Quels résultats ? »","why":"Une néphropathie connue est un antécédent d'atteinte d'organe cible à rechercher, et l'HTA peut elle-même provoquer une néphroangiosclérose (signe précoce : microalbuminurie).","flag":"terrain","src":"224 p. 91, 90"}],"astuce":"Les 4 organes cibles : tête, cœur, reins, artères des jambes. Pour chacun, une question de symptôme, une question d'antécédent."},{"key":"orientation","title":"Les questions qui orientent : HTA secondaire et facteurs aggravants","goal":"Chercher la minorité de cas (environ 10 %) où une cause spécifique est traitable, et les médicaments ou toxiques qui font monter la PA.","questions":[{"ask":"« Prenez-vous la pilule, des gouttes pour le nez, des anti-inflammatoires, de la cortisone, de l'érythropoïétine, de la ciclosporine, un médicament anticancéreux ? »","why":"Contraceptifs oraux, vasoconstricteurs nasaux, corticoïdes, AINS, érythropoïétine, ciclosporine, tacrolimus, dérivés de l'ergot de seigle, inhibiteurs de tyrosine-kinase et anti-VEGF sont des médicaments hypertensiogènes.","if":"Si oui → médicament en cause ou qui interfère avec les antihypertenseurs (AINS)","flag":"orientation","src":"224 p. 91, 105"},{"ask":"« Consommez-vous de la réglisse (bonbons, tisanes, boissons anisées), du cannabis, de la cocaïne, des amphétamines ? Combien d'alcool ? »","why":"Réglisse, cannabis, cocaïne, amphétamines et alcool sont des substances hypertensiogènes ; les boissons anisées contiennent de la réglisse.","if":"Si oui → HTA toxique ou iatrogène","flag":"orientation","src":"224 p. 92, 105"},{"ask":"« Avez-vous des crises brutales avec maux de tête, sueurs et palpitations, sans raison particulière ? »","why":"La triade de Ménard (céphalées, sueurs, palpitations par crises brutales sans facteur déclenchant) évoque le phéochromocytome.","if":"Si oui → phéochromocytome","flag":"orientation","src":"224 p. 92, 104"},{"ask":"« Avez-vous de la fatigue, des crampes, des crises de tétanie, des fourmillements aux extrémités, de la constipation ? »","why":"Ces signes neuromusculaires font évoquer une hypokaliémie et un hyperaldostéronisme.","if":"Si oui → hyperaldostéronisme (syndrome de Conn), HTA + hypokaliémie","flag":"orientation","src":"224 p. 92, 104"},{"ask":"« (Femme) Avez-vous des bleus faciles, des règles rares ou absentes, des poils en excès ? »","why":"Ecchymoses faciles (hypercatabolisme) et hyperandrogénie (oligospanioménorrhée, aménorrhée) évoquent un hypercortisolisme (syndrome de Cushing).","if":"Si oui → syndrome de Cushing","flag":"orientation","src":"224 p. 92"},{"ask":"« Avez-vous eu des infections urinaires à répétition, du sang dans les urines ? Quelqu'un de votre famille a-t-il une maladie des reins (reins polykystiques) ou une tumeur endocrine ? »","why":"Histoire familiale de néphropathie (polykystose) ou de polyendocrinopathies, infections urinaires répétées, hématurie ou autre maladie rénale connue sont des symptômes évocateurs d'une HTA secondaire.","if":"Si oui → néphropathie parenchymateuse, polykystose","flag":"orientation","src":"224 p. 91, 103"},{"ask":"« Avez-vous déjà eu un œdème aigu du poumon sans cause cardiaque, une insuffisance rénale après un traitement IEC/ARA2 ? »","why":"Un œdème aigu pulmonaire récidivant sans cause cardiaque et une insuffisance rénale compliquant l'introduction d'IEC/ARA2 évoquent une HTA rénovasculaire.","if":"Si oui → sténose des artères rénales","flag":"orientation","src":"224 p. 103"},{"ask":"« À quel âge a-t-on découvert votre tension élevée ? »","why":"Avis spécialisé d'emblée en cas d'HTA avant l'âge de 40 ans, sauf obésité (dépistage préalable d'un SAOS) (p. 94) ; dépistage d'HTA secondaire en cas d'âge ≤ 40 ans (p. 102).","if":"Si ≤ 40 ans → chercher une cause secondaire","flag":"orientation","src":"224 p. 94, 102"}],"astuce":"Les 4 « signes d'appel » à ne jamais oublier : médicament ou toxique (réglisse, pilule, AINS), triade Ménard, crampes avec potassium bas, ronflement. Ils sont d'ailleurs listés comme notions inacceptables à oublier."},{"key":"examen","title":"Examen clinique ciblé","goal":"Mesurer la PA correctement, puis chercher le retentissement et les signes d'HTA secondaire.","questions":[{"ask":"Patient assis, au repos depuis plus de 5 minutes, brassard adapté au bras, bras sur table à hauteur du cœur : au moins 3 mesures espacées de 1 à 2 minutes, on retient la moyenne des 2 dernières","why":"Appareil électronique oscillométrique validé au bras ; si les 2 premières mesures diffèrent de plus de 10 mmHg de PAS, on refait des mesures. Le stéthoscope n'est plus recommandé en 1re intention sauf en fibrillation atriale.","flag":"terrain","src":"224 p. 83"},{"ask":"Mesurer la PA aux deux bras à la première consultation","why":"Une asymétrie fait suspecter une sténose de l'artère subclavière ; on prend le bras aux valeurs les plus élevées comme référence.","flag":"orientation","src":"224 p. 83"},{"ask":"Rechercher une hypotension orthostatique : PA et FC après 5 min couché ou assis, puis debout à 1 et 3 minutes","why":"Elle est confirmée par une baisse d'au moins 20 mmHg de PAS et/ou d'au moins 10 mmHg de PAD ; fréquente chez les sujets âgés, fragiles, diabétiques. Elle conditionne la cible tensionnelle.","flag":"orientation","src":"224 p. 84, 95"},{"ask":"Prendre le pouls (au moins 30 secondes) et chercher une arythmie","why":"La FC de repos se mesure par palpation du pouls pendant au moins 30 secondes, en recherchant une arythmie (fibrillation atriale).","flag":"terrain","src":"224 p. 84"},{"ask":"Auscultation des carotides et du cœur, recherche d'un galop, d'un déficit moteur ou sensitif, d'œdèmes des membres inférieurs","why":"Atteinte neurovasculaire (souffles carotidiens, déficit) et cardiaque (tachycardie, arythmie, galop, œdèmes, autres signes d'insuffisance cardiaque).","flag":"orientation","src":"224 p. 92"},{"ask":"Palper tous les pouls (fémoraux surtout), ausculter l'abdomen, chercher une masse battante, une extrémité froide, une lésion cutanée ischémique","why":"Artères périphériques : pouls absents, diminués ou asymétriques, souffle abdominal, masse abdominale battante. Pouls fémoraux diminués ou abolis : coarctation ; souffle aortique abdominal : HTA rénovasculaire.","flag":"orientation","src":"224 p. 92"},{"ask":"Palper les fosses lombaires et l'abdomen, regarder la peau (signes cutanés de neurofibromatose, vergetures, peau fine, bosse de bison)","why":"Gros reins palpables : polykystose ; signes cutanés de neurofibromatose : phéochromocytome ; peau fine, vergetures pourpres et larges, érythrose, amyotrophie proximale (signe du tabouret), bosse de bison, hirsutisme : syndrome de Cushing.","flag":"orientation","src":"224 p. 92"},{"ask":"Poids, taille, IMC, et périmètre abdominal debout","why":"Recherche d'une obésité viscérale ; cibles : IMC 20-25 kg/m², périmètre abdominal < 94 cm chez l'homme et < 80 cm chez la femme.","flag":"terrain","src":"224 p. 92, 96"},{"ask":"Rester attentif aux artères rigides : chez un sujet âgé, diabétique ou dialysé, le pouls radial reste-t-il perçu brassard gonflé au-dessus de la PAS (manœuvre d'Osler) ?","why":"Des calcifications vasculaires peuvent rendre les artères incompressibles et faire surestimer la PA de 20 mmHg (parfois 40-50) ; une pression pulsée > 65 mmHg est aussi un marqueur de rigidité.","flag":"terrain","src":"224 p. 84"}],"astuce":"Le trio gagnant de la première consultation : deux bras, orthostatisme, pouls au moins 30 secondes. Tout le reste du palper-écouter sert à débusquer un organe cible ou une cause secondaire."},{"key":"gravite","title":"Signes de gravité (à chercher d'emblée)","goal":"Distinguer l'HTA sévère isolée de l'urgence hypertensive : PA très élevée plus souffrance d'organe aiguë.","questions":[{"ask":"« Avez-vous une douleur brutale dans la poitrine ? »","why":"Une douleur thoracique brutale chez un hypertendu fait chercher un syndrome coronarien aigu ou une dissection aortique, deux urgences hypertensives (vignette du Collège : PA mesurée à 195/110 avec douleur thoracique).","flag":"gravite","src":"224 p. 83, 106"},{"ask":"« Êtes-vous très essoufflé, même au repos ? »","why":"HTA avec insuffisance ventriculaire gauche : œdème aigu du poumon hypertensif, une des principales urgences hypertensives.","flag":"gravite","src":"224 p. 106"},{"ask":"« Avez-vous un déficit (faiblesse, engourdissement), un très fort mal de tête, des troubles de la conscience ? »","why":"Encéphalopathie hypertensive (HTA avec hypertension intracrânienne), AVC ou hémorragie cérébrale/méningée, PRES, coma dans l'HTA maligne. Devant un point d'appel neurologique, le scanner est indispensable avant de débuter le traitement antihypertenseur.","flag":"gravite","src":"224 p. 92, 106, 107"},{"ask":"« Votre vue a-t-elle baissé brutalement, avez-vous perdu la vue ? »","why":"Cécité centrale et lésions occipitales (PRES) ; occlusion de la veine centrale de la rétine ou rétinopathie stade 4 au fond d'œil.","flag":"gravite","src":"224 p. 106"},{"ask":"« Avez-vous pris de la cocaïne, des amphétamines, du LSD, de l'ecstasy ? »","why":"HTA liée à l'usage de ces toxiques : urgence hypertensive.","flag":"gravite","src":"224 p. 106"},{"ask":"« (Femme enceinte) Votre tension est-elle élevée ? Avez-vous des maux de tête, des troubles de la vue, un signe neurologique ? »","why":"Prééclampsie sévère ou éclampsie nécessitant une extraction fœtale en urgence.","flag":"gravite","src":"224 p. 91, 106"},{"ask":"« Avez-vous maigri, êtes-vous très fatigué depuis quelques semaines, avec des nausées, des vomissements, des douleurs du ventre, une grande soif ? »","why":"L'HTA maligne s'accompagne souvent d'asthénie avec amaigrissement et altération de l'état général sur quelques semaines, de troubles digestifs, de soif et de signes de déshydratation.","flag":"gravite","src":"224 p. 107"},{"ask":"Voir le fond d'œil dès que la PA est en grade 3 (≥ 180 et/ou ≥ 110) : œdème papillaire ?","why":"Un œdème papillaire (rétinopathie stade 4) avec PA non contrôlée signe l'HTA maligne, qui est une urgence hypertensive. Devant un grade 3, on cherche systématiquement une urgence.","flag":"gravite","src":"224 p. 86, 94, 107"}],"astuce":"Crise hypertensive ≠ urgence hypertensive. Crise = grade 3 sans souffrance viscérale, pas une urgence. Urgence = grade 3 (souvent) + un organe qui souffre. Le chiffre seul ne fait pas l'urgence : c'est l'organe."},{"key":"examens","title":"Examens de 1re intention","goal":"Confirmer l'HTA hors cabinet, bilanter le risque et le retentissement, et savoir quand aller plus loin.","questions":[{"ask":"Automesure tensionnelle : « règle des 3 » (3 jours de suite, 3 mesures le matin, 3 le soir, soit 18 mesures)","why":"L'AMT est l'examen recommandé en France pour confirmer l'HTA, avant tout traitement (sauf urgence hypertensive) ; seuil AMT : moyenne ≥ 135/85 mmHg. Matin avant petit-déjeuner et médicaments, soir avant le coucher, brassard huméral.","flag":"orientation","src":"224 p. 84, 86"},{"ask":"MAPA sur 24 heures si l'AMT n'est pas possible ou fiable","why":"Seuil 130/80 mmHg sur 24 h. Utile aussi pour HTA résistante, hypotension symptomatique, forte variabilité, PA nocturne. Elle sépare HTA blouse blanche (15-20 %) et HTA masquée (10-15 %).","flag":"orientation","src":"224 p. 84-87"},{"ask":"Biologie : glycémie à jeun et HbA1c, bilan lipidique (CT, HDL, TG, LDL calculé), natrémie, kaliémie, hémoglobine/hématocrite, créatininémie avec DFG (CKD-EPI)","why":"Bilan minimal de 1re intention pour rechercher les autres facteurs de risque, une atteinte infraclinique des organes cibles ou des arguments pour une HTA secondaire. Kaliémie basse : hyperaldostéronisme.","flag":"terrain","src":"224 p. 92, 110"},{"ask":"Protéinurie : rapport protéinurie/créatininurie (ou albuminurie/créatinurie) sur un échantillon d'urine","why":"Systématique ; protéinurie au-delà de 300 mg/g, valeurs > 30 mg/g déjà pathologiques ; la microalbuminurie n'est recherchée systématiquement que chez le diabétique.","flag":"terrain","src":"224 p. 92, 94"},{"ask":"ECG de repos 12 dérivations","why":"Recherche d'une HVG électrique (Sokolow, Cornell, Lewis), d'une séquelle d'infarctus passée inaperçue, d'anomalies de repolarisation, de troubles du rythme (FA). Il sert aussi de repère pour la suite.","flag":"terrain","src":"224 p. 92, 93"},{"ask":"Échocardiographie si anomalie ECG ou signes cardiologiques (dyspnée)","why":"Examen non systématique : on ne la fait pas chez l'asymptomatique avec ECG normal. Elle cherche une HVG (masse VG > 115 g/m² chez l'homme, > 95 g/m² chez la femme), une dysfonction systolique ou diastolique.","flag":"terrain","src":"224 p. 93"},{"ask":"Fond d'œil si HTA de grade 2 ou 3 avec suspicion d'HTA maligne (recommandé dans les HTA de grade 3) ; IPS et échodoppler des artères si souffle ou symptômes d'AOMI","why":"Examens non systématiques, à prescrire selon le contexte. Le fond d'œil recherche les rétinopathies de stade 3 (hémorragies ou exsudats) ou 4 (œdème papillaire), associées à un risque accru d'événements cardiovasculaires.","flag":"terrain","src":"224 p. 93, 94"},{"ask":"Si PA ≥ 180/110 ou signe d'organe : en urgence, ECG, troponine, créatinine et protéinurie, NFS, plaquettes, haptoglobine/LDH/schizocytes, radiographie de thorax, scanner cérébral avant tout traitement si point d'appel neurologique, imagerie aortique si dissection suspectée","why":"Examens à adapter au contexte devant une urgence hypertensive : SCA, OAP, dissection, hémorragie, microangiopathie, toxiques (cocaïne), CIVD.","flag":"gravite","src":"224 p. 106"}],"astuce":"Bilan minimal en 7 : Na, K, créatinine + DFG, glycémie, lipides, protéinurie sur échantillon, ECG. C'est la liste des notions indispensables."}],"synthese":"Patiente de 47 ans, diabétique de type 2, tabagique à 15 cigarettes/jour depuis 25 ans, en surpoids (75 kg pour 160 cm), vue pour un renouvellement d'ordonnance, avec une PA à 148/94 mmHg au cabinet. HTA de grade 1 non confirmée à ce stade, à confirmer par une automesure en « règle des 3 » avant tout traitement. Dyspnée d'effort stade 2 NYHA, stable. Pas d'argument pour une cause secondaire à l'interrogatoire. Hypothèses : HTA essentielle sur terrain de risque cardiovasculaire élevé (diabète, tabac, surpoids) ; HTA blouse blanche à éliminer ; HTA secondaire à évoquer si hypokaliémie, aggravation ou résistance ; urgence hypertensive à éliminer si PA ≥ 180/110 avec douleur thoracique ou signe d'organe.","hypotheses":[{"dx":"HTA essentielle (90 %)","pour":"HTA confirmée hors cabinet (AMT ≥ 135/85, MAPA 24 h ≥ 130/80), terrain de risque (diabète, tabac, surpoids), pas de point d'appel secondaire","danger":false,"src":"224 p. 86, 88"},{"dx":"HTA blouse blanche","pour":"PA de consultation supérieure à 140/90 mmHg mais mesures ambulatoires qui ne confirment pas l'HTA (15-20 % des adultes) ; surveillance régulière hors cabinet et mesures hygiénodiététiques, pas de traitement médicamenteux","danger":false,"src":"224 p. 86-87"},{"dx":"HTA masquée","pour":"PA de consultation < 140/90 mais AMT/MAPA élevées (10-15 %), souvent avec risque cardiovasculaire élevé ; même risque, même prise en charge","danger":false,"src":"224 p. 87"},{"dx":"HTA secondaire (10 %)","pour":"HTA sévère (> 180/110), brutale ou rapidement aggravée, résistante, ≤ 40 ans, ou avec hypokaliémie, souffle abdominal, triade de Ménard, médicament ou toxique en cause","danger":false,"src":"224 p. 92, 102-105"},{"dx":"HTA résistante","pour":"PA au-dessus de la cible malgré 3 classes à dose optimale dont un diurétique thiazidique, après avoir éliminé une HTA faussement résistante (observance, sel, alcool, blouse blanche)","danger":false,"src":"224 p. 101-102"},{"dx":"Urgence hypertensive (SCA, OAP, dissection aortique, encéphalopathie, AVC/hémorragie, phéochromocytome, prééclampsie sévère, toxique)","pour":"PA le plus souvent > 180/110 associée à un point d'appel viscéral aigu ; hospitalisation en soins intensifs, baisse de 20-25 % en 2 heures, PA toutes les 15 minutes","danger":true,"src":"224 p. 106-107"},{"dx":"HTA maligne","pour":"PA élevée (souvent grade 3) et œdème papillaire au fond d'œil (stade 4), avec atteinte cardiaque, rénale, neurologique ou microangiopathie thrombotique","danger":true,"src":"224 p. 107"},{"dx":"Dissection aortique","pour":"Douleur thoracique brutale chez un hypertendu ; PAS à ramener < 120 mmHg le plus rapidement possible","danger":true,"src":"224 p. 83, 106"}],"pieges":["Traiter sur une PA de cabinet seule : confirme d'abord par AMT ou MAPA (sauf urgence).","Grade 3 sans organe touché = crise hypertensive, pas urgence ; mais cherche toujours l'urgence.","Urgence hypertensive : baisse trop brutale de la PA = hypoperfusion cérébrale, myocardique, rénale.","Scanner cérébral avant l'antihypertenseur si signe neurologique (hémorragique ou ischémique ?).","Oublier réglisse, pilule, AINS, ronflements et crampes : signes d'appel d'HTA secondaire (notion inacceptable).","Dissection aortique : cible inverse, PAS < 120 mmHg le plus vite possible."],"src":"224 p. 83-107"},{"id":"mollet-douloureux","spe":"cardio","title":"Mollet douloureux, jambe gonflée : TVP ?","emoji":"🦶","items":["226"],"hook":"Jambe douloureuse et gonflée d'un seul côté : la clinique seule ne suffit jamais à poser une TVP, mais ne jamais oublier l'embolie pulmonaire qui peut l'accompagner.","intro":"La thrombose veineuse profonde et l'embolie pulmonaire sont deux visages de la même maladie thromboembolique veineuse. Pour la TVP, tu cherches le contexte (provoqué ou non), tu calcules le score de Wells avant tout examen, tu cherches les diagnostics différentiels, et surtout tu poses toujours la question de l'EP : respiration, thorax, malaise.","steps":[{"key":"terrain","title":"Terrain et facteurs prédisposants","goal":"Retrouver un contexte thrombogène : provoqué (transitoire) ou non, et estimer le risque de récidive.","questions":[{"ask":"« Avez-vous été opéré récemment, sous anesthésie générale ? Quand, et de quoi ? »","why":"Chirurgie avec anesthésie générale > 30 minutes dans les 3 derniers mois = facteur transitoire majeur ; plus fréquent en chirurgie orthopédique. Risque élevé 2 semaines, haut jusqu'à 2-3 mois. Le Wells compte la chirurgie récente < 4 semaines.","flag":"terrain","src":"226 p. 495, 498"},{"ask":"« Vous êtes-vous fracturé un membre inférieur, avez-vous eu un plâtre ? »","why":"Fracture des membres inférieurs dans les 3 derniers mois = facteur majeur ; plâtre ou immobilisation récente d'un membre inférieur compte au score de Wells.","flag":"terrain","src":"226 p. 495, 498"},{"ask":"« Avez-vous été alité ou peu mobile ces derniers jours ? Avez-vous fait un long voyage (plus de 6 heures) ? »","why":"Immobilisation > 3 jours pour motif médical aigu dans les 3 derniers mois = majeur ; voyage > 6 heures = facteur mineur.","flag":"terrain","src":"226 p. 495"},{"ask":"« Avez-vous un cancer, en cours de traitement ou récent ? »","why":"Cancer actif = facteur permanent et point du score de Wells ; en cas de TVP/EP associée à un cancer, le traitement anticoagulant est prolongé tant que le cancer est actif.","flag":"terrain","src":"226 p. 495, 498, 513"},{"ask":"« Avez-vous déjà eu une phlébite ou une embolie pulmonaire ? »","why":"Un antécédent de TVP ou d'EP est un point du score de Wells ; la récidive est plus fréquente dans la MTEV non provoquée.","flag":"terrain","src":"226 p. 497-498"},{"ask":"« Prenez-vous la pilule ou un traitement hormonal ? Êtes-vous enceinte, ou avez-vous accouché récemment ? »","why":"Contraception œstroprogestative, grossesse, post-partum et traitement hormonal de la ménopause sont des facteurs transitoires majeurs ; la contraception œstroprogestative devient contre-indiquée après une MTEV.","flag":"terrain","src":"226 p. 495, 517"},{"ask":"« Avez-vous une maladie de l'intestin (Crohn, rectocolite) ou une maladie inflammatoire des articulations ? »","why":"Maladies inflammatoires chroniques digestives ou articulaires = facteurs permanents.","flag":"terrain","src":"226 p. 495"},{"ask":"« Dans votre famille, quelqu'un a-t-il fait des phlébites ou des embolies, surtout avant 50 ans ? »","why":"Un antécédent familial au 1er degré de thromboses, avec un premier épisode non provoqué avant 50 ans, justifie de suggérer un bilan de thrombophilie constitutionnelle.","flag":"terrain","src":"226 p. 501"},{"ask":"« Avez-vous eu un AVC, êtes-vous en surpoids important, avez-vous un cathéter veineux ? »","why":"Les patients âgés avec AVC, l'obésité et les accès veineux profonds (cathéters, TVP iatrogènes) sont des situations à risque.","flag":"terrain","src":"226 p. 519"}],"astuce":"Majeur (opération, fracture, alitement, hormones) = TVP provoquée = traitement plus court. Aucun facteur = TVP non provoquée = on cherche la cause (cancer, thrombophilie)."},{"key":"symptome","title":"La jambe douloureuse, décortiquée","goal":"Caractériser douleur et gonflement : unilatéral, brutal, proximal ou distal, inflammatoire ou non.","questions":[{"ask":"« Depuis quand avez-vous mal, et cela est-il arrivé brutalement ? »","why":"Le tableau est plus évocateur quand la survenue est brutale. L'EP survient dans les 3 à 7 jours suivant le début d'une TVP.","flag":"orientation","src":"226 p. 497"},{"ask":"« Où avez-vous mal exactement : mollet, cuisse, aine ? »","why":"Le siège oriente vers une TVP distale (mollet) ou proximale (poplitée, fémorale, iliaque, cave) : le risque d'EP est bien plus important en cas de TVP proximale.","flag":"orientation","src":"226 p. 494, 497"},{"ask":"« La douleur est-elle présente au repos ou seulement quand vous appuyez, marchez ou fléchissez le pied ? »","why":"Le Collège retient une douleur spontanée ou provoquée du membre inférieur, avec sensibilité le long du trajet veineux profond (point de Wells).","flag":"terrain","src":"226 p. 497-498"},{"ask":"« C'est une seule jambe ou les deux ? »","why":"Le Collège décrit une atteinte typiquement unilatérale ou asymétrique. Quand les signes sont dissociés, il liste des diagnostics différentiels : lymphœdème, insuffisance cardiaque droite, rénale ou hépatique.","flag":"orientation","src":"226 p. 497-498"},{"ask":"« Votre jambe a-t-elle gonflé ? Jusqu'où : cheville, mollet, cuisse, toute la jambe ? »","why":"Œdème unilatéral de la jambe ou de tout le membre, d'autant plus étendu que la thrombose est proximale (différence de circonférence > 3 cm avec l'autre).","flag":"orientation","src":"226 p. 497"},{"ask":"« La jambe est-elle chaude, rouge ? »","why":"Des signes inflammatoires font partie du tableau de TVP, mais aussi des diagnostics différentiels (érysipèle, lymphangite, cellulite).","flag":"orientation","src":"226 p. 497-498"},{"ask":"« Avez-vous remarqué des veines plus visibles qu'avant sur la jambe ? »","why":"Dilatation des veines superficielles : signe évocateur ; circulation collatérale superficielle non variqueuse = point de Wells.","flag":"terrain","src":"226 p. 497-498"},{"ask":"« Avez-vous reçu un coup, ressenti un claquage, ou forcé en faisant du sport ? »","why":"Une lésion musculaire ou tendineuse (traumatisme, claquage) est un diagnostic différentiel, à rapprocher d'un Wells où le diagnostic alternatif est au moins aussi probable (−2).","flag":"orientation","src":"226 p. 498"},{"ask":"« Toute la jambe est-elle gonflée et douloureuse, d'un seul côté ? »","why":"Phlegmatia alba dolens = tableau classique le plus évocateur de TVP, atteinte typiquement unilatérale ou asymétrique, plus évocatrice si brutale. Un syndrome obstructif sévère ou une phlegmatia caerulea dolens est un cas particulier : thrombolyse envisageable en sauvetage de membre, compression élastique contre-indiquée.","flag":"gravite","src":"226 p. 497, 513, 515"}],"astuce":"La TVP typique : un seul côté, douleur, gonflement, parfois chaleur. Mais elle peut être totalement asymptomatique et découverte dans le bilan d'une EP."},{"key":"associes","title":"Signes associés : traquer l'embolie pulmonaire","goal":"Ne jamais s'arrêter à la jambe : demander les signes d'EP, présente cliniquement ou non (environ 50 % des TVP proximales ont une EP asymptomatique).","questions":[{"ask":"« Êtes-vous essoufflé, plus que d'habitude ? Depuis quand, brutalement ? »","why":"Dyspnée, douleur thoracique ou syncope : l'EP est suspectée sur l'un de ces signes dans 90 % des cas ; la dyspnée peut être brutale, progressive sur plusieurs semaines ou aggraver une dyspnée chronique.","flag":"gravite","src":"226 p. 504"},{"ask":"« Avez-vous un point de côté, une douleur qui gêne la respiration ? »","why":"Douleur pleurale typique de type point de côté brutal, parfois trompeuse.","flag":"gravite","src":"226 p. 504"},{"ask":"« Avez-vous eu un malaise, une perte de connaissance ? »","why":"Syncope rare mais témoin d'une réduction sévère du flux sanguin systémique.","flag":"gravite","src":"226 p. 504"},{"ask":"« Avez-vous craché du sang ? »","why":"Crachats hémoptoïques rapportés à un infarctus pulmonaire (point de Wells et de Genève).","flag":"gravite","src":"226 p. 504-505"},{"ask":"« Votre cœur bat-il vite ? »","why":"Tachycardie recherchée à l'examen ; les scores de Genève comptent les fréquences cardiaques de 75-94 et ≥ 95 bpm.","flag":"orientation","src":"226 p. 504-505"},{"ask":"« Avez-vous de la fièvre, des frissons ? »","why":"La fièvre est possible dans l'EP, mais elle fait aussi évoquer érysipèle, lymphangite ou cellulite.","flag":"orientation","src":"226 p. 498, 520"},{"ask":"« Avez-vous maigri, perdu l'appétit, vu du sang dans les selles ou les urines ? »","why":"Une recherche de cancer est faite en cas de TVP non provoquée, surtout chez les sujets de plus de 40 ans ; endoscopies digestives, échographie abdominopelvienne et body-scanner sont utiles s'il existe des signes d'orientation clinique.","flag":"terrain","src":"226 p. 502"}],"astuce":"Retiens : dans 2/3 des EP il n'y a aucun signe de TVP, et dans la TVP il peut y avoir une EP muette. Demande toujours « essoufflement, douleur thoracique, malaise »."},{"key":"orientation","title":"Les questions qui orientent","goal":"Éliminer ce qui ressemble à une TVP : le diagnostic différentiel compte dans le score de Wells (−2 s'il est au moins aussi probable).","questions":[{"ask":"« Sentez-vous un cordon dur et rouge sous la peau, le long d'une veine ? »","why":"Thrombose veineuse superficielle, sur le trajet de la grande saphène : douleur sur le trajet veineux, rougeur, cordon induré. Une TVP est associée dans 10 % des cas, donc l'échodoppler reste nécessaire.","if":"Si oui → TVS, échodoppler pour chercher l'extension profonde","flag":"orientation","src":"226 p. 502"},{"ask":"« La douleur vient-elle du dos et descend-elle dans la jambe ? »","why":"Affection neurologique (sciatique) fait partie des diagnostics différentiels.","if":"Si oui → penser à une sciatique","flag":"orientation","src":"226 p. 498"},{"ask":"« Avez-vous les deux jambes gonflées, essoufflé la nuit, des problèmes de cœur, de reins ou de foie ? »","why":"Insuffisance cardiaque droite, rénale ou hépatique figurent parmi les diagnostics différentiels quand les signes sont dissociés (la TVP typique est unilatérale ou asymétrique).","if":"Si œdème non unilatéral → penser à une cause générale plutôt qu'à une TVP","flag":"orientation","src":"226 p. 498"},{"ask":"« Y a-t-il une plaie, une piqûre ou un orteil macéré qui a pu s'infecter ? La peau est-elle rouge et chaude, avec de la fièvre ? »","why":"Érysipèle, lymphangite, cellulite sont des diagnostics différentiels.","if":"Si rougeur étendue fébrile → érysipèle ou cellulite","flag":"orientation","src":"226 p. 498"},{"ask":"« Avez-vous déjà eu une phlébite il y a longtemps ? La jambe est-elle lourde et gonflée en fin de journée depuis des mois ? »","why":"Syndrome post-thrombotique et insuffisance veineuse primaire (superficielle ou profonde) : lourdeur de jambe, dilatations veineuses, œdème de cheville, troubles trophiques.","if":"Si installation lente et chronique → SPT ou insuffisance veineuse","flag":"orientation","src":"226 p. 498, 503"},{"ask":"« Avez-vous une boule derrière le genou, une articulation douloureuse ? »","why":"Une affection ostéoarticulaire, notamment un kyste synovial, est un diagnostic différentiel.","if":"Si oui → kyste synovial possible","flag":"orientation","src":"226 p. 498"},{"ask":"« Avez-vous une grossesse, une masse abdominale, des ganglions ? »","why":"Compression extrinsèque (adénopathies, tumeur, utérus gravide) ; gonflement du membre peut aussi traduire un lymphœdème.","if":"Si oui → penser à une compression extrinsèque","flag":"orientation","src":"226 p. 498"}],"astuce":"Un seul côté, brutal, avec facteur favorisant = TVP. Signes dissociés, cause cardiaque, rénale ou hépatique = pense au diagnostic différentiel. Rouge et fébrile = pense à l'érysipèle, la lymphangite, la cellulite."},{"key":"examen","title":"Examen clinique ciblé","goal":"Objectiver l'œdème et la sensibilité (points de Wells), éliminer d'autres causes, et chercher des signes d'EP.","questions":[{"ask":"Comparer les deux jambes à l'inspection : volume, couleur, chaleur, veines superficielles","why":"Œdème unilatéral, signes inflammatoires, dilatation des veines superficielles ; pâleur (alba) ou cyanose (caerulea).","src":"226 p. 497"},{"ask":"Mesurer le périmètre du mollet à 10 cm sous la tubérosité tibiale antérieure, des deux côtés","why":"Un œdème du mollet > 3 cm par rapport au côté controlatéral est un point de Wells.","src":"226 p. 497-498"},{"ask":"Rechercher un œdème prenant le godet et un œdème de tout le membre","why":"Points de Wells : œdème unilatéral prenant le godet ; œdème généralisé du membre inférieur.","src":"226 p. 498"},{"ask":"Palper le trajet des veines profondes (mollet, creux poplité, cuisse)","why":"La sensibilité le long du trajet veineux profond est un point de Wells.","src":"226 p. 498"},{"ask":"Rechercher un cordon de veine superficielle et des signes d'érysipèle","why":"Cordon induré rouge sur la saphène (TVS) ; rougeur étendue (érysipèle, cellulite).","src":"226 p. 498, 502"},{"ask":"Chercher une cause de compression extrinsèque : palper les aires ganglionnaires, l'abdomen, l'utérus gravide","why":"Adénopathies, tumeur, utérus gravide.","src":"226 p. 498"},{"ask":"Prendre FC, FR, PA, saturation, température, rechercher une cyanose","why":"L'examen recherche tachypnée > 20/min, tachycardie > 100 bpm, signes de TVP ou cyanose ; la fièvre est possible. Hypotension et signes d'insuffisance cardiaque droite = retentissement hémodynamique.","src":"226 p. 504, 520"},{"ask":"Auscultation cardiopulmonaire, jugulaires","why":"Dans la vignette du Collège (EP), l'auscultation cardiopulmonaire est normale. Distension des veines jugulaires et souffle d'insuffisance tricuspide sont des signes de dysfonction du ventricule droit.","src":"226 p. 494, 509"},{"ask":"Calculer le score de Wells (TVP) avant les examens paracliniques","why":"Probabilité faible (0 point, ~3 %), intermédiaire (1-2 points, ~17 %) ou forte (≥ 3 points, ~75 %) ; il renforce la valeur des tests.","src":"226 p. 498"}],"astuce":"Wells TVP : 9 critères à +1 (cancer, immobilisation/plâtre, chirurgie ou alitement, antécédent, sensibilité, œdème du membre, mollet > 3 cm, godet, collatérales) et un −2 (diagnostic alternatif aussi probable)."},{"key":"gravite","title":"Signes de gravité (à chercher d'emblée)","goal":"Repérer l'EP, surtout avec choc, et les TVP qui justifient une hospitalisation ou un geste de sauvetage du membre.","questions":[{"ask":"Hypotension ou choc : PAS < 90 mmHg ou baisse de la PAS > 40 mmHg pendant plus de 15 minutes","why":"EP à haut risque (mortalité > 15 %) : stratégie diagnostique et traitement différents, réanimation ou Usic, fibrinolyse.","flag":"gravite","src":"226 p. 509, 511"},{"ask":"Dyspnée aiguë, syncope, douleur thoracique, saturation < 90 %","why":"Signes d'EP ; la saturation < 90 % est un élément du score sPESI et justifie une gazométrie.","flag":"gravite","src":"226 p. 504, 509"},{"ask":"Éléments du sPESI : âge > 80 ans, saturation < 90 %, PAS < 100 mmHg, FC > 110 bpm, cancer, insuffisance cardiaque ou maladie pulmonaire chronique","why":"Mnémonique 80, 90, 100, 110. Mortalité d'environ 1 % si score = 0 contre environ 10 % si score ≥ 1.","flag":"gravite","src":"226 p. 509"},{"ask":"Signes de souffrance du ventricule droit : jugulaires turgescentes, souffle d'insuffisance tricuspide, ECG (T négatives V1-V4, S1Q3, BBD)","why":"Marqueurs de dysfonction VD qui classent l'EP à risque intermédiaire.","flag":"gravite","src":"226 p. 504, 509"},{"ask":"Phlegmatia caerulea dolens ou syndrome obstructif sévère","why":"Cas où la thrombolyse peut être envisagée en situation de sauvetage de membre ; la phlegmatia caerulea dolens est une contre-indication à la compression élastique.","flag":"gravite","src":"226 p. 513, 515"},{"ask":"TVP proximale avec syndrome obstructif sévère ou localisation iliocave","why":"Fait partie des indications d'hospitalisation pour TVP proximale.","flag":"gravite","src":"226 p. 515"},{"ask":"Insuffisance rénale sévère (clairance < 30 mL/min), risque hémorragique, contexte psychosocial défavorable","why":"Insuffisants rénaux sévères et patients à risque hémorragique sont hospitalisés ; HBPM, fondaparinux et AOD sont contre-indiqués si DFG < 30 mL/min (HNF recommandée).","flag":"gravite","src":"226 p. 511-513, 515"},{"ask":"Cancer actif, grossesse","why":"Cancer actif : le traitement par AVK est moins efficace et moins bien toléré, on prolonge une HBPM tant que le cancer est actif. Grossesse : le traitement repose sur les HBPM.","flag":"terrain","src":"226 p. 517-518"}],"astuce":"Pour la TVP, la vraie question de gravité est « y a-t-il une EP ? ». Choc ou hypotension = EP à haut risque ; sinon on stratifie avec le sPESI."},{"key":"examens","title":"Examens de 1re intention","goal":"Confirmer objectivement la TVP : score de probabilité, D-dimères pour exclure, échodoppler veineux pour confirmer, sans retarder le traitement si la probabilité est intermédiaire ou forte.","questions":[{"ask":"Score de Wells, puis choisir : D-dimères ou échodoppler direct","why":"La stratégie repose sur le score de probabilité clinique, les D-dimères et l'échodoppler (fig. 19.1) : pas de dosage des D-dimères si âge ≥ 80 ans, cancer ou chirurgie dans les 30 jours ; sinon dosage, négatif = TVP éliminée. Les D-dimères servent essentiellement à exclure la MTEV si probabilité faible ou intermédiaire.","src":"226 p. 498, 500, 519"},{"ask":"D-dimères avec un test Elisa rapide (seuil < 500 ng/mL)","why":"Sensibilité > 95 % et valeur prédictive négative > 95 % : servent à éliminer la TVP, pas à la confirmer (spécificité faible : âge, inflammation, cancer, traumatisme, post-opératoire, grossesse).","src":"226 p. 499"},{"ask":"Échodoppler veineux des membres inférieurs, examen de 1re intention pour confirmer","why":"Sensibilité et spécificité > 95 %. Critères : image directe du thrombus, incompressibilité de la veine à la sonde, modification du signal doppler. Veine normale : compressible, sans matériel endoluminal.","src":"226 p. 499-500"},{"ask":"Si probabilité intermédiaire ou forte : contention + anticoagulation curative sans attendre ; échodoppler systématique dans les 24-48 h ou si possible en urgence","why":"Traitement anticoagulant dès la suspicion en cas de probabilité forte ou intermédiaire, en l'absence de risque hémorragique important, dans l'attente du résultat.","src":"226 p. 500, 510, 519"},{"ask":"Avant traitement : NFS-plaquettes, bilan d'hémostase (Quick, TCA, fibrinogène), créatininémie avec DFG","why":"Nécessaires avant d'anticoaguler ; plaquettes de base avant héparine (risque de thrombopénie induite).","src":"226 p. 510, 512"},{"ask":"Si signes respiratoires : radiographie de thorax, ECG, gazométrie artérielle si saturation < 90 %, puis score de Genève ou Wells EP","why":"Examens d'orientation indispensables pour l'EP. La radiographie élimine une autre cause de dyspnée, l'ECG montre tachycardie sinusale ou signes VD.","src":"226 p. 504-505, 521"},{"ask":"Angioscanner pulmonaire si l'EP est suspectée","why":"Examen le plus performant pour l'EP (l'angioscanner permet de confirmer le diagnostic). Si le scanner est impossible, l'échodoppler veineux peut aider : une TVP proximale suffit pour confirmer l'EP et débuter le traitement.","src":"226 p. 506-507, 521"},{"ask":"Si TVP non provoquée : recherche de cancer (PSA chez l'homme ; examen gynécologique, mammographie et échographie pelvienne chez la femme ; sang dans les selles ; radiographie thoracique)","why":"Surtout chez les sujets de plus de 40 ans ou si le bilan de thrombophilie est négatif. Surveillance clinique d'au moins 1 an.","src":"226 p. 502"},{"ask":"Bilan de thrombophilie seulement dans les indications ciblées, à 3-6 mois","why":"Non systématique après un premier épisode ; suggéré en cas de premier épisode non provoqué avant 50 ans avec antécédent familial 1er degré, MTEV récidivante, ou thrombose de site atypique.","src":"226 p. 501-502"}],"astuce":"D-dimères d'abord (sauf ≥ 80 ans, cancer, chirurgie < 30 jours) : négatifs, on arrête. Sinon : probabilité intermédiaire ou forte, on traite sans attendre ; dans tous les cas, échodoppler. D-dimères = pour exclure, jamais pour confirmer."}],"synthese":"Monsieur T., 66 ans, opéré d'une prothèse de hanche il y a 3 semaines, consulte pour une douleur du mollet gauche avec gonflement apparu il y a 2 jours, sans dyspnée ni douleur thoracique. À l'examen : mollet gauche augmenté de 4 cm par rapport au droit, œdème prenant le godet, sensibilité le long du trajet veineux profond, FC 88 bpm, SpO2 97 %. Score de Wells à 4 (probabilité forte). Hypothèses : thrombose veineuse profonde du membre inférieur gauche (proximale ou distale) provoquée par la chirurgie, avec risque d'EP à rechercher ; diagnostics différentiels : lésion musculaire, kyste synovial, érysipèle.","hypotheses":[{"dx":"Thrombose veineuse profonde proximale","pour":"Œdème étendu à toute la jambe, > 3 cm de différence, sensibilité le long du trajet veineux profond, facteur déclenchant majeur ; risque d'EP élevé, risque évolutif extrême sans anticoagulation.","danger":true,"src":"226 p. 494, 497-498"},{"dx":"Embolie pulmonaire associée (parfois asymptomatique)","pour":"Dyspnée, point de côté, syncope, tachycardie, hémoptysie ; environ 50 % des TVP proximales ont une EP à l'angioscanner ; signes de TVP absents dans deux tiers des EP.","danger":true,"src":"226 p. 494-495, 504, 520"},{"dx":"Thrombose veineuse profonde distale (veines jambières ou surales)","pour":"Souvent asymptomatique ; rarement responsable d'une EP aux conséquences cliniques importantes ; environ 25 % des TVP distales asymptomatiques s'étendent en proximal.","danger":false,"src":"226 p. 494, 519"},{"dx":"Thrombose veineuse superficielle","pour":"Cordon induré rouge sur la grande saphène, douleur sur le trajet ; TVP associée dans 10 % des cas.","danger":false,"src":"226 p. 502"},{"dx":"Lésion musculaire ou tendineuse, kyste synovial","pour":"Signes dissociés, traumatisme ou claquage musculaire, kyste synovial.","danger":false,"src":"226 p. 498"},{"dx":"Érysipèle, lymphangite, cellulite","pour":"Signes inflammatoires avec signes dissociés : érysipèle, lymphangite, cellulite sont des diagnostics différentiels ; la fièvre est possible.","danger":false,"src":"226 p. 498"},{"dx":"Syndrome post-thrombotique, insuffisance veineuse, lymphœdème","pour":"Syndrome post-thrombotique, quelques mois ou années après une TVP : lourdeur de jambe, dilatations veineuses superficielles, œdème de cheville, troubles trophiques.","danger":false,"src":"226 p. 498, 503"},{"dx":"Œdème d'origine générale (insuffisance cardiaque droite, rénale, hépatique)","pour":"Signes dissociés, œdème non typiquement unilatéral ; signes d'insuffisance cardiaque droite, rénale ou hépatique.","danger":false,"src":"226 p. 498"}],"pieges":["La clinique seule n'a qu'une valeur d'orientation : toute TVP exige une confirmation objective.","Les D-dimères servent à exclure, pas à confirmer : spécificité faible (âge, cancer, post-op, grossesse).","Probabilité forte ou intermédiaire : traiter sans attendre le résultat, sauf risque hémorragique important.","Toujours chercher l'EP : environ 50 % des TVP proximales en ont une, et les signes de TVP manquent dans deux tiers des EP.","Pas d'alitement : lever précoce, compression de classe 3 (30-40 mmHg) sauf AOMI avec IPS < 0,6 ou phlegmatia caerulea.","Après une MTEV, la contraception œstroprogestative est contre-indiquée ; pas de bilan de thrombophilie systématique."],"src":"226 p. 493-522 (surtout 495-502, 504-505, 509-511, 515)"},{"id":"membre-ischemique","spe":"cardio","title":"Membre douloureux, froid et pâle","emoji":"🧊","items":["225"],"hook":"Jambe brutalement douloureuse, froide et sans pouls = ischémie aiguë : une urgence vasculaire où le temps, c'est le membre, et où aucun examen ne doit retarder la revascularisation.","intro":"Les nerfs souffrent dès 2 heures, les muscles à 6-8 heures, la peau nécrose après 24 heures : chaque question doit donc être rapide. Ton état d'esprit : confirmer le diagnostic à la clinique, graduer la sévérité (sensibilité, motricité), distinguer embolie sur artère saine et thrombose in situ sur AOMI, alerter le chirurgien vasculaire et mettre l'héparine en route.","steps":[{"key":"terrain","title":"Terrain et antécédents","goal":"Deviner d'emblée si c'est plutôt une thrombose sur artère malade (AOMI) ou une embolie sur artère saine d'origine cardiaque.","questions":[{"ask":"« Quel âge avez-vous ? Fumez-vous, êtes-vous diabétique, hypertendu, avez-vous du cholestérol ? »","why":"La thrombose artérielle in situ concerne le plus souvent un sujet âgé avec facteurs de risque cardiovasculaire, voire un tableau préexistant d'AOMI. L'AOMI est une des étiologies de l'ischémie aiguë (et plus de 95 % des atteintes artérielles oblitérantes des membres inférieurs) ; tabagisme et diabète en sont les deux principaux facteurs de risque.","flag":"terrain","src":"225 p. 168, 174, 181"},{"ask":"« Aviez-vous déjà mal aux jambes en marchant ? Vous a-t-on parlé d'artérite, de pontage ou de stent aux jambes ? »","why":"Un tableau préexistant d'AOMI oriente vers la thrombose in situ ; il faut aussi le rechercher sur l'autre membre. Pontages et stents peuvent se thromboser.","flag":"orientation","src":"225 p. 176, 181"},{"ask":"« Avez-vous une maladie du cœur : trouble du rythme (fibrillation atriale), infarctus récent, valve artificielle, endocardite ? »","why":"Causes cardiaques d'embolie : troubles du rythme (FA), infarctus (faux anévrisme de paroi), endocardite, valvulopathies et prothèses valvulaires, tumeurs cardiaques (myxome), anévrisme ou dyskinésie ventriculaire gauche, foramen ovale perméable.","flag":"orientation","src":"225 p. 181"},{"ask":"« Avez-vous eu des palpitations ces derniers jours ? »","why":"L'embolie peut suivre des épisodes de palpitations traduisant une arythmie cardiaque.","flag":"orientation","src":"225 p. 181"},{"ask":"« Vous a-t-on dit que vous aviez un anévrisme, de l'aorte ou derrière le genou ? »","why":"Anévrisme poplité thrombosé (cause de thrombose in situ), anévrisme aortique (source d'embolie) ; l'anévrisme poplité est associé à un AAA dans 30 % des cas.","flag":"terrain","src":"225 p. 181, 186"},{"ask":"« Avez-vous eu récemment un cathétérisme, un traitement par héparine, ou pris des dérivés de l'ergot de seigle ? »","why":"Causes iatrogènes de thrombose artérielle : cathétérisme, thrombopénie à l'héparine, ergotisme.","flag":"terrain","src":"225 p. 181"},{"ask":"« Avez-vous été déshydraté ces derniers jours (peu bu, fièvre, diarrhée) ? »","why":"Déshydratation et hémoconcentration chez le sujet âgé favorisent la thrombose in situ.","flag":"terrain","src":"225 p. 181"},{"ask":"« Avez-vous une maladie inflammatoire des vaisseaux (Horton, Takayasu, Buerger), un lupus, une radiothérapie ou un traumatisme ancien du membre ? »","why":"Artériopathies non athéromateuses : inflammatoires, radiques, post-traumatiques ; elles peuvent se thromboser.","flag":"terrain","src":"225 p. 174, 181"}],"astuce":"Deux grands tableaux : le vieux fumeur artéritique qui se bouche (thrombose), et le patient avec un cœur en arythmie dont un caillot part (embolie). Ils ne sont pas toujours aussi distincts, garde l'esprit ouvert."},{"key":"symptome","title":"La douleur et le membre, décortiqués","goal":"Dater précisément l'ischémie, localiser l'occlusion et graduer la sévérité (sensibilité, motricité) : c'est ça qui décide de l'urgence.","questions":[{"ask":"« À quelle heure exactement la douleur a-t-elle commencé ? Que faisiez-vous ? »","why":"Chronologie de la souffrance tissulaire : cellules nerveuses dans les 2 heures, muscles dans les 6-8 heures (rhabdomyolyse), nécrose cutanée à partir de la 24e heure. La douleur est d'apparition brutale (parfois en quelques heures dans la forme subaiguë).","flag":"gravite","src":"225 p. 178-179"},{"ask":"« La douleur est-elle venue d'un coup, comme un coup de poignard, ou progressivement ? »","why":"Brutale, aiguë et sévère (absence de collatérales) = embolie sur artère saine ; d'intensité moyenne et d'installation progressive ou rapide (collatéralité préalable) = thrombose in situ.","flag":"orientation","src":"225 p. 181"},{"ask":"« Où avez-vous mal : pied, mollet, cuisse, fesse ? »","why":"Repère la zone touchée : l'examen estimera la topographie de l'occlusion par la localisation de la froideur du membre et l'abolition des pouls en aval.","flag":"orientation","src":"225 p. 179"},{"ask":"« Comment est la douleur : un broiement, un étau ? Quelle note sur 10 ? »","why":"Intense, à type de broiement, avec impotence fonctionnelle du membre. Les antalgiques de niveau 3 sont souvent nécessaires d'emblée.","flag":"terrain","src":"225 p. 179, 182"},{"ask":"« Votre jambe est-elle froide ? Avez-vous vu sa couleur changer ? »","why":"Membre froid, livide : signe physique majeur, à comparer à l'autre côté.","flag":"terrain","src":"225 p. 179"},{"ask":"« Sentez-vous encore votre pied et vos orteils ? Avez-vous des fourmillements ou un engourdissement ? »","why":"Le déficit sensitif distingue ischémie viable, menaçante et irréversible : absent (grade I), limité aux orteils (IIa), au-delà des orteils (IIb), anesthésie importante (III).","flag":"gravite","src":"225 p. 179"},{"ask":"« Arrivez-vous à bouger vos orteils et à relever le pied ? »","why":"Déficit moteur modéré (IIb) ou paralysie (III) ; la paralysie du nerf fibulaire commun empêche de relever le pied.","flag":"gravite","src":"225 p. 179"},{"ask":"« Les deux jambes sont-elles touchées ? Avez-vous eu un malaise ? »","why":"L'occlusion de la bifurcation aortique donne une ischémie bilatérale sévère avec paralysie sensitivomotrice, souvent des signes généraux jusqu'au collapsus cardiovasculaire.","flag":"gravite","src":"225 p. 179"}],"astuce":"Retiens les 5 signes de l'ischémie aiguë : douleur brutale, membre froid, membre livide, pouls abolis en aval, puis la neurologie (anesthésie, paralysie) qui donne le grade."},{"key":"associes","title":"Signes associés","goal":"Chercher la source embolique et les autres territoires touchés (embolies multiples).","questions":[{"ask":"« Votre cœur s'emballe-t-il, battait-il de façon irrégulière ? »","why":"Les troubles du rythme (fibrillation atriale) figurent parmi les causes cardiaques d'embolie, et l'embolie peut suivre des épisodes de palpitations. L'auscultation cardiaque et l'ECG sont systématiques.","flag":"orientation","src":"225 p. 181-182"},{"ask":"« Avez-vous eu une douleur dans la poitrine ou été essoufflé récemment ? »","why":"Infarctus du myocarde (avec notamment un faux anévrisme de paroi) et dyskinésie ou anévrisme ventriculaire gauche sont des causes cardiaques d'embolie ; la fonction cardiaque doit être évaluée rapidement.","flag":"orientation","src":"225 p. 181-182"},{"ask":"« Avez-vous eu un déficit de force, un trouble de la parole ou de la vision ? »","why":"La recherche d'autres localisations ischémiques est nécessaire (embolies multiples).","flag":"gravite","src":"225 p. 182"},{"ask":"« Avez-vous mal au ventre, vomi, eu la diarrhée ? »","why":"Une ischémie mésentérique aiguë embolique associe douleur abdominale aiguë avec peu de signes physiques, vidange digestive accélérée et fibrillation atriale : autre territoire d'embolie.","flag":"gravite","src":"225 p. 167"},{"ask":"« Avez-vous de la fièvre, des frissons ces derniers temps ? »","why":"L'endocardite infectieuse fait partie des causes cardiaques d'embolie artérielle.","flag":"orientation","src":"225 p. 181"},{"ask":"« Vos urines sont-elles foncées ou rares ? »","why":"Myoglobinurie et insuffisance rénale aiguë sont à craindre (rhabdomyolyse, reperfusion) ; on surveille la diurèse.","flag":"gravite","src":"225 p. 178-179, 183"},{"ask":"« Avez-vous eu une douleur dans le dos ou le ventre au même moment ? »","why":"Une dissection aorto-iliaque, un anévrisme de l'aorte (thrombose intra-anévrismale emboligène) ou l'athérome aortique peuvent expliquer une ischémie aiguë.","flag":"orientation","src":"225 p. 181, 184"}],"astuce":"Une embolie ne vient jamais seule dans l'esprit : cœur, aorte, et autres territoires (cerveau, intestin)."},{"key":"orientation","title":"Les questions qui orientent","goal":"Trancher entre embolie sur artère saine et thrombose in situ, car cela change la stratégie (Fogarty, thrombolyse, pontage) et la recherche étiologique.","questions":[{"ask":"« Cette douleur est-elle venue en quelques minutes, sans aucun signe avant ? »","why":"L'embolie sur artère saine se manifeste par une douleur brutale, aiguë et sévère (absence de collatérales), classiquement chez un sujet jeune sans antécédent vasculaire connu. Attention : une thrombose in situ peut aussi survenir sans signe préalable d'AOMI.","if":"Si oui → plutôt une embolie sur artère saine : chercher la source cardiaque","flag":"orientation","src":"225 p. 181"},{"ask":"« Avant cela, aviez-vous mal en marchant, aux mollets ou aux fesses ? Quelle distance pouviez-vous parcourir ? »","why":"Un tableau préexistant d'AOMI oriente vers une thrombose in situ ; il est à rechercher aussi sur l'autre membre.","if":"Si oui → thrombose in situ sur AOMI","flag":"orientation","src":"225 p. 168, 181"},{"ask":"« Avez-vous un trouble du rythme connu, un traitement anticoagulant que vous avez arrêté ? »","why":"Une cardiopathie emboligène connue oriente vers l'embolie ; l'anticoagulation au long cours sera à envisager ensuite.","if":"Si oui → embolie d'origine cardiaque","flag":"orientation","src":"225 p. 181, 183"},{"ask":"« Êtes-vous plutôt jeune, sans antécédent vasculaire ? »","why":"L'embolie survient classiquement chez un sujet jeune sans antécédent vasculaire (mais éventuellement cardiopathe).","flag":"terrain","src":"225 p. 181"},{"ask":"« L'autre jambe est-elle normale ? Y sentez-vous bien le pouls ? »","why":"Un tableau préexistant d'AOMI est à rechercher sur l'autre membre ; les deux tableaux ne sont pas toujours distincts (une embolie peut survenir sur des artères déjà atteintes).","flag":"orientation","src":"225 p. 181"}],"astuce":"Embolie = brutal, intense, source cardiaque ou aortique ; thrombose = plus progressif, artérite connue, facteurs de risque. Mais une plaque peut se rompre sans signe préalable."},{"key":"examen","title":"Examen clinique ciblé","goal":"Confirmer le diagnostic, localiser l'occlusion et graduer la sévérité, le tout en comparant les deux membres.","questions":[{"ask":"Comparer les deux membres : couleur, température, temps de recoloration cutanée","why":"Membre froid et livide ; le temps de recoloration est allongé (normal < 3 secondes).","src":"225 p. 170, 179"},{"ask":"Palper les pouls bilatéralement : fémoral, poplité, tibial postérieur, pédieux","why":"Abolition des pouls en aval de l'occlusion. Le pédieux est absent chez 5 % des gens : toujours comparer au côté opposé.","src":"225 p. 170, 179"},{"ask":"Palper les masses musculaires du mollet","why":"La douleur à la palpation des masses musculaires est un signe d'ischémie sévère.","src":"225 p. 170, 179"},{"ask":"Examen de la sensibilité : orteils, puis au-delà, comparatif","why":"Absente (grade I), limitée aux orteils (IIa), au-delà (IIb), anesthésie importante (III).","src":"225 p. 179"},{"ask":"Examen moteur : mobiliser orteils, cheville, relever le pied","why":"Déficit modéré (IIb) ou paralysie (III), notamment du nerf fibulaire commun.","src":"225 p. 179"},{"ask":"Auscultation cardiaque et prise du pouls : rythme irrégulier ?","why":"Toujours compléter par auscultation cardiaque à la recherche d'une cause emboligène (arythmie, souffle, prothèse).","src":"225 p. 182"},{"ask":"Palpation de l'abdomen et du creux poplité","why":"Recherche d'un anévrisme aortique ; au creux poplité, une masse battante évoque un anévrisme poplité.","src":"225 p. 170, 182, 186"},{"ask":"Auscultation des trajets vasculaires et mesure de la pression artérielle","why":"L'auscultation recherche un souffle sur les trajets vasculaires. La pression artérielle systémique doit être maintenue à un niveau correct : elle conditionne la baisse du débit artériel.","src":"225 p. 170, 178"},{"ask":"Rechercher d'autres signes d'ischémie : autre membre, abdomen, neurologie","why":"Embolies multiples possibles ; évaluer l'état général, la fonction cardiaque et les comorbidités.","src":"225 p. 182"}],"astuce":"Toujours deux jambes, jamais une seule. Ton œil et ta main d'abord : le diagnostic est essentiellement clinique."},{"key":"gravite","title":"Signes de gravité (à chercher d'emblée)","goal":"Classer en grade viable, menaçant ou irréversible, et anticiper le syndrome de reperfusion.","questions":[{"ask":"Déficit sensitif au-delà des orteils ou déficit moteur : grade IIb","why":"Ischémie immédiatement menaçante (IIb) : récupération possible si prise en charge immédiate. Aucune exploration ne doit retarder l'intervention en cas d'atteinte neurologique (grade II).","flag":"gravite","src":"225 p. 179-180"},{"ask":"Anesthésie importante et paralysie : grade III","why":"Irréversible, perte de tissus et déficit séquellaire inévitables : amputation (ischémie dépassée).","flag":"gravite","src":"225 p. 179-180, 183"},{"ask":"Syndrome des loges : œdème dans des loges aponévrotiques inextensibles, avec compression des tissus","why":"L'œdème dans des loges inextensibles comprime les tissus jusqu'à l'arrêt total de circulation ; seule une aponévrotomie de décharge libère le muscle. Elle est systématique en cas de revascularisation tardive.","flag":"gravite","src":"225 p. 178, 183"},{"ask":"Ischémie bilatérale avec choc : occlusion de la bifurcation aortique","why":"Cas le plus grave : ischémie bilatérale sévère avec paralysie, signes généraux au premier plan jusqu'au collapsus.","flag":"gravite","src":"225 p. 179"},{"ask":"Surveiller l'hyperkaliémie, l'acidose, la myoglobinurie et la diurèse après reperfusion","why":"Syndrome de revascularisation : hyperkaliémie, acidose métabolique, hyperuricémie, myoglobinémie, hypocalcémie, insuffisance rénale aiguë, parfois CIVD ou choc.","flag":"gravite","src":"225 p. 178-179, 183"},{"ask":"Autres territoires ischémiques et état général du patient","why":"Embolies multiples possibles. L'état général est à prendre en compte (pathologie incurable ou fortement handicapante) ; une prise en charge palliative est parfois la seule solution pour un malade très âgé et moribond.","flag":"orientation","src":"225 p. 182"}],"astuce":"Grade I = urgence relative, IIa = discrètement menaçante (récupérable si prise en charge), IIb = immédiatement menaçante, III = irréversible. La sensibilité et la motricité font la différence."},{"key":"examens","title":"Examens et gestes de 1re intention","goal":"Traiter sans perdre une minute : alerter l'équipe chirurgicale, anticoaguler, soulager, et ne rien faire qui retarde la revascularisation.","questions":[{"ask":"Alerter immédiatement l'équipe de chirurgie vasculaire","why":"Le diagnostic reste clinique ; aucune exploration ne doit retarder l'intervention, notamment en cas d'atteinte neurologique (grade II).","src":"225 p. 179-180"},{"ask":"Conduite selon le grade (fig. 7.7)","why":"Pour tous : héparine et antalgiques dès que possible, soins locaux. Viable (grade I) : imagerie en urgence puis revascularisation dans les heures à venir. Viable avec déficit sensitif (grade II) : revascularisation en urgence absolue. Irréversible (grade III) : amputation.","flag":"gravite","src":"225 p. 180"},{"ask":"Héparine non fractionnée IV dès le diagnostic (bolus 5 000 UI puis 500 UI/kg/j, TCA entre 2 et 3), après avoir prélevé le bilan de coagulation","why":"Traitement anticoagulant de première intention dans tous les grades.","src":"225 p. 182"},{"ask":"Antalgiques de niveau 3, oxygène nasal, remplissage si besoin, soins locaux (protection, position légèrement déclive, éviter les frottements)","why":"Traitement médical immédiat, à poursuivre au-delà de la revascularisation.","src":"225 p. 182"},{"ask":"ECG et bilan de coagulation","why":"Rechercher une arythmie emboligène ; le bilan de coagulation est nécessaire. Les autres examens cardiaques viennent après la revascularisation.","src":"225 p. 182"},{"ask":"Échodoppler seulement si cela ne fait pas perdre de temps (surtout grade I sans atteinte neurologique)","why":"Peut être réalisé sans perte de temps si les conditions locales et la gravité le permettent.","src":"225 p. 180"},{"ask":"Artériographie, le plus souvent au bloc opératoire","why":"Localise l'occlusion, caractérise sa nature, apprécie le réseau d'aval, et peut révéler d'autres emboles asymptomatiques.","src":"225 p. 180"},{"ask":"Ionogramme, urée, créatininémie, CPK, surveillance horaire de la diurèse","why":"Dépister acidose hyperkaliémique et insuffisance rénale aiguë, systématiquement après reperfusion.","src":"225 p. 183"},{"ask":"Après revascularisation : bilan cardiaque (Holter ECG, ETT, ETO, IRM) et artériel (échodoppler aorte et membres inférieurs, angioscanner)","why":"Bilan étiologique à faire une fois le membre sauvé, pour décider d'un traitement étiologique (ex. anticoagulation au long cours en cas de FA, antiagrégant si origine thrombotique).","src":"225 p. 182-183"}],"astuce":"Ordre : appeler le chirurgien, héparine, antalgiques, bloc. L'ETT et le Holter, c'est pour après."}],"synthese":"Monsieur D., 76 ans, hypertendu, en fibrillation atriale non anticoagulée, consulte pour une douleur très intense du pied et de la jambe droite apparue brutalement il y a 4 heures, avec impossibilité de bouger les orteils. À l'examen : jambe droite froide et livide, pouls fémoral présent, poplité et distaux abolis, anesthésie au-delà des orteils et déficit moteur modéré, pouls gauches présents. Hypothèses : ischémie aiguë de membre inférieur (grade IIb) par embolie d'origine cardiaque sur fibrillation atriale ; thrombose in situ sur AOMI ; anévrisme poplité thrombosé.","hypotheses":[{"dx":"Embolie artérielle sur artère saine (origine cardiaque)","pour":"Douleur brutale et sévère, absence de collatérales, FA ou autre cardiopathie emboligène, sujet parfois jeune sans AOMI.","danger":true,"src":"225 p. 181"},{"dx":"Thrombose artérielle in situ sur AOMI","pour":"Sujet âgé avec facteurs de risque, tableau préexistant d'AOMI (à rechercher sur l'autre membre), douleur d'intensité moyenne de survenue progressive ou rapide.","danger":true,"src":"225 p. 181"},{"dx":"Anévrisme poplité thrombosé","pour":"Cause de thrombose in situ ; masse battante au creux poplité ; anévrismes poplités fréquemment associés à un AAA (30 % des cas) et bilatéraux dans près de la moitié des cas.","danger":true,"src":"225 p. 181, 186"},{"dx":"Dissection aorto-iliaque","pour":"Cause de thrombose in situ sur artère initialement saine ; à évoquer en l'absence d'AOMI et de cardiopathie emboligène.","danger":true,"src":"225 p. 181"},{"dx":"Occlusion de la bifurcation aortique","pour":"Ischémie bilatérale sévère avec paralysie sensitivomotrice, signes généraux, collapsus.","danger":true,"src":"225 p. 179"},{"dx":"Thrombose iatrogène (cathétérisme, thrombopénie à l'héparine, ergotisme) ou hémoconcentration","pour":"Geste artériel récent, héparine en cours, déshydratation du sujet âgé.","danger":false,"src":"225 p. 181"}],"pieges":["Ischémie aiguë = urgence : ne retarde aucune revascularisation par des examens d'imagerie inutiles.","Comparer toujours aux deux membres ; le pédieux est absent chez 5 % des gens.","Héparine d'emblée, après avoir prélevé le bilan de coagulation.","Embolie et thrombose ne sont pas toujours aussi distinctes : une embolie peut survenir sur AOMI.","Revascularisation tardive = aponévrotomie ; surveiller kaliémie, acidose, créatinine et diurèse à la reperfusion.","ECG, auscultation cardiaque et palpation abdominale (anévrisme) systématiques à la recherche de la cause."],"src":"225 p. 164-189 (surtout 170, 178-183)"},{"id":"claudication","spe":"cardio","title":"Douleur de jambe à la marche","emoji":"🚶","items":["225","221"],"hook":"Une crampe de mollet qui t'arrête à la marche et cède à l'arrêt, c'est une artérite jusqu'à preuve du contraire, et c'est surtout le signe d'un patient polyathéromateux à haut risque cardiovasculaire.","intro":"La claudication intermittente est le symptôme d'effort de l'AOMI, troisième localisation de l'athérosclérose après le cœur et le cerveau. Tu cherches à caractériser la douleur (siège, distance, délai de disparition), à éliminer les diagnostics différentiels, à repérer le stade de gravité (repos, plaies) et à dépister les autres territoires atteints : coronaires, carotides, aorte.","steps":[{"key":"terrain","title":"Terrain et antécédents","goal":"Évaluer les facteurs de risque d'athérome et repérer un patient déjà polyvasculaire.","questions":[{"ask":"« Fumez-vous, ou avez-vous fumé ? Combien de paquets par jour, depuis quand ? »","why":"Le tabagisme est un des deux principaux facteurs de risque d'AOMI (plus fréquent chez le sujet plus jeune) et, parmi tous les facteurs de risque, le plus fortement associé aux lésions de l'aorte.","flag":"terrain","src":"225 p. 166, 168"},{"ask":"« Êtes-vous diabétique ? Depuis quand, comment est-il équilibré ? »","why":"Le diabète est le 2e grand facteur de risque : formes graves d'emblée, atteinte plus distale, pronostic plus sévère ; il peut aussi masquer les symptômes par neuropathie.","flag":"terrain","src":"225 p. 168-169"},{"ask":"« Avez-vous de la tension, du cholestérol ? »","why":"Hypercholestérolémie et HTA sont les autres facteurs fréquemment associés. Les FDR modifiables principaux sont tabac, HTA, dyslipidémies et diabète.","flag":"terrain","src":"225 p. 168 ; 221 p. 39"},{"ask":"« Avez-vous déjà eu un infarctus, un angor, des stents ? Un AVC, un petit AVC ? »","why":"L'atteinte coronarienne est présente dans 40-50 % des AOMI ; les patients AOMI sont ceux qui ont le plus souvent une atteinte polyvasculaire (≥ 2 territoires).","flag":"orientation","src":"221 p. 40"},{"ask":"« Dans votre famille, y a-t-il eu des infarctus, des AVC, des anévrismes ? À quel âge ? »","why":"Les antécédents familiaux sont un FDR non modifiable ; ceux d'anévrisme sont un FDR d'AAA. La vignette du Collège cite un père décédé d'infarctus à 63 ans.","flag":"terrain","src":"221 p. 34, 39 ; 225 p. 183"},{"ask":"« Avez-vous une insuffisance rénale ou êtes-vous dialysé ? »","why":"La médiacalcose (IPS > 1,40) est fréquente chez le diabétique âgé et/ou le patient dialysé rénal ; une neuropathie (diabète, insuffisance rénale, âge avancé) peut altérer la sensibilité et masquer une atteinte sévère.","flag":"terrain","src":"225 p. 169, 171"},{"ask":"« Prenez-vous de l'aspirine, une statine ? Depuis quand ? »","why":"Les douleurs musculaires sous statines peuvent mimer une AOMI (tableaux parfois intriqués) ; l'aspirine et les statines sont la base du traitement.","flag":"terrain","src":"225 p. 174-175"},{"ask":"« Avez-vous des troubles de l'érection ? »","why":"Peut être un indicateur de maladie artérielle ; dans le syndrome de Leriche (atteinte aorto-iliaque), il s'associe à une claudication fessière.","flag":"terrain","src":"225 p. 169 ; 221 p. 40"}],"astuce":"FDR à réciter : tabac et diabète pour la jambe (le tabac chez le plus jeune, le diabète pour les formes graves distales), puis HTA et cholestérol."},{"key":"symptome","title":"La douleur à la marche, décortiquée","goal":"Décrire la claudication : siège, nature, distance de gêne et de marche, délai de disparition au repos.","questions":[{"ask":"« Marchez-vous régulièrement ? Quelque chose vous empêche-t-il de marcher ? »","why":"Avant même de parler de douleur, s'assurer que le patient marche : une atteinte sévère peut rester masquée chez le sujet très âgé, ou à cause de comorbidités (insuffisance cardiaque, respiratoire, arthrose) qui limitent la marche.","flag":"orientation","src":"225 p. 169"},{"ask":"« Où avez-vous mal quand vous marchez : mollet, cuisse, fesse, pied ? »","why":"Typiquement le mollet ; mais pied, cuisse ou claudication fessière (atteintes aorto-iliaques) sont possibles dans les formes atypiques.","flag":"orientation","src":"225 p. 168-169"},{"ask":"« Comment est la douleur : une crampe, un étau, un engourdissement, des fourmillements ? »","why":"Dans la forme typique : douleur de type crampe au mollet. Dans les formes atypiques, elle peut être remplacée par une paresthésie ou un engourdissement d'effort.","flag":"terrain","src":"225 p. 168-169 ; 221 p. 34"},{"ask":"« Au bout de combien de mètres (ou de minutes) la douleur apparaît-elle ? »","why":"C'est la distance de gêne (apparition de la douleur). La distance de marche est classiquement stable et s'évalue sur terrain plat ou lors d'une épreuve de marche.","flag":"terrain","src":"225 p. 169"},{"ask":"« Êtes-vous obligé de vous arrêter ? Après quelle distance ? »","why":"C'est la distance de marche. Claudication sévère si la distance est inférieure à 100 m, ce qui peut conduire à discuter une revascularisation.","flag":"gravite","src":"225 p. 169, 176"},{"ask":"« En combien de temps la douleur disparaît-elle quand vous vous arrêtez ? »","why":"Dans la claudication intermittente typique, la douleur disparaît habituellement en moins de 5 minutes.","flag":"orientation","src":"225 p. 168"},{"ask":"« La distance que vous faites est-elle toujours la même d'un jour à l'autre ? »","why":"Classiquement stable ; une distance variable fait partie des formes atypiques (fréquentes).","flag":"orientation","src":"225 p. 168-169"},{"ask":"« Plutôt que de vous arrêter, ralentissez-vous le pas pour ne plus avoir mal ? »","why":"Certains patients ne s'arrêtent pas mais ralentissent suffisamment pour ne plus souffrir : forme atypique à connaître.","flag":"terrain","src":"225 p. 169"}],"astuce":"Les 3 mots de la claudication artérielle : effort (apparaît à la marche), distance (constante), arrêt (cède en moins de 5 min)."},{"key":"associes","title":"Signes associés","goal":"Détecter une maladie polyvasculaire : coronaires, carotides, aorte, artères digestives et rénales.","questions":[{"ask":"« Avez-vous une douleur dans la poitrine à l'effort, un essoufflement inhabituel ? »","why":"Interrogatoire systématique de l'angor : la coronaropathie accompagne souvent l'AOMI (40-50 %).","flag":"orientation","src":"225 p. 169 ; 221 p. 40"},{"ask":"« Avez-vous eu un engourdissement du visage ou du bras, un trouble de la parole ou de la vue qui a disparu ? »","why":"L'interrogatoire doit systématiquement rechercher des signes fonctionnels d'autres atteintes athéromateuses, notamment l'angor et les symptômes déficitaires cérébraux.","flag":"orientation","src":"225 p. 169"},{"ask":"« Avez-vous mal au ventre après les repas ? Avez-vous perdu du poids ? »","why":"Ischémie mésentérique chronique : angor digestif (douleurs abdominales postprandiales), parfois amaigrissement car le patient limite ses repas.","flag":"orientation","src":"225 p. 166"},{"ask":"« Avez-vous de la fatigue des fesses ou des cuisses en marchant, en plus des mollets ? »","why":"Claudication fessière, fatigabilité à la marche et impuissance définissent le syndrome de Leriche (atteinte aorto-iliaque).","flag":"orientation","src":"225 p. 169"},{"ask":"« Vous a-t-on déjà trouvé de la tension élevée difficile à contrôler, ou une insuffisance rénale ? »","why":"L'athérome des artères rénales peut donner une HTA rénovasculaire et une insuffisance rénale.","flag":"terrain","src":"225 p. 166 ; 221 p. 38"},{"ask":"« Avez-vous déjà eu une douleur du ventre ou du dos, ou une masse qui bat dans le ventre ? »","why":"Dépistage de l'anévrisme de l'aorte abdominale chez les hommes de plus de 65 ans ou à risque ; l'AAA est souvent asymptomatique.","flag":"terrain","src":"225 p. 183-184 ; 221 p. 41"}],"astuce":"Une artérite, c'est trois territoires à interroger : cœur (angor), cerveau (symptômes déficitaires), ventre (angor digestif). Chez le claudicant, à 5 ans : 20 % ont des complications cardiovasculaires, 20 % décèdent, pour moitié de cause cardiovasculaire."},{"key":"orientation","title":"Les questions qui orientent","goal":"Éliminer les autres causes de douleur à la marche (neurologiques, rhumatologiques, veineuses, musculaires), parfois associées chez le sujet âgé.","questions":[{"ask":"« La douleur part-elle du dos et descend-elle le long de la jambe, avec des fourmillements dans le pied ? »","why":"Origine neurologique : canal lombaire étroit (douleur ou paresthésies du mollet ou du pied apparaissant à l'effort et cédant au repos), sciatalgie.","if":"Si oui → penser à une origine neurologique (canal lombaire étroit, sciatique)","flag":"orientation","src":"225 p. 174"},{"ask":"« Vos jambes se dérobent-elles sous vous sans que vous ayez vraiment mal ? »","why":"Atteinte médullaire : parésie du membre sans douleur avec dérobement des jambes.","if":"Si oui → penser à une atteinte médullaire","flag":"orientation","src":"225 p. 174"},{"ask":"« Avez-vous mal à la hanche, au genou, aux tendons, est-ce plus net à l'appui ? »","why":"Origine rhumatologique : tendinite, arthrose, rhumatismes, anomalies posturostaturales.","if":"Si oui → arthrose ou tendinite possibles, et peuvent coexister avec l'artérite","flag":"orientation","src":"225 p. 174"},{"ask":"« Avez-vous eu une phlébite ? Votre jambe est-elle lourde, gonflée le soir ? »","why":"Claudication veineuse (post-thrombotique).","if":"Si oui → penser à une claudication veineuse","flag":"orientation","src":"225 p. 174"},{"ask":"« Avez-vous mal derrière le genou, avez-vous une boule ou un pouls qui bat fort à cet endroit ? »","why":"Kyste poplité, piège poplité, anévrisme poplité (masse battante au creux poplité).","if":"Si oui → rechercher une cause poplitée","flag":"orientation","src":"225 p. 174, 186"},{"ask":"« Les douleurs musculaires ont-elles commencé après le début d'une statine ? »","why":"Les douleurs musculaires sous statines peuvent parfois mimer une AOMI, avec attention aux tableaux intriqués.","flag":"orientation","src":"225 p. 174"},{"ask":"« Avez-vous eu une radiothérapie, des gelures, un traumatisme du membre, ou une maladie inflammatoire ? »","why":"Artériopathies non athéromateuses (Buerger, Takayasu, Horton, collagénoses, radiques, post-traumatiques, gelures) ; l'AOMI athéromateuse représente plus de 95 % des atteintes.","flag":"orientation","src":"225 p. 174"}],"astuce":"Artérite : l'effort la déclenche et l'arrêt la calme en moins de 5 minutes. Mais le canal lombaire étroit cède aussi au repos : le test de marche avec IPS après effort aide au diagnostic différentiel."},{"key":"examen","title":"Examen clinique ciblé","goal":"Un examen toujours bilatéral et comparatif, des pieds à l'abdomen, avec l'IPS pour conclure.","questions":[{"ask":"Inspecter les deux pieds : couleur, troubles trophiques, espaces interdigitaux","why":"Pied normal, pâle ou cyanosé ; les troubles trophiques (peau mince, perte de pilosité, plaies) sont systématiquement recherchés, notamment entre les orteils.","src":"225 p. 170"},{"ask":"Palper la température du pied et mesurer le temps de recoloration cutanée","why":"Pied froid ; le temps de recoloration cutanée est allongé (normalement < 3 secondes).","src":"225 p. 170"},{"ask":"Palper les pouls fémoral, poplité, tibial postérieur, pédieux, des deux côtés","why":"Recherche d'un amortissement ou d'une abolition ; le pédieux peut être absent de façon congénitale chez 5 % de la population. Dans la vignette : pouls fémoral amorti et pouls d'aval absents d'un côté.","src":"225 p. 170 ; 221 p. 34"},{"ask":"Palper les masses musculaires du mollet","why":"Une douleur à la pression du mollet témoigne d'une ischémie sévère.","src":"225 p. 170"},{"ask":"Palper l'abdomen et le creux poplité à la recherche d'un anévrisme","why":"La recherche d'anévrisme (aorte abdominale et poplité) est systématique.","src":"225 p. 170"},{"ask":"Ausculter les trajets vasculaires : fémoraux, abdomen, carotides","why":"Rechercher un souffle sur les trajets vasculaires (souffle fémoral, abdominal, carotidien).","src":"225 p. 170, 166 ; 221 p. 34"},{"ask":"Prendre la pression artérielle aux deux bras","why":"Une différence > 15 mmHg entre les deux bras sur plusieurs mesures fait suspecter une sténose subclavière unilatérale. Elle est aussi nécessaire pour calculer l'IPS.","src":"221 p. 41 ; 225 p. 170"},{"ask":"Ausculter le cœur et le thorax, examen cardiovasculaire général","why":"L'examen d'un patient AOMI doit être complété par un examen cardiovasculaire général du fait de la fréquence de la maladie coronarienne et cérébrovasculaire.","src":"225 p. 170"},{"ask":"Mesurer l'IPS, aux deux chevilles","why":"Examen clinique systématiquement complété par l'IPS : pression systolique de cheville (la plus élevée entre tibiale postérieure et pédieuse) divisée par la plus élevée des deux bras. Normal 1,00-1,40 ; AOMI si < 0,90 ; sévère si < 0,70 ; > 1,40 = médiacalcose.","src":"225 p. 170-171"}],"astuce":"Examen en 4 mots : regarder (couleur, plaies), toucher (froid, pouls), écouter (souffles), mesurer (IPS). Toujours comparer à l'autre jambe."},{"key":"gravite","title":"Signes de gravité (à chercher d'emblée)","goal":"Repérer le passage à l'ischémie permanente, qui engage le pronostic du membre, et l'ischémie aiguë.","questions":[{"ask":"« Avez-vous mal la nuit, aux orteils ou au pied, quand vous êtes allongé ? Cela vous soulage-t-il de laisser la jambe pendre ? »","why":"Douleurs de décubitus (stade III) : brûlures des orteils et de l'avant-pied, apparaissant après quelques minutes à quelques heures allongé, améliorées jambe pendante ; insomnie, antalgiques de plus en plus forts. C'est l'ischémie permanente.","flag":"gravite","src":"225 p. 169"},{"ask":"« Avez-vous une plaie, un ulcère, un orteil noirci qui ne cicatrise pas ? »","why":"Troubles trophiques (stade IV) : ulcères aux zones d'appui (orteil, talon, bord du pied) ou « suspendus », gangrène (orteils, talon), souvent très douloureux, portes d'entrée d'infections.","flag":"gravite","src":"225 p. 169"},{"ask":"« Depuis combien de temps la douleur de repos dure-t-elle ? Les antalgiques simples vous soulagent-ils ? »","why":"L'ischémie permanente englobe les stades III et IV, avec des douleurs durant plus de 15 jours, résistant aux antalgiques usuels.","flag":"gravite","src":"225 p. 169"},{"ask":"Pied froid, pâle ou cyanosé, œdème de déclivité","why":"Signes d'ischémie permanente à l'examen ; l'œdème de déclivité favorise les complications trophiques.","flag":"gravite","src":"225 p. 169"},{"ask":"Pressions de perfusion : cheville < 50 mmHg ou hallux < 30 mmHg","why":"Des pressions de perfusion effondrées (< 50 mmHg à la cheville ou < 30 mmHg à l'hallux), avec ce tableau clinique, définissent l'ischémie critique : le pronostic du membre est engagé.","flag":"gravite","src":"225 p. 169"},{"ask":"Signes d'infection : fièvre, rougeur, écoulement, douleur locale","why":"Les plaies ischémiques sont des portes d'entrée à une infection locorégionale (cellulite, arthrite, ostéite) voire générale (septicémie) ; la gangrène est plus fréquente et plus souvent infectée chez le diabétique.","flag":"gravite","src":"225 p. 169"},{"ask":"Douleur brutale du membre, froid, pâle, avec déficit : ischémie aiguë","why":"Le patient peut déclarer sa maladie sous forme d'ischémie aiguë ou subaiguë : urgence vasculaire (cf. fiche membre ischémique).","flag":"gravite","src":"225 p. 169, 178"},{"ask":"Patient diabétique, insuffisant rénal ou très âgé : forme masquée","why":"Neuropathie, comorbidités limitant la marche ou collatéralité peuvent cacher une AOMI qui se révèle d'emblée par une ischémie permanente.","flag":"gravite","src":"225 p. 169"}],"astuce":"Claudication = on traite les facteurs de risque et on marche. Douleur de repos, plaie ou gangrène = le membre est en danger : revascularisation."},{"key":"examens","title":"Examens de 1re intention","goal":"Confirmer l'AOMI par l'IPS, la quantifier, la localiser, et dépister les autres territoires et facteurs de risque.","questions":[{"ask":"IPS de repos aux deux chevilles","why":"En cas de suspicion d'AOMI ou de dépistage, l'examen clinique est systématiquement complété par l'IPS. AOMI si au moins une cheville < 0,90 ; sévère si < 0,70. Un IPS < 0,90 est aussi un marqueur de risque cardiovasculaire élevé.","src":"225 p. 170-171"},{"ask":"Si IPS normal malgré des symptômes : test de marche sur tapis (3,2 km/h, pente 10 %) avec IPS après effort","why":"Une baisse de la pression systolique de cheville > 30 mmHg et/ou une baisse > 20 % de l'IPS juste après la marche évoque l'AOMI ; le test objective aussi la distance de gêne et de marche.","src":"225 p. 171"},{"ask":"Pression d'orteil (index d'orteil) si IPS > 1,40, diabète, insuffisance rénale ou grand âge","why":"L'IPS de repos peut être pris en défaut (médiacalcose) ; un index d'orteil < 0,70 témoigne d'une AOMI, une pression d'orteil < 30 mmHg d'une ischémie critique.","src":"225 p. 170-171"},{"ask":"TcPO2 après hyperémie (si ischémie critique suspectée)","why":"Utile au diagnostic et à l'évaluation de l'ischémie critique : normale > 50 mmHg au dos du pied, hypoxie continue entre 10 et 35, critique < 10 mmHg.","src":"225 p. 171"},{"ask":"Échodoppler artériel des membres inférieurs","why":"Exploration la plus fréquente, non invasive : localise les lésions et quantifie leur sévérité.","src":"225 p. 172"},{"ask":"Angioscanner ou angio-IRM seulement si une revascularisation est envisagée","why":"Étudient faisabilité et stratégie. Angioscanner : iode, vérifier allergies et fonction rénale. ARM : gadolinium contre-indiqué si clairance < 30 mL/min/1,73 m². L'artériographie est réservée aux procédures de revascularisation.","src":"225 p. 172-173"},{"ask":"ECG systématique, et recherche d'une atteinte coronaire ou carotidienne orientée par la clinique","why":"Chez un patient polyathéromateux, bilan clinique de tous les territoires, ECG systématique, IPS, et explorations choisies selon le bilan clinique et la nécessité d'un geste.","src":"221 p. 41"},{"ask":"Échographie abdominale de dépistage d'un AAA, notamment chez l'homme de plus de 65 ans","why":"Le dépistage de l'anévrisme de l'aorte abdominale est fait chez les patients athéromateux, notamment les hommes après 65 ans.","src":"221 p. 41 ; 225 p. 184"},{"ask":"Bilan des facteurs de risque : glycémie/HbA1c, bilan lipidique (LDL-cholestérol), pression artérielle","why":"Évaluation des facteurs de risque, commune à tous les territoires atteints, et calcul du risque cardiovasculaire global. Cibles de prévention du Collège : LDL-cholestérol < 0,55 g/L, HbA1c < 7 %.","src":"221 p. 41 ; 225 p. 175"}],"astuce":"Réflexe : IPS d'abord (pas d'artériographie), écho-doppler ensuite, angioscanner/ARM seulement si on pense à revasculariser, et un coup d'œil aux autres artères."}],"synthese":"Monsieur P., 62 ans, fumeur à 35 paquets-années, hypertendu, se plaint depuis 8 mois d'une crampe du mollet gauche survenant après 200 m de marche à plat, l'obligeant à s'arrêter et disparaissant en 3 minutes, sans douleur de repos ni plaie. À l'examen : pouls fémoral gauche amorti, pouls poplité et distaux abolis à gauche, souffle fémoral gauche, PA 150/80 mmHg au bras droit et 140/80 au gauche, IPS gauche à 0,62. Hypothèses : AOMI symptomatique au stade de claudication intermittente (stade II de Leriche et Fontaine) chez un patient possiblement polyvasculaire ; canal lombaire étroit ; claudication veineuse ; myalgies sous statine.","hypotheses":[{"dx":"AOMI au stade de claudication intermittente (stade II)","pour":"Crampe du mollet à l'effort, distance stable, cède en moins de 5 minutes à l'arrêt, tabac, pouls amortis ou abolis, IPS < 0,90.","danger":false,"src":"225 p. 168-169, 171"},{"dx":"AOMI au stade d'ischémie permanente / ischémie critique","pour":"Douleurs de décubitus soulagées jambe pendante, plaies, gangrène, pressions de cheville < 50 mmHg ; pronostic du membre engagé.","danger":true,"src":"225 p. 169"},{"dx":"Maladie polyvasculaire associée (coronaire, carotide, AAA)","pour":"AOMI = patient le plus souvent polyvasculaire ; coronaropathie dans 40-50 % des cas ; souffle carotidien, angor, AIT.","danger":true,"src":"221 p. 39-40"},{"dx":"Canal lombaire étroit, sciatalgie, atteinte médullaire","pour":"Douleur ou paresthésies du mollet ou du pied à l'effort cédant au repos (canal lombaire étroit) ; sciatalgie ; parésie du membre sans douleur avec dérobement des jambes (atteinte médullaire).","danger":false,"src":"225 p. 174"},{"dx":"Claudication veineuse, atteinte rhumatologique (arthrose, tendinite), myalgies sous statine","pour":"Claudication veineuse (post-thrombotique) ; tendinite, arthrose, rhumatismes ; douleurs musculaires sous statine pouvant mimer une AOMI (tableaux parfois intriqués).","danger":false,"src":"225 p. 174"},{"dx":"Anévrisme poplité, kyste ou piège poplité, artériopathie non athéromateuse (Buerger, Takayasu, radique)","pour":"Masse battante au creux poplité (anévrisme), kyste ou piège poplité ; artériopathies non athéromateuses (inflammatoires, radiques, post-traumatiques) : l'AOMI athéromateuse représente plus de 95 % des atteintes.","danger":false,"src":"225 p. 174, 186"}],"pieges":["Un IPS > 1,40 traduit une médiacalcose (diabétique, dialysé) : il faut mesurer la pression d'orteil.","Un IPS de repos normal n'exclut pas l'AOMI : faire un test de marche avec IPS après effort.","Chez le diabétique, l'insuffisant rénal, le très âgé : AOMI masquée, voire ischémie permanente d'emblée.","Le pouls pédieux est absent de façon congénitale chez 5 % de la population.","Pas d'artériographie en 1re intention : elle est réservée à la revascularisation.","Un patient AOMI est polyvasculaire : toujours chercher coronaire, carotide, AAA, et ne jamais oublier aspirine et statine."],"src":"225 p. 164-189 (surtout 166, 168-177) ; 221 p. 34-43 (surtout 39-41)"},{"id":"fievre-valvulaire","spe":"cardio","title":"Fièvre chez un patient cardiaque : penser endocardite","emoji":"🌡️","items":["152","153"],"hook":"Fièvre + valve, souffle ou prothèse = endocardite jusqu'à preuve du contraire, et on prélève les hémocultures AVANT le premier antibiotique.","intro":"Une fièvre banale chez un patient cardiaque n'est jamais banale : l'endocardite est polymorphe, grave (mortalité hospitalière 15-30 %) et facile à rater. Ton état d'esprit : repérer le terrain à risque d'abord, chercher les signes d'atteinte du cœur et les complications à distance, puis hémocultures + échographie avant toute antibiothérapie.","steps":[{"key":"terrain","title":"Terrain et antécédents","goal":"Classer le patient dans un groupe à risque d'endocardite (haut risque, risque intermédiaire, aucun connu) : ça change tout pour la probabilité du diagnostic.","questions":[{"ask":"« Avez-vous une valve artificielle, ou avez-vous été opéré du cœur ? Avez-vous eu une valve posée par un cathéter (TAVI) ? »","why":"Les prothèses valvulaires (chirurgicales, mécaniques ou biologiques, et TAVI) et tout matériel de réparation valvulaire sont des cardiopathies à HAUT risque d'EI. Le risque est le même sur prothèse biologique et mécanique, et le pronostic est plus sévère que sur valve native.","flag":"terrain","src":"152 p. 252, 258 ; 153 p. 269"},{"ask":"« Avez-vous déjà eu une endocardite ? »","why":"L'antécédent d'endocardite infectieuse fait partie du groupe à haut risque.","flag":"terrain","src":"152 p. 252"},{"ask":"« Êtes-vous né avec une malformation du cœur ? A-t-elle été opérée, et quand ? »","why":"Cardiopathie congénitale cyanogène, ou réparée avec matériel prothétique (haut risque pendant 6 mois, à vie s'il reste un shunt) ; les valvulopathies congénitales comme la bicuspidie aortique sont à risque intermédiaire.","flag":"terrain","src":"152 p. 252, 263"},{"ask":"« Avez-vous un pacemaker, un défibrillateur ou une assistance cardiaque ? »","why":"Stimulateur et défibrillateur implantables = risque intermédiaire ; assistance ventriculaire = haut risque. Les EI sur stimulateur ou défibrillateur sont surtout à staphylocoques.","flag":"terrain","src":"152 p. 252, 258"},{"ask":"« Vous a-t-on déjà parlé d'une maladie des valves : rétrécissement, fuite, rhumatisme articulaire aigu ? »","why":"Valvulopathies dégénératives, bicuspidie, cardiopathie post-rhumatismale et cardiomyopathie hypertrophique = risque intermédiaire.","flag":"terrain","src":"152 p. 250, 252"},{"ask":"« Avez-vous une voie veineuse centrale, une chambre implantable, êtes-vous dialysé ? »","why":"Cathéters veineux, hémodialyse et chambre implantable sont des situations de plus en plus fréquentes qui exposent à l'EI (porte d'entrée cutanée, staphylocoques).","flag":"terrain","src":"152 p. 250-251"},{"ask":"« Vous est-il arrivé de vous injecter des drogues ? »","why":"La toxicomanie intraveineuse est un facteur de risque ; elle donne surtout des EI du cœur droit à staphylocoques.","flag":"terrain","src":"152 p. 250, 258"},{"ask":"« Cela fait combien de temps que votre valve a été posée ? »","why":"EI précoce = dans l'année suivant l'implantation (contamination peropératoire, germes hospitaliers, souvent staphylocoques, pronostic sévère) ; EI tardive = plus d'un an, plus proche de l'EI sur valve native.","flag":"orientation","src":"152 p. 258 ; 153 p. 279"},{"ask":"« Prenez-vous un anticoagulant (AVK) ? Quel est votre INR cible et vos derniers résultats ? »","why":"Chez un porteur de prothèse mécanique, un traitement anticoagulant insuffisant est le principal facteur de risque de complication thromboembolique et souvent en cause dans une thrombose de prothèse ; une fébricule est possible et le diagnostic différentiel (ou l'association) avec l'EI est parfois difficile.","flag":"orientation","src":"153 p. 276-277"}],"astuce":"Trois familles à retenir : prothèse ou matériel, antécédent d'EI, cardiopathie congénitale cyanogène ou réparée = HAUT risque. Mais attention : dans 50 % des cas, la cardiopathie n'était pas connue ou absente."},{"key":"symptome","title":"La fièvre, décortiquée","goal":"Caractériser le syndrome infectieux : ancienneté, intensité, contexte et traitement déjà pris (qui peut fausser les hémocultures).","questions":[{"ask":"« Depuis quand avez-vous de la fièvre ? »","why":"Le Collège donne l'exemple d'épisodes fébriles à plus de 39 °C depuis plus de 2 semaines (vignette). Fièvre + cardiopathie à risque est un des tableaux qui doivent faire évoquer l'EI.","flag":"orientation","src":"152 p. 250, 253"},{"ask":"« Quelle température avez-vous mesurée, et à quel moment de la journée ? »","why":"Fièvre (température > 38 °C) = critère clinique mineur de la classification diagnostique.","flag":"terrain","src":"152 p. 259"},{"ask":"« Avez-vous des frissons, des sueurs ? »","why":"La vignette du Collège associe fièvre à plus de 39 °C et frissons ; la fièvre fait partie du syndrome infectieux de l'EI.","flag":"terrain","src":"152 p. 250, 253"},{"ask":"« Avez-vous maigri, perdu l'appétit, êtes-vous plus fatigué que d'habitude ? »","why":"L'altération de l'état général fait partie du syndrome infectieux de l'EI, maladie systémique.","flag":"terrain","src":"152 p. 253"},{"ask":"« Votre fièvre a-t-elle commencé après un soin dentaire, une opération, un cathéter, une injection ? »","why":"Une bactériémie importante ou répétée à partir d'une porte d'entrée est le point de départ de l'EI ; le contexte est très important pour évoquer le diagnostic.","flag":"orientation","src":"152 p. 251, 253"},{"ask":"« Avez-vous déjà pris des antibiotiques pour cette fièvre ? Lesquels, combien de temps ? »","why":"Une antibiothérapie préalable à la réalisation des hémocultures est une cause d'EI à hémocultures négatives (10 % des EI). Les hémocultures sont alors à répéter durant 2 ou 3 jours, notamment chez les sujets ayant reçu des antibiotiques.","flag":"orientation","src":"152 p. 254-255"},{"ask":"« Avez-vous déjà eu un autre épisode de fièvre ces dernières semaines ? »","why":"Le Collège donne l'exemple d'épisodes fébriles à plus de 39 °C depuis plus de 2 semaines (vignette) : une fièvre qui dure ou qui revient chez un patient à risque doit faire évoquer l'EI.","flag":"terrain","src":"152 p. 250"},{"ask":"« Vous a-t-on posé une valve il y a moins d'un an, et avez-vous été revu depuis ? »","why":"Une fièvre inexpliquée chez un porteur de prothèse impose hémocultures systématiques et échocardiographie ; le Collège classe comme inacceptable de ne pas penser à l'EI en cas de fièvre.","flag":"gravite","src":"153 p. 280, 289"}],"astuce":"Le piège classique : le patient a déjà avalé des antibiotiques. Demande-le toujours, il explique les hémocultures négatives."},{"key":"associes","title":"Signes associés","goal":"Chercher les signes cardiaques et surtout les localisations à distance : l'EI est une maladie systémique, tous les signes ne sont pas forcément présents.","questions":[{"ask":"« Êtes-vous essoufflé ? Avez-vous les jambes gonflées ? Dormez-vous assis ? »","why":"Toute insuffisance cardiaque fébrile doit faire évoquer une endocardite (destruction valvulaire, fuite aiguë).","flag":"gravite","src":"152 p. 254"},{"ask":"« Avez-vous eu un malaise, une perte de connaissance ou failli vous évanouir ? »","why":"Syncopes et lipothymies peuvent être dues à un bloc atrioventriculaire par abcès septal interrompant les voies de conduction.","flag":"gravite","src":"152 p. 254"},{"ask":"« Avez-vous eu une faiblesse d'un bras ou d'une jambe, un trouble de la parole, un fort mal de tête, de la confusion ? »","why":"Signes d'AVC ischémique ou hémorragique, méningite, abcès cérébral : les complications neurologiques sont une des deux principales causes de décès.","flag":"gravite","src":"152 p. 254, 259"},{"ask":"« Avez-vous mal au dos, aux articulations ? »","why":"Arthrite périphérique ou spondylodiscite = foyers infectieux à distance. Lombalgie + fièvre est un tableau d'alerte pour l'EI.","flag":"orientation","src":"152 p. 253-254"},{"ask":"« Toussez-vous, crachez-vous, avez-vous mal en respirant ? Avez-vous eu plusieurs pneumonies de suite ? »","why":"Embolies pulmonaires septiques (EI du cœur droit) : pneumopathies récidivantes et souvent abcédées, surtout chez le toxicomane ou le porteur de stimulateur.","flag":"orientation","src":"152 p. 254, 258"},{"ask":"« Vos urines sont-elles rouges, foncées ou mousseuses ? »","why":"Hématurie et protéinurie : glomérulonéphrite immunologique ou infarctus rénal.","flag":"orientation","src":"152 p. 254"},{"ask":"« Avez-vous remarqué des petits boutons douloureux au bout des doigts ou des orteils, des taches rouges sur les paumes ou les plantes, des petits saignements sous les ongles ou dans les yeux ? »","why":"Signes cutanéomuqueux rares (5-15 %) : faux panaris d'Osler (pathognomoniques), placards de Janeway, hémorragies sous-unguéales et sous-conjonctivales, purpura.","flag":"orientation","src":"152 p. 254"},{"ask":"« Avez-vous eu une douleur à gauche sous les côtes ? »","why":"Splénomégalie dans 20-30 % des EI ; les abcès spléniques font partie des foyers infectieux à distance et l'infarctus splénique des embolies systémiques.","flag":"orientation","src":"152 p. 252-253 ; 153 p. 276"}],"astuce":"Les cinq tableaux d'alerte à réciter : cardiopathie à risque + fièvre, souffle + fièvre, AVC + fièvre, purpura + fièvre, lombalgie + fièvre."},{"key":"orientation","title":"Les questions qui orientent","goal":"Trouver la porte d'entrée : elle oriente vers le germe, et n'est retrouvée que dans 50 % des cas.","questions":[{"ask":"« Avez-vous mal aux dents, une carie, un abcès ? Quand êtes-vous allé chez le dentiste pour la dernière fois ? »","why":"Porte d'entrée buccodentaire : streptocoques oraux (20 % des EI) et bactéries du groupe HACEK. Le suivi dentaire est à contrôler chez tout porteur de prothèse.","if":"Si oui → penser à un streptocoque oral, panoramique dentaire + stomatologue","flag":"orientation","src":"152 p. 251, 256 ; 153 p. 285"},{"ask":"« Avez-vous une plaie, un abcès, un ulcère, un tatouage ou un piercing récent ? »","why":"Porte d'entrée cutanée : Staphylococcus aureus (cause la plus fréquente, 30 %) et staphylocoques coagulase négative. Il faut éviter tatouages et piercings chez les patients à risque.","if":"Si oui → penser à un staphylocoque","flag":"orientation","src":"152 p. 251, 263"},{"ask":"« Avez-vous des troubles digestifs récents, du sang dans les selles, un changement du transit ? Une coloscopie a-t-elle été faite ? »","why":"Porte d'entrée digestive (cancer, polypes, diverticules) : Streptococcus gallolyticus (ex bovis) et entérocoques → coloscopie.","if":"Si oui → penser à un streptocoque D ou à un entérocoque","flag":"orientation","src":"152 p. 251, 257"},{"ask":"« Avez-vous des brûlures en urinant, un sondage urinaire récent ? »","why":"Porte d'entrée urinaire possible pour les entérocoques → ECBU et imagerie des voies urinaires.","flag":"orientation","src":"152 p. 251, 257"},{"ask":"« Avez-vous eu une perfusion, un cathéter, une dialyse, une ponction articulaire récemment ? »","why":"Cathéters veineux, hémodialyse, ponction articulaire, chambre implantable : procédures de soins à risque d'EI en augmentation. Le Collège cite la porte d'entrée cutanée (plaies, cathéter veineux, cathéter de dialyse) pour les staphylocoques.","flag":"orientation","src":"152 p. 250-251"},{"ask":"« Êtes-vous immunodéprimé, sous corticoïdes ou immunosuppresseur ? »","why":"L'immunosuppression, avec cathéters et toxicomanie IV, expose à l'EI à Candida et autres champignons (porte d'entrée cutanée).","flag":"terrain","src":"152 p. 251"},{"ask":"« Votre médecin vous a-t-il déjà dit que vous aviez un souffle ? A-t-il changé ? »","why":"Devant un syndrome infectieux inexpliqué, le souffle a une valeur diagnostique considérable ; la plus grande valeur est un nouveau souffle ou un souffle modifié. L'absence de souffle n'élimine pas le diagnostic.","if":"Si souffle nouveau ou modifié → EI jusqu'à preuve du contraire","flag":"orientation","src":"152 p. 254"},{"ask":"« Votre prothèse fait-elle toujours le même bruit de clic ? Avez-vous remarqué un changement ? »","why":"Chez le porteur de prothèse mécanique, un bruit de prothèse diminué ou variable, ou un souffle nouveau, évoque thrombose ou désinsertion (souvent due à une EI).","if":"Si oui → dysfonction de prothèse : ETO, INR en urgence","flag":"orientation","src":"153 p. 277, 281, 285-286"}],"astuce":"Staph = Peau, strepto oral = bouche, strepto D et entérocoque = tube digestif (± urinaire). Une porte d'entrée, un germe."},{"key":"examen","title":"Examen clinique ciblé","goal":"Retrouver à l'examen le souffle, l'insuffisance cardiaque, les signes cutanés et les localisations à distance.","questions":[{"ask":"Prendre température, fréquence cardiaque, pression artérielle, fréquence respiratoire, saturation","why":"Apprécier le retentissement : sepsis, choc, insuffisance cardiaque. La vignette du Collège associe une PA à 145/45 mmHg, un souffle diastolique intense au foyer aortique et des râles crépitants.","src":"152 p. 250, 253"},{"ask":"Ausculter le cœur : souffle nouveau ou modifié, foyer, systolique ou diastolique","why":"Le souffle nouveau ou modifié est le signe cardiaque le plus évocateur ; dans la vignette, souffle diastolique intense au foyer aortique sur TAVI.","src":"152 p. 250, 254"},{"ask":"Chez un porteur de prothèse mécanique, ausculter les bruits de prothèse (clics d'ouverture et de fermeture)","why":"Bruits claqués métalliques normaux ; diminution d'intensité, variabilité d'un cycle à l'autre, nouveau souffle ou bruit diastolique surajouté = dysfonction (thrombose, désinsertion).","src":"153 p. 277, 285"},{"ask":"Ausculter les poumons : crépitants ?","why":"Râles crépitants = œdème aigu du poumon d'une EI du cœur gauche ; foyers = pneumopathies d'une EI du cœur droit.","src":"152 p. 254, 256"},{"ask":"Examiner la peau, les ongles, les conjonctives, la paume des mains et la plante des pieds","why":"Purpura, faux panaris d'Osler (pathognomoniques), placards de Janeway, hémorragies sous-unguéales et sous-conjonctivales. Signes rares (5-15 % des cas).","src":"152 p. 254"},{"ask":"Palper la rate et examiner l'abdomen","why":"Splénomégalie dans 20-30 % des cas.","src":"152 p. 253"},{"ask":"Examen neurologique complet, recherche d'un syndrome méningé","why":"Déficit focal ou signes méningés : AVC, méningite, abcès cérébral, hémorragie méningée.","src":"152 p. 254"},{"ask":"Examiner le rachis, les articulations ; fond d'œil si possible","why":"Spondylodiscite, arthrite ; taches de Roth (exsudats hémorragiques rétiniens) au fond d'œil.","src":"152 p. 254"},{"ask":"Examiner les dents, les gencives, la peau, les points d'injection et les voies d'abord","why":"Rechercher la porte d'entrée (dentaire, cutanée, cathéters), non retrouvée dans 50 % des cas.","src":"152 p. 256 ; 153 p. 285"},{"ask":"Bandelette urinaire","why":"Hématurie et protéinurie : glomérulonéphrite ou infarctus rénal.","src":"152 p. 254, 256"}],"astuce":"Pense en trois blocs : infectieux (fièvre, rate), cardiaque (souffle, insuffisance cardiaque), extracardiaque (neuro, peau, œil, rein, os)."},{"key":"gravite","title":"Signes de gravité (à chercher d'emblée)","goal":"Repérer les complications qui font la mortalité et qui peuvent faire basculer vers la chirurgie.","questions":[{"ask":"Insuffisance cardiaque aiguë : OAP, hypotension, choc cardiogénique ?","why":"L'insuffisance cardiaque aiguë est l'une des deux principales causes de décès. L'insuffisance cardiaque gauche réfractaire ou le choc cardiogénique sont une indication chirurgicale en phase active (encadré 9.4).","flag":"gravite","src":"152 p. 259, 262"},{"ask":"Sepsis sévère ou choc septique ?","why":"Le syndrome infectieux mal maîtrisé est un facteur de mauvais pronostic ; l'antibiothérapie probabiliste est indiquée en cas de sepsis sévère (après les hémocultures).","flag":"gravite","src":"152 p. 259, 260"},{"ask":"Déficit neurologique, troubles de conscience, céphalées intenses ?","why":"Les complications neurologiques sont l'une des deux principales causes de décès et un facteur de mauvais pronostic : à chercher d'emblée (scanner ou IRM cérébrale).","flag":"gravite","src":"152 p. 254, 256, 259"},{"ask":"Syncope, lipothymie, bradycardie : ECG à la recherche d'un BAV","why":"Un BAV traduit un abcès septal (EI aortique) : infection non contrôlée localement, indication chirurgicale en phase active (encadré 9.4).","flag":"gravite","src":"152 p. 253-254, 262"},{"ask":"Embolie systémique : AVC, ischémie aiguë de membre, infarctus rénal ou splénique, embolie coronarienne ?","why":"Les végétations du cœur gauche peuvent emboliser. Végétations ≥ 10 mm persistantes après un ou plusieurs épisodes emboliques malgré une antibiothérapie adaptée = indication chirurgicale. L'embolie coronarienne se cherche à l'ECG et à la troponine.","flag":"gravite","src":"152 p. 252, 256, 262 ; 153 p. 276"},{"ask":"Prothèse mécanique avec OAP brutal, syncope, choc ou mort subite : penser thrombose obstructive","why":"Accident brutal possible ; vérifier l'INR en urgence ; hospitalisation en USIC, héparine IV et aspirine, réintervention discutée (mortalité 30 %).","flag":"gravite","src":"153 p. 277"},{"ask":"Germe virulent, prothèse, végétation volumineuse, abcès, terrain fragile ?","why":"Facteurs de mauvais pronostic : S. aureus, champignons, EI sur prothèse, grosses végétations, abcès, âge avancé, diabète, immunodépression, insuffisance cardiaque ou rénale.","flag":"gravite","src":"152 p. 259-260"}],"astuce":"Les deux premières causes de décès : le cœur (insuffisance cardiaque aiguë) et le cerveau (complications neurologiques) ; un syndrome infectieux mal maîtrisé aggrave aussi le pronostic. Si l'une est là, appelle d'emblée l'équipe endocardite et le chirurgien."},{"key":"examens","title":"Examens de 1re intention","goal":"Deux piliers, hémocultures et échographie, puis le bilan des complications et de la porte d'entrée.","questions":[{"ask":"3 hémocultures veineuses espacées d'au moins 30 minutes, AVANT toute antibiothérapie, en aéroanaérobie","why":"Isolent le germe dans 90 % des cas. Ne pas prélever sur un cathéter déjà en place ; signaler la suspicion d'EI au laboratoire (germes à culture lente) ; à répéter 2-3 jours si négatives.","src":"152 p. 254"},{"ask":"Échographie transthoracique (ETT) systématique en 1re intention","why":"Recherche végétations, destructions valvulaires, abcès, fuites ; évalue le retentissement.","src":"152 p. 255"},{"ask":"Échographie transœsophagienne (ETO) : si ETT positive, négative avec forte suspicion, et toujours en cas de matériel intracardiaque","why":"Meilleure sensibilité que l'ETT. Une échographie normale n'élimine pas le diagnostic : la répéter à 7-10 jours (ETT + ETO).","src":"152 p. 255"},{"ask":"Antibiothérapie probabiliste, en cas de forte suspicion ou de sepsis sévère, APRÈS les hémocultures","why":"Débuter les antibiotiques avant les hémocultures est une faute inacceptable ; chez un porteur de prothèse, ne jamais prescrire d'antibiotiques à l'aveugle sans hémocultures.","src":"152 p. 260, 265 ; 153 p. 289"},{"ask":"NFS-plaquettes, CRP, facteur rhumatoïde, ionogramme, créatininémie, bandelette urinaire, ECG et radiographie thoracique","why":"Hyperleucocytose à PNN, anémie, thrombopénie, syndrome inflammatoire, réaction immunologique, retentissement rénal. ECG : BAV, ischémie (embolie coronarienne). Radiographie : OAP (cœur gauche) ou pneumopathies (cœur droit).","src":"152 p. 256"},{"ask":"INR en urgence chez un porteur de prothèse mécanique","why":"Un traitement anticoagulant insuffisant est souvent en cause dans une thrombose de prothèse, diagnostic différentiel de l'EI (fébricule possible).","src":"153 p. 277"},{"ask":"Scanner cérébral et thoraco-abdomino-pelvien (± IRM cérébrale)","why":"Chercher des localisations septiques secondaires parfois asymptomatiques (encéphale, rate, rein, foie, vertèbres) et des anévrismes infectieux ; avec injection si la fonction rénale le permet.","src":"152 p. 256"},{"ask":"Scanner cardiaque, TEP-scanner au FDG ou scintigraphie aux leucocytes marqués si le doute persiste","why":"Utiles sur prothèse valvulaire, stimulateur ou défibrillateur quand l'échographie ne tranche pas ; mettent en évidence abcès et localisations secondaires.","src":"152 p. 256 ; 153 p. 280"},{"ask":"Recherche de la porte d'entrée : panoramique dentaire, coloscopie, ECBU selon le germe","why":"Streptocoques oraux → dents ; S. gallolyticus ou entérocoques → coloscopie ; entérocoques → urines.","src":"152 p. 256-257"},{"ask":"Prévenir l'équipe endocardite et un chirurgien cardiaque","why":"Prise en charge multidisciplinaire qui améliore le pronostic ; environ 50 % des EI ont une indication chirurgicale en phase active.","src":"152 p. 253, 261 ; 153 p. 280"}],"astuce":"Ordre d'or : hémocultures, puis antibiotiques si besoin, et échographie dès le départ. Jamais l'inverse."}],"synthese":"Monsieur H., 72 ans, porteur d'une prothèse aortique mécanique posée il y a 8 mois, consulte pour une fièvre à 39 °C avec frissons depuis 10 jours, une asthénie et une dyspnée d'effort récente. À l'examen : souffle diastolique nouveau au foyer aortique, bruits de prothèse atténués, râles crépitants bilatéraux, bandelette urinaire avec hématurie. Hypothèses : endocardite infectieuse précoce sur prothèse aortique avec désinsertion et insuffisance cardiaque ; thrombose de prothèse (INR à vérifier) ; endocardite sur valve native ou sur matériel (pacemaker, cathéter) à garder en tête chez d'autres profils.","hypotheses":[{"dx":"Endocardite infectieuse sur prothèse valvulaire","pour":"Prothèse = haut risque ; fièvre + souffle nouveau ou bruits de prothèse modifiés ; pronostic sévère, staphylocoque fréquent ; précoce si < 1 an.","danger":true,"src":"152 p. 253, 258 ; 153 p. 279"},{"dx":"Endocardite sur valve native (cardiopathie à risque ou valve saine si germe virulent)","pour":"Fièvre + souffle ou cardiopathie à risque, valvulopathie dégénérative, bicuspidie ; S. aureus peut infecter un endocarde sain.","danger":true,"src":"152 p. 251, 253"},{"dx":"Endocardite du cœur droit","pour":"Toxicomanie IV, stimulateur ou défibrillateur, voie veineuse centrale ; pneumopathies récidivantes abcédées par embolies septiques.","danger":true,"src":"152 p. 258"},{"dx":"Thrombose obstructive de prothèse mécanique","pour":"Anticoagulation insuffisante, bruits de prothèse diminués, souffle nouveau, OAP ou choc brutal ; fébricule possible, diagnostic différentiel de l'EI.","danger":true,"src":"153 p. 277"},{"dx":"Désinsertion de prothèse","pour":"Nouveau souffle (diastolique si prothèse aortique, systolique si mitrale), hémolyse (LDH élevées, haptoglobine basse, schizocytes) ; due le plus souvent à une EI qu'il faut toujours rechercher.","danger":true,"src":"153 p. 281-282"},{"dx":"Endocardite non infectieuse (marastique, lupus, syndrome des antiphospholipides)","pour":"Beaucoup plus rare ; cause d'EI à hémocultures négatives chez un patient avec cancer ou maladie auto-immune.","danger":false,"src":"152 p. 250, 255"}],"pieges":["Fièvre + souffle, AVC, purpura, lombalgie ou cardiopathie : toujours penser EI.","Antibiotiques avant les hémocultures : faute grave, surtout chez un porteur de prothèse.","L'absence de souffle n'élimine pas l'EI ; une échographie normale non plus (la répéter à 7-10 jours).","Hémocultures négatives dans 10 % des cas : antibiothérapie préalable, germes à croissance difficile, EI non infectieuse.","Ne pas oublier l'ETO systématique en cas de matériel intracardiaque, et le chirurgien cardiaque prévenu dès le diagnostic.","Prothèse mécanique : ne jamais donner d'AOD, et penser à la thrombose devant un OAP ou un choc brutal."],"src":"152 p. 248-265 ; 153 p. 268-290"},{"id":"souffle","spe":"cardio","title":"Souffle cardiaque découvert","emoji":"🩺","items":["233","238","152"],"hook":"Un souffle découvert à l'auscultation pose trois questions dans cet ordre : est-il organique ? quelle valve ? y a-t-il de la fièvre (endocardite) ?","intro":"Le souffle est souvent le seul signe d'une valvulopathie silencieuse (RA, IM, IA) et, avec une fièvre, le premier indice d'une endocardite infectieuse. Chez l'enfant, il est le plus souvent innocent. Ton rôle : caractériser le souffle (temps, siège, irradiation, intensité), chercher les symptômes d'effort, ne jamais oublier la fièvre et savoir quand adresser au spécialiste.","steps":[{"key":"terrain","title":"Terrain et antécédents","goal":"Situer le souffle dans son contexte : âge, valvulopathie ou cardiopathie connue, risque d'endocardite, antécédents familiaux.","questions":[{"ask":"« Quel âge a-t-il ? » (nouveau-né, nourrisson, enfant, adulte, sujet âgé)","why":"L'âge oriente d'emblée : 90 % des souffles du nourrisson sont organiques ; plus des trois quarts des souffles de l'enfant d'âge scolaire sont fonctionnels. Chez l'adulte : RA dégénératif après 65 ans, bicuspidie avant.","flag":"orientation","src":"238 p. 293; 233 p. 197-198"},{"ask":"« Comment le souffle a-t-il été découvert : par hasard, lors d'un bilan, ou à cause de symptômes ? »","why":"Le souffle est le plus souvent une découverte fortuite ; il peut aussi être révélé par des symptômes ou une complication (insuffisance cardiaque, FA).","flag":"terrain","src":"233 p. 198, 214; 238 p. 295"},{"ask":"« Vous a-t-on déjà dit que vous aviez un souffle ou une maladie des valves ? Le souffle a-t-il changé ? »","why":"Un nouveau souffle ou la modification d'un souffle connu a une valeur diagnostique considérable devant un syndrome infectieux (endocardite). Un souffle modifié impose d'adresser au spécialiste.","flag":"gravite","src":"152 p. 254; 233 p. 207"},{"ask":"« Avez-vous une prothèse de valve, un pacemaker, un défibrillateur, ou déjà eu une endocardite ? »","why":"Antécédent d'endocardite et prothèses valvulaires (chirurgicales ou percutanées) forment le groupe à haut risque d'EI ; valvulopathies, bicuspidie, CMH, stimulateurs : risque intermédiaire.","flag":"gravite","src":"152 p. 252"},{"ask":"« Avez-vous un cathéter, de la dialyse, une toxicomanie intraveineuse, ou une plaie récente ? »","why":"Les portes d'entrée cutanées (cathéter, dialyse, toxicomanie IV) sont celles des staphylocoques dorés ; l'EI du cœur droit touche toxicomanes, porteurs de stimulateur et de voies centrales.","flag":"gravite","src":"152 p. 251, 258"},{"ask":"« Avez-vous eu récemment des soins dentaires, une carie, une gencive infectée ? »","why":"La porte d'entrée buccodentaire est celle des streptocoques oraux. Prévention : bonne hygiène buccodentaire et consultation chez le dentiste 2 fois/an dans les cardiopathies à haut risque, 1 fois/an pour les autres.","flag":"orientation","src":"152 p. 251, 263"},{"ask":"« Avez-vous eu une angine mal soignée, un rhumatisme articulaire aigu ? Êtes-vous originaire d'une région à rhumatisme ? »","why":"Le RAA est devenu rare mais s'observe chez les migrants ; il donne un RA (souvent avec IA et atteinte mitrale) ou une IM.","flag":"terrain","src":"233 p. 198, 212"},{"ask":"« Prenez-vous ou avez-vous pris un coupe-faim (Médiator®, fenfluramine) ou un dérivé de l'ergot de seigle (antimigraineux) ? Eu de la radiothérapie du thorax ? »","why":"Ces expositions donnent des lésions valvulaires toxiques ou radiques (IA, IM).","flag":"terrain","src":"233 p. 212, 231"},{"ask":"« Dans la famille, quelqu'un a-t-il une bicuspidie aortique, un syndrome de Marfan, une cardiopathie congénitale ? » (enfant : syndrome malformatif ?)","why":"La bicuspidie est familiale (dépistage chez les apparentés du 1er degré) et associée à un anévrisme de l'aorte ascendante ; l'IA et l'IM peuvent survenir dans le Marfan. Chez l'enfant, un syndrome polymalformatif (échocardiographie systématique) ou une cardiopathie congénitale familiale (apparentés du 1er degré) : adresser au cardiopédiatre.","flag":"terrain","src":"233 p. 198, 228; 238 p. 295"}],"astuce":"Terrain en 3 blocs : âge (qui a quelle valve), antécédents de valve/prothèse/endocardite, et portes d'entrée (dent, peau, cathéter, drogue)."},{"key":"symptome","title":"Le symptôme, décortiqué","goal":"Chercher les symptômes d'effort qui signent une valvulopathie significative ; un patient qui a limité ses efforts se dit à tort asymptomatique.","questions":[{"ask":"« Vous essoufflez-vous plus qu'avant à l'effort ? Pour monter des escaliers, faire du vélo, marcher ? »","why":"La dyspnée d'effort est l'un des trois symptômes cardinaux du RA ; dans l'IM chronique elle s'installe souvent lentement et progressivement ; elle fait aussi partie des signes fonctionnels de l'IA. On cherche si le patient a progressivement diminué ses activités.","flag":"orientation","src":"233 p. 199, 214, 232"},{"ask":"« Avez-vous mal dans la poitrine à l'effort ? »","why":"L'angor d'effort est l'un des trois maîtres symptômes du RA ; rare dans l'IA, mais possible si l'IA est massive.","flag":"gravite","src":"233 p. 199, 232"},{"ask":"« Avez-vous eu un malaise ou une perte de connaissance à l'effort ? »","why":"La syncope d'effort est le 3e maître symptôme du RA : cassure de l'évolution, mauvais pronostic sans traitement.","flag":"gravite","src":"233 p. 199; 342 p. 313"},{"ask":"« Avez-vous des palpitations ? »","why":"Les palpitations sont un signe fonctionnel de l'IM (circonstance de découverte, ou signe tardif). La dilatation de l'oreillette gauche expose à la fibrillation atriale, complication de l'IM.","flag":"orientation","src":"233 p. 210, 214, 219"},{"ask":"« Vous sentez-vous plus fatigué qu'avant à l'effort, sans raison ? »","why":"Asthénie d'effort anormale : signe d'IM comme d'insuffisance cardiaque sur IA.","flag":"orientation","src":"233 p. 214, 232"},{"ask":"« Êtes-vous essoufflé au repos, ou en étant couché ? Vous réveillez-vous la nuit en manquant d'air ? »","why":"Dyspnée de repos, orthopnée et dyspnée paroxystique nocturne sont tardives ; les signes au repos dans l'IA sont rares, tardifs et de mauvais pronostic.","flag":"gravite","src":"233 p. 214, 232"},{"ask":"« Avez-vous eu une crise d'étouffement avec expectoration (œdème aigu du poumon) ? »","why":"L'OAP est un signe tardif et de gravité de l'IM ; l'IM aiguë est souvent responsable d'un tableau hémodynamique grave.","flag":"gravite","src":"233 p. 214"},{"ask":"« Avez-vous eu des épisodes de fièvre, des frissons depuis des jours ou des semaines ? »","why":"Une fièvre prolongée devant un souffle fait penser à l'endocardite ; c'est une circonstance de découverte de l'IM.","flag":"gravite","src":"233 p. 214; 152 p. 253"},{"ask":"« (Enfant) Boit-il ses biberons en plusieurs fois, transpire-t-il en tétant, grossit-il mal, s'essouffle-t-il à l'effort ? »","why":"Signes d'appel d'une cardiopathie chez l'enfant : difficultés alimentaires, sueurs, retard de croissance, polypnée, infections respiratoires répétées, dyspnée d'effort. Le souffle est souvent asymptomatique.","flag":"orientation","src":"238 p. 294, 296"}],"astuce":"Les 3 maîtres symptômes du rétrécissement aortique : dyspnée, angor, syncope d'effort. S'ils apparaissent, c'est le tournant de la maladie."},{"key":"associes","title":"Signes associés","goal":"Repérer l'endocardite et ses complications, l'insuffisance cardiaque, et les signes de cardiopathie congénitale chez l'enfant.","questions":[{"ask":"« Vous avez de la fièvre, des frissons, vous avez maigri, vous êtes plus fatigué ? »","why":"Le syndrome infectieux (fièvre, altération de l'état général) associé à un souffle est évocateur d'endocardite : « souffle + fièvre ».","flag":"gravite","src":"152 p. 253"},{"ask":"« Avez-vous eu un déficit neurologique, un mal de tête violent, des troubles visuels ? »","why":"Signes d'AVC ischémique ou hémorragique, méningite ou abcès cérébral par embolie septique : « accident ischémique + fièvre ».","flag":"gravite","src":"152 p. 253-254"},{"ask":"« Avez-vous mal au dos, aux articulations, du sang dans les urines ? »","why":"Lombalgie fébrile (spondylodiscite), arthrite, hématurie (glomérulonéphrite ou infarctus rénal) sont des localisations de l'EI.","flag":"gravite","src":"152 p. 253-254"},{"ask":"« Avez-vous remarqué des petites taches rouges sur la peau, sous les ongles, dans l'œil, des nodosités douloureuses au bout des doigts ? »","why":"Signes cutanéomuqueux rares (5-15 %) : purpura, faux panaris d'Osler pathognomoniques, hémorragies sous-unguéales et sous-conjonctivales, placards de Janeway.","flag":"gravite","src":"152 p. 254"},{"ask":"« Toussez-vous, avez-vous eu des pneumonies à répétition ? »","why":"Pneumopathies récidivantes abcédées par embolies septiques évoquent une EI du cœur droit.","flag":"orientation","src":"152 p. 254, 258"},{"ask":"« Avez-vous des chevilles gonflées, une prise de poids rapide, du mal à vous allonger ? »","why":"Signes d'insuffisance cardiaque ; toute insuffisance cardiaque fébrile doit faire évoquer l'endocardite.","flag":"gravite","src":"152 p. 254; 233 p. 214"},{"ask":"« Avez-vous eu des malaises, des lipothymies ? »","why":"Syncope ou lipothymie peut traduire un BAV dû à un abcès septal (EI) ; dans le RA, la syncope est d'effort.","flag":"gravite","src":"152 p. 254; 233 p. 199"},{"ask":"« (Enfant) Y a-t-il une coloration bleutée des lèvres ou des ongles ? »","why":"La cyanose se confirme par la saturation transcutanée ; elle est réfractaire à l'oxygène quand elle est d'origine cardiaque.","flag":"gravite","src":"238 p. 294, 296"}],"astuce":"Souffle + fièvre = endocardite jusqu'à preuve du contraire. Cinq tableaux fébriles évocateurs : cardiopathie à risque, souffle, accident ischémique, purpura, lombalgie."},{"key":"orientation","title":"Les questions qui orientent","goal":"À partir des caractères du souffle et du contexte, nommer la valve atteinte (RA, IM, IA) ou le type de souffle chez l'enfant.","questions":[{"ask":"Souffle systolique râpeux, maximal au 2e espace intercostal droit, irradiant aux carotides, avec symptômes d'effort ?","if":"Si oui → rétrécissement aortique","why":"Souffle mésosystolique éjectionnel intense, râpeux, renforcé après une diastole longue ; abolition de B2 dans les RA serrés calcifiés. Dégénératif après 65-70 ans, bicuspidie avant, RAA chez les migrants.","flag":"orientation","src":"233 p. 197-199"},{"ask":"Souffle en jet de vapeur à la pointe, de B1 à B2, irradiant dans l'aisselle ?","if":"Si oui → insuffisance mitrale","why":"Souffle holosystolique de régurgitation, ne se renforçant pas après diastole longue. Dans le prolapsus de la valve postérieure, l'irradiation peut se faire vers la base. Dans le prolapsus, le souffle débute parfois après B1 par un clic mésosystolique : il est alors mésotélésystolique ou télésystolique.","flag":"orientation","src":"233 p. 214-215"},{"ask":"Souffle diastolique prédominant au foyer aortique, irradiant le long du bord gauche du sternum, mieux entendu penché en avant en expiration bloquée, avec hyperpulsatilité des pouls ?","if":"Si oui → insuffisance aortique","why":"Souffle diastolique prédominant au foyer aortique, avec choc de pointe étalé dévié « en dôme », hyperpulsatilité artérielle et élargissement de la pression différentielle avec abaissement de la diastolique (IA sévère).","flag":"orientation","src":"233 p. 232-233"},{"ask":"Fièvre associée à un souffle nouveau ou modifié ?","if":"Si oui → pense à l'endocardite infectieuse (hémocultures avant l'antibiothérapie)","why":"La plus grande valeur diagnostique est à l'apparition d'un nouveau souffle ou à la modification d'un souffle connu ; l'absence de souffle n'exclut pas l'EI.","flag":"gravite","src":"152 p. 253-254"},{"ask":"Enfant d'âge scolaire, asymptomatique, souffle systolique bref, doux, < 3/6, variable avec la position, sans irradiation ni frémissement ?","if":"Si oui → souffle innocent (fonctionnel)","why":"Souffles anorganiques : systoliques (jamais diastoliques), proto ou mésosystoliques, sans modification de B1/B2, examen normal. Ils sont favorisés par fièvre, effort, émotion, anémie, hyperthyroïdie, anomalies du thorax. Aucun examen n'est indiqué si toutes les conditions sont réunies.","flag":"orientation","src":"238 p. 296, 302"},{"ask":"Souffle diastolique, ou frémissant, ou irradiant largement chez l'enfant ?","if":"Si oui → souffle organique (diastolique et frémissant : toujours ; irradiation large : a priori)","why":"Un souffle diastolique ou un double souffle est toujours organique ; un souffle frémissant est toujours organique ; un souffle bruyant irradiant largement est a priori organique. Un souffle néonatal est toujours potentiellement pathologique.","flag":"gravite","src":"238 p. 296, 298"},{"ask":"Nourrisson avec souffle holosystolique râpeux parasternal gauche irradiant en rayons de roue, mauvaise prise des biberons ?","if":"Si oui → communication interventriculaire","why":"CIV restrictive : souffle holosystolique intense ; CIV large : souffle faible avec B1 fort. Les larges shunts sont à opérer tôt (1re année) pour éviter l'HTAP irréversible.","flag":"orientation","src":"238 p. 300-301"},{"ask":"Souffle systolique doux sous-claviculaire gauche irradiant dans le dos, HTA, pouls fémoraux faibles ?","if":"Si oui → coarctation de l'aorte","why":"Symptomatique dès les premiers jours de vie si néonatale (pouls fémoraux abolis, chirurgie urgente) ; plus tard HTA, gradient tensionnel membres supérieurs/inférieurs.","flag":"gravite","src":"238 p. 298, 301"},{"ask":"Souffle systolique pulmonaire avec dédoublement fixe de B2 chez un enfant bien toléré ?","if":"Si oui → communication interatriale","why":"Souffle lié à l'hyperdébit à travers la valve pulmonaire, avec dédoublement fixe et constant de B2. Un DB2 large et fixe est anormal.","flag":"orientation","src":"238 p. 293, 301"}],"astuce":"Souffle systolique en haut à droite = RA. Systolique à la pointe = IM. Diastolique au bord gauche du sternum = IA. Chez l'enfant : diastolique, frémissant ou irradiant = organique ; bref, doux, variable = innocent."},{"key":"examen","title":"Examen clinique ciblé","goal":"Caractériser le souffle comme au cabinet (temps, siège, irradiation, intensité, variabilité), puis chercher le retentissement et l'endocardite.","questions":[{"ask":"Préciser le temps du souffle : systolique, diastolique, systolodiastolique ou continu ; sa durée (proto, méso, télé, holosystolique)","why":"Premier critère : un souffle diastolique est toujours organique ; les souffles innocents sont presque toujours systoliques et brefs.","flag":"orientation","src":"238 p. 295-296"},{"ask":"Localiser le souffle sur les foyers (aortique, pulmonaire, mitral, tricuspidien) et noter les irradiations (cou, aisselle, dos, rayons de roue)","why":"Un souffle entendu ou frémissant dans le cou et en sus-sternal évoque probablement un obstacle aortique ; un souffle entendu dans le dos évoque un obstacle pulmonaire ; un souffle panradiant à partir de la région mésocardiaque évoque une CIV. Le souffle du RA irradie dans les vaisseaux du cou ; celui de l'IM le plus souvent vers l'aisselle.","flag":"orientation","src":"238 p. 296; 233 p. 199, 214"},{"ask":"Coter l'intensité sur 6 et chercher un frémissement (thrill)","why":"Frémissement palpatoire au foyer aortique : RA hémodynamiquement significatif, 4/6. Un thrill est toujours pathologique chez l'enfant. L'intensité ne corrèle pas toujours avec la gravité.","flag":"orientation","src":"238 p. 294-297 ; 233 p. 199"},{"ask":"Faire varier : respiration, position (couché, assis, debout), compression vasculaire","why":"La variabilité est une caractéristique très importante : un souffle variable dans le temps et avec la position est pratiquement toujours innocent.","flag":"orientation","src":"238 p. 296"},{"ask":"Écouter B1 et B2 : abolition, dédoublement fixe ou variable, éclat, clic, B3 (galop)","why":"B2 aboli dans le RA serré ; DB2 fixe (CIA), éclat de B2 (HTAP), clic protosystolique, galop : un seul de ces signes suffit à adresser l'enfant au spécialiste.","flag":"gravite","src":"233 p. 199; 238 p. 293, 297"},{"ask":"Palper le choc de pointe et prendre les pouls périphériques (carotides, fémoraux), la PA","why":"Choc de pointe élargi et dévié en bas et à gauche dans le RA évolué (dilatation du VG) ; choc « en dôme » dans l'IA, avec hyperpulsatilité artérielle et pression différentielle élargie. Chez l'enfant : pouls huméraux et fémoraux, PA mesurée au membre supérieur et au membre inférieur.","flag":"orientation","src":"233 p. 199, 233; 238 p. 296-297"},{"ask":"Rechercher des signes d'insuffisance cardiaque : râles crépitants, œdèmes, hépatomégalie (nourrisson)","why":"Râles crépitants dans l'IM évoluée ; hépatomégalie signe le plus pertinent d'insuffisance cardiaque chez le nourrisson.","flag":"gravite","src":"233 p. 215; 238 p. 294"},{"ask":"Chercher les signes d'endocardite : température, splénomégalie, purpura, faux panaris d'Osler, hémorragies sous-unguéales, placards de Janeway, taches de Roth","why":"Maladie systémique à présentation polymorphe : tous les signes ne sont pas forcément présents.","flag":"gravite","src":"152 p. 253-254"},{"ask":"Mesurer la saturation en O2 (enfant) et la croissance pondérale","why":"Cyanose confirmée par saturomètre ; la courbe de croissance est un paramètre important de l'examen.","flag":"orientation","src":"238 p. 294, 296"}],"astuce":"Décris toujours un souffle avec 6 mots : temps, siège, irradiation, intensité, timbre, variabilité. Puis B2 et pouls."},{"key":"gravite","title":"Signes de gravité (à chercher d'emblée)","goal":"Repérer ce qui impose une prise en charge rapide : endocardite, valvulopathie aiguë, RA symptomatique, cardiopathie de l'enfant.","questions":[{"ask":"Fièvre avec souffle chez un patient à risque ou avec prothèse","why":"L'EI est grave (mortalité hospitalière 15-30 %). Hémocultures puis antibiothérapie probabiliste si forte suspicion ou sepsis sévère. Notion inacceptable du Collège : ne pas penser à une EI en cas de fièvre.","flag":"gravite","src":"152 p. 253-254, 259-260; 233 p. 207"},{"ask":"Insuffisance cardiaque fébrile ou OAP","why":"Toute insuffisance cardiaque fébrile doit faire évoquer l'endocardite ; l'insuffisance cardiaque aiguë est l'une des deux principales causes de décès dans l'EI.","flag":"gravite","src":"152 p. 254, 259"},{"ask":"Déficit neurologique ou autre embolie","why":"Complications neurologiques : l'une des deux principales causes de décès dans l'EI et facteur de mauvais pronostic.","flag":"gravite","src":"152 p. 254, 259"},{"ask":"Syncope, lipothymie, bloc à l'ECG chez un patient avec endocardite aortique","why":"BAV par abcès septal.","flag":"gravite","src":"152 p. 253-254"},{"ask":"Syncope, angor ou dyspnée d'effort avec souffle aortique","why":"RA symptomatique : tournant évolutif, risque de mort subite, indication de traitement.","flag":"gravite","src":"233 p. 199, 204"},{"ask":"Insuffisance mitrale ou aortique aiguë (rupture de cordage, EI, dissection, infarctus)","why":"Régurgitation aiguë souvent mal tolérée : OAP, urgence ; rupture de pilier dans l'infarctus = choc et urgence chirurgicale. IA aiguë : douleur thoracique ou AVC sans fièvre = penser à la dissection aortique.","flag":"gravite","src":"233 p. 213-214, 232, 244"},{"ask":"Fibrillation atriale d'apparition récente","why":"Mal tolérée dans le RA (perte de la systole atriale), complication de l'IM.","flag":"gravite","src":"233 p. 197, 204, 219"},{"ask":"(Enfant) Cyanose, insuffisance cardiaque, retard staturopondéral, HTA, pouls fémoraux anormaux","why":"Ne pas adresser au cardiopédiatre dans ces situations est inacceptable.","flag":"gravite","src":"238 p. 294, 304"},{"ask":"(Enfant) Frémissement précordial, DB2 fixe, éclat de B2, clic protosystolique, galop","why":"Un seul de ces signes impose d'adresser l'enfant au spécialiste.","flag":"gravite","src":"238 p. 297, 304"},{"ask":"(Nouveau-né) Tout souffle, même asymptomatique","why":"Toujours potentiellement pathologique : échographie cardiaque avant la sortie de la maternité.","flag":"gravite","src":"238 p. 298, 304"}],"astuce":"Trois urgences à reconnaître : endocardite (fièvre), RA symptomatique (syncope d'effort), régurgitation aiguë (OAP, dissection). Chez l'enfant : nouveau-né, cyanose, IC."},{"key":"examens","title":"Examens de 1re intention","goal":"Confirmer le souffle (ETT), mesurer la sévérité et le retentissement, et documenter l'endocardite si fièvre.","questions":[{"ask":"Échocardiographie-doppler transthoracique","why":"Examen clé de toute valvulopathie : diagnostic, mécanisme, étiologie, sévérité et retentissement. Chez l'enfant, examen clé aussi ; indiquée seulement en cas de doute pour un souffle innocent.","flag":"orientation","src":"233 p. 200, 216; 238 p. 297, 302"},{"ask":"RA serré si : Vmax > 4 m/s, gradient moyen > 40 mmHg, surface < 1 cm² (ou < 0,6 cm²/m²)","why":"Critères de RA serré ; un RA peut être serré malgré un gradient < 40 mmHg si le débit est bas (volume d'éjection ≤ 35 mL/m²).","flag":"orientation","src":"233 p. 202"},{"ask":"ECG 12 dérivations","why":"RA : HVG de surcharge systolique, troubles de conduction, FA. IM : HAG, HVG, FA. IA : HVG. Peut être normal. Chez l'enfant, interpréter selon l'âge.","flag":"orientation","src":"233 p. 200, 215, 233; 238 p. 297"},{"ask":"Radiographie thoracique","why":"Dilatation du VG, surcharge pulmonaire ; chez l'enfant, cardiomégalie, vascularisation pulmonaire.","flag":"orientation","src":"233 p. 200, 215; 238 p. 297"},{"ask":"Si fièvre : 3 hémocultures espacées d'au moins 30 min, avant toute antibiothérapie","why":"Isolent le germe dans 90 % des cas. À répéter 2-3 jours si négatives. Signaler la suspicion au laboratoire.","flag":"gravite","src":"152 p. 254"},{"ask":"Si EI suspectée : ETT en 1re intention puis ETO (si ETT positive, négative avec forte suspicion, ou matériel intracardiaque)","why":"Une échographie normale n'élimine pas l'EI : à répéter après 7-10 jours. Scanner cardiaque et TEP-scan en renfort sur prothèse.","flag":"orientation","src":"152 p. 255-256"},{"ask":"NFS, CRP, ionogramme, créatinine, bandelette urinaire, scanner cérébral et thoraco-abdomino-pelvien si EI","why":"Syndrome inflammatoire, atteinte rénale, localisations septiques secondaires à rechercher, ainsi que la porte d'entrée.","flag":"orientation","src":"152 p. 256"},{"ask":"Épreuve d'effort si RA serré asymptomatique","why":"Vérifie objectivement le caractère asymptomatique (le patient s'est adapté) et la réponse tensionnelle.","flag":"orientation","src":"233 p. 204"},{"ask":"Coronarographie ou coroscanner avant chirurgie ; scanner avant TAVI","why":"Bilan préopératoire selon l'âge et les facteurs de risque ; scanner cardiaque systématique avant TAVI.","flag":"orientation","src":"233 p. 204, 207, 223"},{"ask":"(Enfant) Adresser au cardiopédiatre : examen, écho-doppler, ECG ; radiographie rarement","why":"Dans l'immense majorité des cas, l'interrogatoire et l'examen font le diagnostic organique ou fonctionnel ; en cas de souffle fonctionnel, aucun suivi ni restriction.","flag":"orientation","src":"238 p. 297, 302-303"}],"astuce":"ETT dans presque tous les cas d'adulte. Fièvre + souffle : hémocultures d'abord (3, avant antibio), puis écho. Souffle innocent de l'enfant : pas d'examen si tout colle."}],"synthese":"M. P., 78 ans, hypertendu, consulte pour une dyspnée d'effort croissante depuis quelques semaines et un malaise survenu en montant les escaliers. À l'auscultation : souffle systolique râpeux au 2e espace intercostal droit irradiant aux carotides, B2 aboli, sans fièvre. ECG avec hypertrophie ventriculaire gauche. Hypothèses : rétrécissement aortique dégénératif serré (principale), cardiomyopathie hypertrophique obstructive moins probable ; à confirmer par ETT. Si le même patient avait de la fièvre et un souffle nouveau : endocardite à éliminer en urgence.","hypotheses":[{"dx":"Rétrécissement aortique (dégénératif ou bicuspidie)","pour":"Souffle mésosystolique râpeux, 2e EICD, irradiation carotidienne, B2 aboli, dyspnée/angor/syncope d'effort, sujet âgé","danger":true,"src":"233 p. 197-199"},{"dx":"Insuffisance mitrale","pour":"Souffle holosystolique apexien en jet de vapeur irradiant à l'aisselle, dyspnée d'effort, palpitations ou FA","danger":false,"src":"233 p. 214-215"},{"dx":"Insuffisance aortique","pour":"Souffle diastolique prédominant au foyer aortique, hyperpulsatilité des pouls, pression différentielle élargie, choc de pointe en dôme, Marfan ou bicuspidie","danger":false,"src":"233 p. 232-233"},{"dx":"Endocardite infectieuse","pour":"Fièvre, souffle nouveau ou modifié, cardiopathie ou prothèse à risque, portes d'entrée, signes emboliques","danger":true,"src":"152 p. 253-254"},{"dx":"Cardiomyopathie hypertrophique obstructive","pour":"Souffle systolique éjectionnel au bord gauche du sternum, syncope à l'effort ou après","danger":true,"src":"342 p. 313"},{"dx":"Souffle innocent de l'enfant","pour":"Enfant d'âge scolaire, bref, doux, < 3/6, variable avec la position, sans irradiation, examen normal","danger":false,"src":"238 p. 302"},{"dx":"Communication interventriculaire","pour":"Nourrisson, souffle holosystolique râpeux parasternal gauche en rayons de roue, mauvaise croissance","danger":true,"src":"238 p. 300"},{"dx":"Coarctation de l'aorte","pour":"Souffle sous-claviculaire gauche irradiant dans le dos, HTA, pouls fémoraux abolis ou diminués","danger":true,"src":"238 p. 298, 301"},{"dx":"Communication interatriale","pour":"Souffle systolique pulmonaire et dédoublement fixe de B2, enfant bien toléré","danger":false,"src":"238 p. 301"}],"pieges":["Chez l'enfant, l'intensité du souffle ne reflète généralement pas la gravité : petite CIV = souffle intense ; cardiopathie grave possible sans souffle.","Fièvre, effort, anémie favorisent un souffle innocent chez l'enfant, mais vérifie quand même tous les critères d'organicité.","Sténose valvulaire avec souffle modifié ou nouveaux symptômes : adresser au spécialiste (ne pas le faire est une notion inacceptable).","Souffle + fièvre : penser à l'endocardite ; hémocultures avant tout antibiotique.","Un souffle de RA peut s'atténuer dans le RA évolué à bas débit : ne pas rassurer sur la seule auscultation.","Patient qui dit « ne pas avoir de symptômes » : il a peut-être limité ses efforts."],"src":"233 p. 193-247 ; 238 p. 292-305 ; 152 p. 248-263"},{"id":"patient-anticoagule","spe":"cardio","title":"Patient sous anticoagulant ou antiagrégant","emoji":"💊","items":["330","232","226","153"],"hook":"Un anticoagulant protège d'un caillot et expose à un saignement : toute la consultation consiste à vérifier que l'équilibre n'a pas basculé d'un côté ou de l'autre.","intro":"Tu vois un patient dont le traitement antithrombotique est une évidence pour lui et une zone de piège pour toi : indication, molécule, dose, surveillance, interactions, éducation. Les anticoagulants sont responsables d'une iatrogénie importante (les AVK sont la 1re cause iatrogène d'hospitalisation). Ton état d'esprit : comprendre pourquoi il est traité, vérifier le traitement, chercher un saignement et chercher aussi un caillot.","steps":[{"key":"terrain","title":"Terrain : pourquoi ce traitement ?","goal":"Retrouver l'indication, car elle décide de la molécule, de la cible, de la durée et de ce qui est interdit.","questions":[{"ask":"« Pourquoi prenez-vous ce traitement ? Qui vous l'a prescrit et depuis quand ? »","why":"L'indication conditionne tout : prévention secondaire de la coronaropathie, de l'AOMI et des AVC (antiagrégant), FA, maladie thromboembolique veineuse, prothèse valvulaire.","flag":"orientation","src":"330 p. 561, 232 p. 334, 226 p. 513"},{"ask":"« Avez-vous un trouble du rythme du cœur, une fibrillation atriale ? Intermittente ou permanente ? »","why":"En cas de FA, l'anticoagulation dépend du score CHA2DS2-VA : score nul, pas d'anticoagulant ; score > 1, anticoagulants oraux indiqués de façon indiscutable ; score = 1, conseillés avec discussion au cas par cas (le tableau 13.1 résume : ≥ 1 → AOD, ou AVK). Le type de FA (paroxystique, persistante, permanente) n'intervient pas.","flag":"orientation","src":"232 p. 334"},{"ask":"« Avez-vous une insuffisance cardiaque, de l'hypertension, un diabète, déjà eu un AVC ou un infarctus, une artérite ? Quel âge avez-vous ? »","why":"Ce sont les éléments du score CHA2DS2-VA : insuffisance cardiaque 1, HTA 1, âge ≥ 75 ans 2, diabète 1, AVC ou embolie 2, atteinte vasculaire 1, âge 65-74 ans 1.","flag":"terrain","src":"232 p. 334"},{"ask":"« Avez-vous une valve cardiaque artificielle ? Mécanique ou biologique ? Mitrale ou aortique ? Posée par chirurgie ou par cathéter ? Avez-vous un rétrécissement mitral ? »","why":"Valve mécanique : AVK à vie, AOD formellement contre-indiqués. Bioprothèse : pas d'anticoagulation au long cours sauf FA ou autre indication. TAVI : aspirine seule au long cours en rythme sinusal.","flag":"orientation","src":"153 p. 270, 272, 273, 283"},{"ask":"« Avez-vous déjà eu une phlébite ou une embolie pulmonaire ? Quand ? Y avait-il une cause : opération, plâtre, immobilisation, voyage, grossesse, pilule, cancer ? »","why":"La durée dépend du contexte : 3 mois si facteur transitoire majeur, 6 mois sinon, davantage voire au long cours en cas de récidive ou de facteur persistant majeur ; tant que le cancer est actif.","flag":"orientation","src":"226 p. 495, 513, 514"},{"ask":"« Avez-vous eu un infarctus ou une pose de stent ? À quelle date ? »","why":"Après un SCA ou un stent, on prescrit une double antiagrégation (aspirine + clopidogrel, ticagrélor ou prasugrel), classiquement 12 mois ; durée raccourcie si risque hémorragique.","flag":"orientation","src":"330 p. 563, 579"},{"ask":"« Vos reins fonctionnent-ils bien ? Connaissez-vous votre dernière créatinine ? »","why":"Les HBPM et le fondaparinux sont contre-indiqués (ou plutôt contre-indiqués) si la clairance de la créatinine est < 30 mL/min ; les AOD sont déconseillés en dessous de 30 à 25 mL/min ; l'HNF est le seul anticoagulant utilisable dans les insuffisances rénales sévères.","flag":"orientation","src":"330 p. 564, 569"},{"ask":"« Avez-vous déjà saigné de l'estomac, de l'intestin ou du cerveau ? Une maladie du foie, un problème de plaquettes, une opération ou un traumatisme récents ? »","why":"Les comorbidités qui favorisent un accident hémorragique : pathologie digestive ou cérébrale à risque, insuffisance hépatocellulaire, chirurgie ou traumatisme récents, thrombopénie, trouble de la coagulation, insuffisance rénale.","flag":"terrain","src":"330 p. 573"},{"ask":"« (Femme) Prenez-vous une pilule œstroprogestative ? Êtes-vous enceinte ou envisagez-vous une grossesse ? »","why":"Les AVK sont tératogènes. Après une MTEV, la contraception œstroprogestative est contre-indiquée. Un désir de grossesse est un argument en faveur d'une bioprothèse.","flag":"orientation","src":"330 p. 568, 226 p. 517, 153 p. 275"},{"ask":"« Avez-vous un cancer, en cours de traitement ? »","why":"En cas de cancer, la MTEV est traitée par HBPM prolongée car les AVK sont moins efficaces et moins bien tolérés ; la durée est prolongée tant que le cancer est actif.","flag":"terrain","src":"226 p. 513, 517"}],"astuce":"Une phrase à garder : « pourquoi, depuis quand, jusqu'à quand ». Si tu ne connais pas l'indication, tu ne peux ni juger la cible ni décider d'arrêter."},{"key":"symptome","title":"Le traitement lui-même : molécule, dose, surveillance","goal":"Savoir exactement ce que prend le patient, comment, et si la surveillance est faite et fiable.","questions":[{"ask":"« Quel est le nom de votre médicament ? Pouvez-vous me montrer l'ordonnance ou la boîte ? »","why":"Classe et surveillance diffèrent : antiagrégants (aspirine, clopidogrel, prasugrel, ticagrélor), héparines, AVK (warfarine, fluindione, acénocoumarol), AOD (dabigatran, rivaroxaban, apixaban).","flag":"orientation","src":"330 p. 560, 563, 566, 569"},{"ask":"« À quelle dose, combien de fois par jour, à quelle heure ? »","why":"Acénocoumarol (Sintrom®) : 2 prises par jour. AOD : 2 fois/j pour dabigatran et apixaban, 1 fois/j pour rivaroxaban (2 fois/j en début de traitement de TVP/EP). Posologie des AOD adaptée à l'âge, à la fonction rénale et au poids.","flag":"terrain","src":"330 p. 566, 570, 580"},{"ask":"« Vous arrive-t-il d'oublier une prise, ou d'arrêter le traitement quand vous vous sentez bien ? »","why":"Un traitement anticoagulant insuffisant est le principal facteur de risque de complications thromboemboliques d'une prothèse valvulaire. Avec les AOD, la vérification de l'observance est difficile.","flag":"orientation","src":"153 p. 276, 330 p. 570"},{"ask":"(Sous AVK) « Quel est votre INR cible ? Quel était votre dernier INR ? Avez-vous votre carnet ? »","why":"Cible INR 2-3 pour la plupart des indications ; pour les prothèses mécaniques entre 2,5 et 4, avec une variation maximale tolérée de 0,5 (tableau 10.2 : prothèse à risque thrombotique faible 2,5, moyen 3,0, élevé 3,5 ; 3,0 / 3,5 / 4,0 si au moins un facteur lié au patient : remplacement mitral ou tricuspide, antécédent thromboembolique, FA, sténose mitrale, FEVG < 35 %). En cas de FA sur prothèse mécanique, l'item 232 donne 2,5 (2 à 3) sauf valve mécanique mitrale ou à disque (3-4,5). Bien équilibré = au moins 70 % des INR dans la cible.","flag":"orientation","src":"330 p. 567, 153 p. 283, 286, 232 p. 336"},{"ask":"(Sous AVK) « À quelle fréquence contrôlez-vous votre INR ? »","why":"À l'instauration, 2 fois/semaine puis espacé ; au long cours au minimum 1 fois/mois. Pour une prothèse mécanique, 1 à 2 fois/semaine au début puis au moins 1 fois/mois.","flag":"orientation","src":"330 p. 567, 153 p. 286"},{"ask":"« Mesurez-vous votre INR vous-même avec un appareil ? »","why":"L'automesure peut diminuer le risque hémorragique ; remboursée depuis 2017 pour les porteurs de prothèse mécanique (et chez l'enfant). Elle n'est possible que chez environ 50 % des patients.","flag":"terrain","src":"330 p. 567, 578, 153 p. 287"},{"ask":"« Avez-vous commencé un nouveau médicament récemment : antibiotique, antifongique, anti-inflammatoire, amiodarone ? »","why":"Interactions des AOD : macrolides, antiprotéases, antifongiques azolés, certains anticancéreux, amiodarone, diltiazem, vérapamil. Les AINS augmentent le risque hémorragique des AVK et des AOD. Toute coprescription est à éviter.","flag":"orientation","src":"330 p. 570, 573"},{"ask":"« Prenez-vous de l'aspirine ou des anti-inflammatoires en plus, en automédication ? »","why":"L'association d'un autre antithrombotique (AVK, antiagrégant) ou d'un AINS augmente le risque hémorragique. En Europe, l'adjonction d'un antiagrégant à l'AVK pour une prothèse valvulaire n'est pas recommandée hors situations spécifiques.","flag":"orientation","src":"330 p. 573, 153 p. 286"},{"ask":"« Avez-vous changé votre alimentation récemment ? Vous a-t-on expliqué les précautions alimentaires sous votre traitement ? »","why":"L'éducation du patient sous AVK inclut les précautions alimentaires, la fréquence de l'INR, les interactions, les signes d'alarme hémorragiques et un carnet de suivi.","flag":"terrain","src":"232 p. 337"},{"ask":"« Avez-vous eu des piqûres d'héparine ces dernières semaines ? Depuis combien de jours ? »","why":"Le risque de thrombopénie induite par l'héparine survient typiquement entre 5 et 8 jours après le début ; plus tôt (dès J1) si exposition dans les 3 mois précédents, plus tard avec les HBPM.","flag":"orientation","src":"330 p. 574"},{"ask":"« Avez-vous votre carte de porteur de prothèse, votre carnet d'anticoagulant, votre carte d'antibioprophylaxie pour le dentiste ? »","why":"Le porteur de valve doit avoir une carte de porteur (type, diamètre, numéro de série), un carnet de surveillance de l'anticoagulation avec l'INR cible et une carte d'antibioprophylaxie.","flag":"terrain","src":"153 p. 284"},{"ask":"« Devez-vous avoir prochainement une opération, une coloscopie, des soins dentaires ? »","why":"Pour les gestes à risque hémorragique, les règles diffèrent selon le médicament : aspirine, AVK avec ou sans relais héparine.","flag":"orientation","src":"330 p. 562, 568-569"}],"astuce":"Trois lignes à noter sur l'ordonnance de ta mémoire : molécule + dose, dernier INR (AVK) ou dernière prise (AOD), indication. Le reste en découle."},{"key":"associes","title":"Signes associés : saignement d'un côté, caillot de l'autre","goal":"Chercher à la fois les signes de saignement (surdosage ou fragilité) et les signes de thrombose (sous-dosage).","questions":[{"ask":"« Avez-vous des bleus qui apparaissent facilement, des saignements de nez, des gencives qui saignent ? »","why":"Purpura, ecchymoses, hématome, épistaxis : manifestations hémorragiques classiques, un hématome peut être favorisé par un traumatisme.","flag":"orientation","src":"330 p. 559, 153 p. 280"},{"ask":"« Avez-vous remarqué du sang dans les urines ? »","why":"Une hématurie sous anticoagulant doit faire rechercher une lésion organique sous-jacente.","flag":"orientation","src":"153 p. 280"},{"ask":"« Vos selles sont-elles noires, avec du sang ? Avez-vous vomi du sang ? »","why":"Méléna, rectorragies, hémorragie digestive : hémorragie de tout type sous AVK. Une hémorragie digestive doit faire rechercher une lésion.","flag":"gravite","src":"330 p. 559, 153 p. 280"},{"ask":"« (Femme) Vos règles sont-elles devenues plus abondantes, avez-vous des saignements entre les règles ? »","why":"Les ménométrorragies font partie des complications hémorragiques des AVK.","flag":"orientation","src":"153 p. 280"},{"ask":"« Êtes-vous plus fatigué, plus pâle, essoufflé à l'effort ? »","why":"Sous héparine, une anémie typiquement microcytaire ferriprive peut exister sans hémorragie apparente : d'où la NFS régulière lors des traitements de longue durée.","flag":"orientation","src":"330 p. 573"},{"ask":"« Avez-vous mal à la tête de façon inhabituelle ? Avez-vous fait une chute ou reçu un coup sur la tête ? »","why":"L'hémorragie cérébrale est une complication possible ; après un traumatisme crânien sous AVK, hospitalisation d'au moins 24 heures et scanner cérébral en urgence.","flag":"gravite","src":"153 p. 280, 330 p. 578"},{"ask":"« Avez-vous eu une perte de force d'un bras ou d'une jambe, même passagère ? »","why":"Les embolies systémiques d'une prothèse sont le plus souvent cérébrales (70 % des cas : AIT ou AVC constitué) ; un traitement anticoagulant insuffisant est le principal facteur de risque.","flag":"gravite","src":"153 p. 276"},{"ask":"« Avez-vous un mollet gonflé et douloureux d'un seul côté ? Un essoufflement brutal, un point de côté, un malaise ? »","why":"TVP : douleur, œdème unilatéral du membre inférieur, signes inflammatoires ; EP : dyspnée, douleur thoracique de type point de côté, syncope, crachats hémoptoïques.","flag":"gravite","src":"226 p. 497, 504"},{"ask":"« Un bras ou une jambe froids, pâles, douloureux ? »","why":"Plus rarement que l'embolie cérébrale, l'embolie systémique d'une prothèse peut donner une ischémie aiguë d'un membre.","flag":"gravite","src":"153 p. 276"},{"ask":"« Avez-vous des plaques rouges ou douloureuses aux points de piqûre ? »","why":"Les placards inflammatoires au site d'injection sous héparine font évoquer une thrombopénie induite par l'héparine.","flag":"orientation","src":"330 p. 574"}],"astuce":"Pense toujours aux deux faces de la pièce : saignement = trop de traitement ou fragilité ; AVC, EP, ischémie de membre = pas assez de traitement."},{"key":"orientation","title":"Les questions qui orientent","goal":"Discriminer ce qui relève d'un surdosage, d'une prothèse qui dysfonctionne, d'une infection ou d'une intolérance au médicament.","questions":[{"ask":"« Avez-vous de la fièvre, même modeste ? Un mal de dents, un abcès ? »","why":"Les porteurs de prothèse ont un risque majoré d'endocardite et doivent bénéficier d'une prophylaxie draconienne. En cas de fièvre inexpliquée, les hémocultures systématiques sont indispensables AVANT toute antibiothérapie à l'aveugle, avec une échocardiographie selon le contexte ; une fébricule est aussi possible dans la thrombose de prothèse.","if":"Si oui, porteur de prothèse → suspecter une endocardite sur prothèse (hémocultures avant antibiotique, ETT puis ETO) ; fébricule possible aussi dans une thrombose de prothèse","flag":"gravite","src":"153 p. 277, 279, 280"},{"ask":"« Le bruit de votre valve a-t-il changé ? Êtes-vous plus essoufflé qu'avant ? »","why":"La réapparition d'une dyspnée ou une récidive d'insuffisance cardiaque fait suspecter une dysfonction de prothèse ; diminution des bruits de prothèse, souffle nouveau, roulement diastolique. Il faut vérifier l'INR en urgence.","if":"Si oui → thrombose ou dysfonction de prothèse, INR en urgence","flag":"gravite","src":"153 p. 277, 285"},{"ask":"« Êtes-vous plus fatigué, plus pâle qu'avant ? »","why":"Une désinsertion de prothèse (fuite paraprothétique) peut donner une anémie hémolytique : LDH élevées, haptoglobine basse, schizocytes. Elle survient surtout dans les premiers mois et est souvent liée à une endocardite.","if":"Si oui → désinsertion de prothèse avec hémolyse","flag":"orientation","src":"153 p. 281-282"},{"ask":"« Votre cœur bat-il irrégulièrement depuis peu ? »","why":"Un passage en fibrillation atriale n'est pas exceptionnel chez le porteur de prothèse, notamment mitrale. Lors d'une FA sur prothèse mécanique, seuls les AVK sont recommandés et le score CHA2DS2-VA ne s'applique pas.","if":"Si oui → FA : ECG, réévaluer l'anticoagulation (sur prothèse mécanique : AVK)","flag":"orientation","src":"153 p. 285, 232 p. 334"},{"ask":"« Après quelques jours de piqûres d'héparine, avez-vous une nouvelle phlébite, une plaque douloureuse au point d'injection ? »","why":"TIH : numération plaquettaire < 100 G/L et/ou chute relative de 30 à 50 %, apparition ou extension de thromboses, résistance biologique à l'HNF, placards inflammatoires au site d'injection. Le risque est thrombotique, pas hémorragique.","if":"Si oui → TIH : numération plaquettaire, avis spécialisé","flag":"gravite","src":"330 p. 574"},{"ask":"« (Sous ticagrélor) Êtes-vous essoufflé sans raison ? »","why":"L'effet indésirable principal du ticagrélor est la dyspnée (18 % des patients).","if":"Si oui → dyspnée, effet indésirable principal du ticagrélor","flag":"orientation","src":"330 p. 563"},{"ask":"« (Sous aspirine) Avez-vous mal à l'estomac ? De l'asthme, un nez bouché par des polypes, une allergie à l'aspirine ? »","why":"Les effets indésirables essentiels de l'aspirine sont les saignements et l'intolérance gastrique ; très rares allergies vraies ; syndrome de Widal : asthme, polypose nasale et allergie à l'aspirine.","if":"Si oui → intolérance gastrique ou syndrome de Widal","flag":"orientation","src":"330 p. 561"},{"ask":"« (Sous prasugrel) Avez-vous déjà eu un AVC ? Votre poids ? Votre âge ? »","why":"Prasugrel : contre-indication absolue = antécédent d'AVC ; relatives = poids < 60 kg, âge > 75 ans.","if":"Si oui → prasugrel à discuter","flag":"orientation","src":"330 p. 563"},{"ask":"« Votre INR était-il instable ou trop haut ces dernières semaines ? Qu'est-ce qui a changé ? »","why":"La cause d'un surdosage doit toujours être recherchée et prise en compte dans l'adaptation de la posologie.","if":"Si INR trop haut → chercher la cause du surdosage (interactions médicamenteuses...) et en tenir compte dans la posologie","flag":"orientation","src":"330 p. 577"}],"astuce":"Le trio qui change tout chez un porteur de prothèse : fièvre (endocardite), souffle/bruit modifié (thrombose, désinsertion), dyspnée (dysfonction). Ne jamais attendre."},{"key":"examen","title":"Examen clinique ciblé","goal":"Apprécier la tolérance, chercher le saignement extériorisé ou caché, le caillot, et ausculter la prothèse.","questions":[{"ask":"Pression artérielle et fréquence cardiaque, recherche de signes de choc hémorragique","why":"En cas d'accident hémorragique, on évalue la gravité par l'examen clinique, la PA, la FC et la recherche de signes de choc ; Hb et hématocrite complètent.","flag":"gravite","src":"330 p. 573"},{"ask":"Température","why":"L'absence de fièvre ou de foyer infectieux doit être vérifiée soigneusement à chaque consultation chez le porteur de prothèse ; en cas de fièvre inexpliquée, hémocultures avant toute antibiothérapie.","flag":"orientation","src":"153 p. 280, 285"},{"ask":"Peau et muqueuses : ecchymoses, hématome, purpura, gencives, épistaxis, points de piqûre","why":"Manifestations hémorragiques visibles ; les placards inflammatoires aux points d'injection d'héparine orientent vers une TIH.","flag":"orientation","src":"330 p. 559, 574"},{"ask":"Auscultation de la prothèse : bruits d'ouverture et de fermeture, souffle","why":"Prothèse mécanique : bruits intenses, claqués, métalliques ; bioprothèse : bruits identiques aux valves natives (petit souffle éjectionnel aortique). Pathologique : bruits diminués ou variables, souffle systolique qui apparaît ou augmente, bruit diastolique surajouté.","flag":"orientation","src":"153 p. 285"},{"ask":"Rythme (pouls, auscultation) : régulier ou irrégulier ?","why":"L'auscultation retrouve des bruits du cœur irréguliers en FA ; le pouls ne remplace pas l'ECG.","flag":"orientation","src":"232 p. 330-331"},{"ask":"Signes d'insuffisance cardiaque (OAP, œdèmes des membres inférieurs)","why":"OAP ou signes d'insuffisance cardiaque sont à rechercher d'emblée (FA) ; chez le porteur de prothèse, une dyspnée ou une récidive d'insuffisance cardiaque fait suspecter une dysfonction de prothèse.","flag":"gravite","src":"232 p. 331, 153 p. 277, 285"},{"ask":"Examen artériel et neurologique (déficit moteur ou sensitif)","why":"Chez le patient en FA ou porteur de prothèse, on recherche d'emblée une embolie artérielle systémique (examen artériel et neurologique).","flag":"gravite","src":"232 p. 331, 153 p. 276"},{"ask":"Membres inférieurs : œdème unilatéral, douleur, différence de circonférence > 3 cm avec le côté opposé","why":"TVP : douleur spontanée ou provoquée, œdème unilatéral d'autant plus étendu que la thrombose est proximale (différence de circonférence > 3 cm), signes inflammatoires, dilatation des veines superficielles. La clinique seule n'a qu'une valeur d'orientation et la TVP peut être asymptomatique.","flag":"orientation","src":"226 p. 497"},{"ask":"Dents et foyers infectieux ORL ; contrôle du suivi dentaire","why":"Le porteur de prothèse est à haut risque d'endocardite ; il faut insister sur la prévention et le traitement de tout foyer infectieux, notamment ORL et dentaire ; suivi dentaire au moins biannuel.","flag":"orientation","src":"153 p. 279, 284-285"}],"astuce":"L'auscultation d'un porteur de valve mécanique doit « claquer » : un bruit sourd ou variable d'un cycle à l'autre, c'est un signal d'alarme."},{"key":"gravite","title":"Signes de gravité (à chercher d'emblée)","goal":"Reconnaître en quelques secondes ce qui impose l'hôpital : hémorragie grave, thrombose de prothèse, EP à haut risque, infection.","questions":[{"ask":"Le saignement est-il grave ? Saignement extériorisé non contrôlable, instabilité hémodynamique, geste hémostatique nécessaire, transfusion nécessaire, localisation menaçante ?","why":"Hémorragie grave : au moins un de ces critères : extériorisée non contrôlable par les moyens usuels, collapsus, nécessité d'un geste hémostatique ou chirurgical, de culots globulaires, ou localisation menaçant le pronostic vital ou fonctionnel. Sinon, non grave.","flag":"gravite","src":"330 p. 577"},{"ask":"Traumatisme crânien ou céphalée inhabituelle sous anticoagulant ?","why":"Hospitalisation d'au moins 24 heures et scanner cérébral en urgence. L'hémorragie intracrânienne peut imposer une interruption très temporaire de l'anticoagulation.","flag":"gravite","src":"330 p. 578, 153 p. 280"},{"ask":"INR très élevé (> 10, ou entre 6 et 10 avec cible 2,5) ?","why":"INR cible 2,5 : < 4 : pas de saut ni de vitamine K ; 4 à 6 : saut d'une prise ; 6 à 10 : arrêt de l'AVK + 1 à 2 mg de vitamine K per os ; > 10 : arrêt + 5 mg de vitamine K per os. Contrôle de l'INR le lendemain.","flag":"gravite","src":"330 p. 576-577"},{"ask":"OAP, syncope, état de choc, mort subite chez un porteur de prothèse mécanique ?","why":"La thrombose obstructive de prothèse peut donner des accidents brutaux. Prise en charge : Usic, héparine IV + aspirine, réintervention discutée (mortalité de 30 % en thrombose aiguë), thrombolyse en cas de contre-indication chirurgicale.","flag":"gravite","src":"153 p. 277"},{"ask":"Choc ou hypotension (PAS < 90 mmHg, ou baisse de PAS > 40 mmHg pendant plus de 15 minutes) devant une suspicion d'EP ?","why":"EP à haut risque (mortalité > 15 %) : réanimation ou Usic, fibrinolyse en l'absence de contre-indication ; HNF dans ce cas.","flag":"gravite","src":"226 p. 509, 511, 513"},{"ask":"AIT ou AVC récent chez un patient anticoagulé ?","why":"Embolie systémique à partir d'une prothèse ou d'une FA. En aigu, les AVK et les héparines ne sont pas utilisables en raison du risque de transformation hémorragique, mais l'indication d'anticoagulation au long cours est impérative à la sortie ; prise en charge en unité d'urgence neurovasculaire.","flag":"gravite","src":"153 p. 276, 232 p. 338"},{"ask":"Nouvelle thrombose sous héparine avec plaquettes qui chutent ?","why":"Thrombopénie induite par l'héparine : décision à prendre dès la forte suspicion, sans attendre le laboratoire ; avis spécialisé pour éviter d'arrêter une héparine sans argument.","flag":"gravite","src":"330 p. 574-575"},{"ask":"Fièvre avec prothèse valvulaire récente (jusqu'à 1 an)","why":"L'endocardite postopératoire précoce est aiguë, avec abcès de l'anneau et désinsertion ; mortalité de l'ordre de 50 %.","flag":"gravite","src":"153 p. 279"}],"astuce":"Hémorragie grave = hôpital + arrêt de l'AVK + INR en urgence mais traitement sans attendre le résultat (vitamine K + PPSB). Ne jamais perdre de temps à attendre le laboratoire."},{"key":"examens","title":"Examens de 1re intention et conduite à tenir","goal":"Prescrire ce qui répond à la question posée (saignement, caillot, dysfonction) et appliquer la bonne antidote ou la bonne surveillance.","questions":[{"ask":"INR en urgence (patient sous AVK avec saignement, traumatisme ou suspicion de thrombose de prothèse)","why":"L'INR est systématique en cas de saignement non grave comme grave ; dans la thrombose de prothèse, un traitement anticoagulant insuffisant est souvent en cause. En cas de surdosage, adapter la posologie et contrôler l'INR le lendemain.","flag":"orientation","src":"330 p. 577-578, 153 p. 277"},{"ask":"NFS : hémoglobine, hématocrite, plaquettes","why":"Évaluation du retentissement du saignement, dépistage de l'anémie ferriprive occulte, numération plaquettaire avant ou dans les 24 heures de toute héparine (surveillance de la TIH).","flag":"terrain","src":"330 p. 573-574, 226 p. 512"},{"ask":"Créatininémie avec DFG ou clairance (Cockcroft)","why":"Indispensable pour choisir et doser : HBPM et fondaparinux contre-indiqués si ClCr < 30 ; AOD déconseillés en dessous de 30 à 25 mL/min ; suivi de la fonction rénale au moins 1 fois/an sous AOD.","flag":"terrain","src":"330 p. 569, 226 p. 512, 232 p. 337"},{"ask":"Sous HNF : TCA ou activité anti-Xa","why":"TCA allongé de 2 à 3 fois le témoin ou anti-Xa entre 0,5 et 0,8 ; 1er TCA vers la 5e heure ; surveillé au moins 1 fois par jour. Les HBPM n'ont pas besoin de mesure sauf situation particulière.","flag":"terrain","src":"330 p. 564, 565"},{"ask":"Antiagrégants et AOD : ne pas demander de test d'efficacité","why":"Il n'existe pas de test biologique fiable pour les antiagrégants. Pour les AOD, les tests standards (TCA, TP, INR) sont perturbés et ne renseignent pas sur l'efficacité ; le dosage spécialisé ne doit jamais retarder la prise en charge d'un saignement actif.","flag":"terrain","src":"330 p. 561, 570, 579"},{"ask":"Si fièvre : hémocultures avant toute antibiothérapie, puis ETT, ETO","why":"Diagnostic d'endocardite : hémocultures pour le germe, ETT et ETO pour les végétations, la désinsertion, l'abcès ; dossier discuté en équipe endocardite.","flag":"gravite","src":"153 p. 279-280"},{"ask":"ETT/ETO de la prothèse ; radiocinéma ou scanner synchronisé si besoin","why":"Thrombose : gradients élevés, surface fonctionnelle réduite, thrombus visible. Suivi : ETT de référence au 2e-4e mois, puis tous les 1 à 2 ans pour les mécaniques, annuelle pour les bioprothèses. ETO en cas de suspicion de dysfonction.","flag":"orientation","src":"153 p. 277, 283, 285-286"},{"ask":"Bilan d'hémolyse : LDH, haptoglobine, schizocytes","why":"Une anémie hémolytique mécanique avec LDH élevées, haptoglobine basse et schizocytes oriente vers une désinsertion de prothèse.","flag":"orientation","src":"153 p. 281-282"},{"ask":"Scanner cérébral urgent, ECG, imagerie ciblée selon le tableau","why":"Traumatisme crânien sous AVK : hospitalisation d'au moins 24 heures et scanner cérébral en urgence. ECG pour documenter la FA. Embolie artérielle systémique cérébrale suspectée : imagerie cérébrale à effectuer.","flag":"gravite","src":"330 p. 578, 232 p. 331, 338"},{"ask":"Antidotes et surveillance de la correction","why":"HNF : sulfate de protamine. AVK : vitamine K (quelques heures) et PPSB/CCP (très rapide, durée brève). Dabigatran : idarucizumab ; anti-Xa : PPSB ou Feiba. Après CCP : INR à 30 min, complément si INR > 1,5, puis INR à 6-8 h et 1 fois/j.","flag":"gravite","src":"330 p. 564, 568, 578"}],"astuce":"Antidote en une ligne : HNF = protamine ; AVK = vitamine K + PPSB ; dabigatran = idarucizumab ; anti-Xa = PPSB ou Feiba."}],"synthese":"Patient de 72 ans, porteur d'une prothèse aortique mécanique depuis 2 ans sous AVK (cible INR 3), à l'observance irrégulière, vu pour une dyspnée croissante depuis 5 jours et un déficit transitoire du membre supérieur droit il y a 48 heures. Apyrétique, PA 110/80, FC 94, bruits de prothèse diminués avec un souffle systolique et un souffle diastolique, râles crépitants aux deux bases, léger déficit moteur de la main droite ; INR à 1,4. Hypothèses : thrombose de prothèse mécanique sur sous-dosage, embolie systémique cérébrale, endocardite sur prothèse, désinsertion de prothèse.","hypotheses":[{"dx":"Thrombose obstructive de prothèse mécanique","pour":"Anticoagulation insuffisante, bruits de prothèse diminués, souffle nouveau, OAP ou syncope, gradients élevés à l'ETT/ETO ; Usic, héparine IV + aspirine, réintervention discutée","danger":true,"src":"153 p. 277"},{"dx":"Embolie systémique (AIT/AVC) sur prothèse ou FA","pour":"Déficit neurologique brutal chez un patient sous-anticoagulé ou en FA ; embolies le plus souvent cérébrales (70 %)","danger":true,"src":"153 p. 276, 232 p. 338"},{"dx":"Endocardite sur prothèse","pour":"Fièvre, hémocultures positives, végétations ou abcès à l'ETO ; précoce (< 1 an) mortalité ≈ 50 %","danger":true,"src":"153 p. 279-280"},{"dx":"Hémorragie grave sous anticoagulant","pour":"Saignement incontrôlable, collapsus, besoin de transfusion ou de geste hémostatique, localisation menaçante ; vitamine K + PPSB","danger":true,"src":"330 p. 577-578"},{"dx":"EP à haut risque sous traitement insuffisant","pour":"Dyspnée, douleur thoracique ou syncope avec choc ou PAS < 90 ; fibrinolyse","danger":true,"src":"226 p. 504, 509"},{"dx":"Thrombopénie induite par l'héparine","pour":"Plaquettes < 100 G/L et/ou chute relative de 30 à 50 %, typiquement 5 à 8 jours après le début de l'héparine, nouvelle thrombose, placards inflammatoires au site d'injection","danger":true,"src":"330 p. 574"},{"dx":"Désinsertion de prothèse avec hémolyse","pour":"Souffle nouveau (diastolique en aortique), anémie hémolytique : LDH élevées, haptoglobine basse, schizocytes","danger":false,"src":"153 p. 281-282"},{"dx":"Surdosage asymptomatique en AVK","pour":"INR au-dessus de la cible sans saignement ; conduite selon l'INR, chercher la cause, contrôle le lendemain","danger":false,"src":"330 p. 576-577"},{"dx":"Dégénérescence de bioprothèse","pour":"5 à 15 ans après la pose : souffle modifié, symptômes d'effort qui reviennent, calcifications à l'ETT","danger":false,"src":"153 p. 280-281"}],"pieges":["Valve mécanique ou rétrécissement mitral serré : AOD contre-indiqués, uniquement AVK.","Insuffisance rénale sévère : ni HBPM, ni AOD ; l'HNF reste possible.","Fièvre chez un porteur de prothèse : hémocultures avant tout antibiotique.","Les relais par héparine rassurent mais sont sources de complications hémorragiques et thrombotiques.","Aspirine : ne pas l'arrêter pour les gestes à risque modéré ; si risque important, arrêt de 5 jours au plus.","Oublier l'éducation thérapeutique du patient sous AVK ou AOD : notion inacceptable."],"src":"330 p. 559-580 ; 232 p. 330-338 ; 226 p. 495-517 ; 153 p. 270-287"},{"id":"bilan-risque-cv","spe":"cardio","title":"Bilan de risque cardiovasculaire","emoji":"📋","items":["221","222","223"],"hook":"Une consultation de prévention bien menée réduit le risque d'infarctus et d'AVC : la clé est de classer le patient dans la bonne catégorie de risque (probabilité d'événement à 10 ans).","intro":"Ici le patient n'a souvent aucune plainte : c'est toi qui vas chercher. Tu fais l'inventaire des facteurs de risque, tu vérifies s'il n'y a pas déjà une maladie athéromateuse (ce qui change tout), puis tu calcules le risque à 10 ans et tu fixes un objectif de LDL-cholestérol. Toute consultation est une occasion de prévention.","steps":[{"key":"terrain","title":"Terrain et antécédents : y a-t-il déjà une maladie ?","goal":"Savoir d'emblée si le patient est en prévention secondaire (maladie documentée, risque très élevé) ou en prévention primaire.","questions":[{"ask":"« Avez-vous déjà eu un infarctus, des stents, un pontage, un angor ? »","why":"Une maladie cardiovasculaire documentée classe le patient en prévention secondaire : risque d'emblée très élevé, SCORE2 inutile.","flag":"orientation","src":"222 p. 52, 223 p. 72-73"},{"ask":"« Avez-vous déjà eu un AVC, un petit accident passager (AIT), une artérite des jambes, une opération des artères ? »","why":"Maladie coronaire, AIT/AVC, AOMI : risque très élevé. Au moins deux territoires artériels atteints = patient polyathéromateux.","flag":"orientation","src":"223 p. 73, 221 p. 40"},{"ask":"« Êtes-vous diabétique ? Depuis quand ? Avez-vous des complications (yeux, reins, nerfs) ? »","why":"Le diabète multiplie le risque cardiovasculaire par 2 à 3 ; ancienneté, facteurs de risque associés et atteinte d'organe cible définissent la catégorie de risque (modéré, élevé, très élevé).","flag":"orientation","src":"222 p. 51, 223 p. 73"},{"ask":"« Vos reins fonctionnent-ils bien ? A-t-on trouvé des protéines dans vos urines ? »","why":"L'insuffisance rénale chronique classe le patient à risque élevé ou très élevé selon le DFG et le rapport albuminurie/créatinurie ; SCORE2 ne s'applique pas.","flag":"orientation","src":"222 p. 54, 223 p. 72"},{"ask":"« Dans votre famille, y a-t-il quelqu'un qui a eu un infarctus ou un AVC jeune ? Votre père ou un frère avant 55 ans, votre mère ou une sœur avant 65 ans ? »","why":"Les accidents cardiovasculaires prématurés chez un apparenté (père ou frère avant 55 ans, mère ou sœur avant 65 ans) sont un facteur de risque non pris en compte par les scores : à noter séparément.","flag":"terrain","src":"222 p. 47, 55"},{"ask":"« Dans votre famille, quelqu'un a-t-il un cholestérol très élevé, des dépôts sur les tendons ? »","why":"Pense à l'hypercholestérolémie familiale (LDL-C entre 2 et 4 g/L pour la forme hétérozygote) : le risque est d'emblée élevé et il faut dépister les apparentés du 1er degré.","flag":"orientation","src":"223 p. 70, 72, 77"},{"ask":"« (Femme) À quel âge avez-vous été ménopausée ? Êtes-vous enceinte ou souhaitez-vous le devenir ? »","why":"La ménopause précoce est un facteur de risque propre à la femme ; les statines sont contre-indiquées pendant la grossesse.","flag":"terrain","src":"221 p. 39, 223 p. 76"},{"ask":"Noter l'âge et le sexe du patient (données d'identité, mais elles comptent)","why":"Âge, sexe masculin et antécédents familiaux sont les facteurs non modifiables ; les accidents surviennent en moyenne 10 ans plus tôt chez l'homme que chez la femme. SCORE2 s'applique de 40 à 69 ans, SCORE2-OP à partir de 70 ans.","flag":"terrain","src":"222 p. 47, 52"}],"astuce":"Réflexe en 3 secondes : maladie déjà là, diabète, insuffisance rénale ou hypercholestérolémie familiale ? Si oui, le patient est déjà à haut risque : inutile de calculer SCORE2."},{"key":"symptome","title":"Les facteurs de risque modifiables, un par un","goal":"Quantifier chaque facteur de risque : ce que tu mesures et ce que tu expliques ensuite en consultation de prévention.","questions":[{"ask":"« Fumez-vous ? Depuis quand, combien de cigarettes par jour, quel type de tabac ? Avez-vous essayé d'arrêter ? »","why":"Tabagisme actif : 2e facteur de risque d'infarctus. Le risque est proportionnel à la consommation, sans seuil sans danger, et identique quel que soit le type (cigarettes, pipe, cigare, narguilé, tabac à mâcher).","flag":"orientation","src":"222 p. 48"},{"ask":"« Êtes-vous exposé à la fumée des autres, à la maison ou au travail ? »","why":"Le tabagisme passif augmente le risque d'infarctus (+24 % pour 1 à 7 heures par semaine, +62 % au-delà de 22 heures).","flag":"terrain","src":"222 p. 48"},{"ask":"« Quel niveau de dépendance, quelle motivation pour arrêter ? Autres consommations : alcool, cannabis, anxiolytiques ? »","why":"On évalue la motivation et la dépendance physique (test de Fagerström), on prend en compte les autres dépendances, puis on propose aide et suivi. Le « conseil minimum » peut doubler le taux de sevrage à un an.","flag":"terrain","src":"222 p. 59-60"},{"ask":"« A-t-on déjà mesuré votre cholestérol ? Quels étaient les chiffres ? Prenez-vous un traitement ? »","why":"L'hypercholestérolémie est le facteur le plus important pour la maladie coronarienne ; le bilan lipidique est conseillé chez tous les adultes, et sans anomalie il n'est pas à refaire avant 5 ans.","flag":"terrain","src":"222 p. 49, 223 p. 68"},{"ask":"« Votre tension a-t-elle déjà été trouvée élevée ? Quelles valeurs ? Prenez-vous un traitement ? »","why":"L'HTA concerne 20 à 30 % des adultes ; le risque cardiovasculaire croît avec la PA, même pour des valeurs inférieures à la normale (PA élevée > 120/70).","flag":"terrain","src":"222 p. 49"},{"ask":"« A-t-on déjà trouvé du sucre dans votre sang ? Quand a-t-on mesuré votre glycémie la dernière fois ? »","why":"Diabète : glycémie à jeun > 1,26 g/L (7 mmol/L) à deux reprises, ou glycémie > 2 g/L à n'importe quel moment de la journée. Hyperglycémie à jeun non diabétique : entre 1,00 et 1,26 g/L. Diagnostic le plus souvent lors d'un dépistage chez un sujet de plus de 50 ans, sédentaire, en surcharge pondérale. Chez un patient avec maladie cardiovasculaire, il faut aussi dépister un diabète méconnu.","flag":"terrain","src":"222 p. 50-51, 52"},{"ask":"« Quel est votre poids, votre taille ? Avez-vous pris du poids, du tour de taille ? »","why":"L'IMC (poids / taille²) normal est entre 18,5 et 25 ; le périmètre ombilical, mieux corrélé au risque cardiovasculaire, reflète la graisse viscérale.","flag":"terrain","src":"222 p. 51"},{"ask":"« Faites-vous du sport ? Combien de minutes par semaine ? Passez-vous beaucoup de temps assis ? »","why":"La sédentarité est un facteur prédisposant ; la recommandation est au moins 30 minutes, 5 jours par semaine (150 à 300 minutes d'activité modérée par semaine). L'activité physique est un facteur protecteur.","flag":"terrain","src":"222 p. 48, 60, 221 p. 39"},{"ask":"« Mangez-vous des fruits et légumes chaque jour ? Du poisson ? Beaucoup de graisses animales, de sucre, de sel ? »","why":"Messages du PNNS : 5 fruits et légumes par jour, poisson 2 fois par semaine, limiter graisses saturées, sucres, sel ; l'alimentation de type méditerranéen a un bénéfice cardiovasculaire établi.","flag":"terrain","src":"222 p. 60, 61, 223 p. 75"},{"ask":"« Combien de verres d'alcool buvez-vous par semaine ? »","why":"Il faut limiter la consommation d'alcool, en particulier pour les triglycérides.","flag":"terrain","src":"223 p. 75"},{"ask":"« Comment vous sentez-vous moralement : stress, déprime, isolement, difficultés sociales ? »","why":"Les facteurs psychosociaux (dépression, troubles psychiques, catégorie sociale défavorisée, isolement social) augmentent le risque mais ne sont pas inclus dans les scores.","flag":"terrain","src":"222 p. 47, 55, 221 p. 39"}],"astuce":"Les 6 facteurs d'INTERHEART (9 facteurs expliquent 90 % des infarctus) : tabac, cholestérol, HTA, diabète, obésité abdominale, psychosocial. Les protecteurs : fruits et légumes, activité physique, alcool léger."},{"key":"associes","title":"Signes associés : la maladie athéromateuse est-elle déjà symptomatique ?","goal":"Passer en revue tous les territoires artériels : un patient asymptomatique dans un territoire peut être atteint dans un autre.","questions":[{"ask":"« Avez-vous une douleur ou une oppression dans la poitrine à l'effort ? »","why":"Réduction progressive de la lumière artérielle : angor d'effort (territoire coronaire). La plaque est responsable de cardiopathie ischémique.","flag":"orientation","src":"221 p. 39"},{"ask":"« Avez-vous mal dans les mollets quand vous marchez, obligeant à vous arrêter ? Au bout de combien de mètres ? »","why":"Claudication intermittente des membres inférieurs : sténose des artères des membres inférieurs (AOMI) ; 90 % des artéritiques sont fumeurs.","flag":"orientation","src":"221 p. 39, 222 p. 48"},{"ask":"« Avez-vous déjà eu un déficit neurologique, même passager (faiblesse ou engourdissement d'un côté du corps) ? »","why":"Plaques carotidiennes et plaques de la crosse de l'aorte : à l'origine d'AVC et d'AIT. Le déficit neurologique est un signe d'appel de complication.","flag":"orientation","src":"221 p. 38, 42"},{"ask":"« Avez-vous des douleurs de ventre après les repas ? »","why":"Claudication digestive (douleurs postprandiales) : sténose des artères digestives, ischémie mésentérique.","flag":"orientation","src":"221 p. 39"},{"ask":"« (Homme) Avez-vous des troubles de l'érection ? »","why":"La dysfonction érectile peut être un indicateur de maladie artérielle : à ne pas oublier dans la recherche d'un patient polyvasculaire.","flag":"orientation","src":"221 p. 40"},{"ask":"« Vos pieds ou vos mains sont-ils froids, avez-vous des plaies qui ne cicatrisent pas ? »","why":"Extrémités froides et lésions cutanées d'allure ischémique sont des signes d'atteinte vasculaire périphérique.","flag":"orientation","src":"224 p. 92"},{"ask":"« Avez-vous eu une tension difficile à équilibrer, des poussées d'œdème pulmonaire, des reins qui fonctionnent moins bien ? »","why":"Les sténoses des artères rénales sont responsables d'HTA et d'insuffisance rénale. Un œdème aigu pulmonaire récidivant sans cause cardiaque et une insuffisance rénale compliquant l'introduction d'un IEC/ARA2 évoquent une HTA rénovasculaire.","flag":"orientation","src":"221 p. 38, 224 p. 103"}],"astuce":"Les 4 grands territoires : coronaires, carotides, membres inférieurs, aorte abdominale. Un questionnaire = un territoire."},{"key":"orientation","title":"Les questions qui orientent : dyslipidémie primitive ou secondaire ?","goal":"Devant un cholestérol ou des triglycérides élevés, éliminer une cause secondaire avant de parler de dyslipidémie primitive.","questions":[{"ask":"« A-t-on déjà trouvé un problème de thyroïde (hypothyroïdie) ? Prenez-vous un traitement pour la thyroïde ? »","why":"Hypothyroïdie : cause d'hypercholestérolémie ou d'hyperlipidémie mixte (diagnostic par la TSH).","if":"Si oui → TSH","flag":"orientation","src":"223 p. 69"},{"ask":"« A-t-on déjà trouvé un problème de foie ou de voies biliaires (cholestase) ? »","why":"Cholestase : hypercholestérolémie (bilirubine, phosphatases alcalines).","if":"Si oui → bilirubine, PAL","flag":"orientation","src":"223 p. 69"},{"ask":"« Avez-vous les jambes gonflées (œdèmes) ? A-t-on trouvé des protéines dans vos urines ? »","why":"Syndrome néphrotique : hyperlipidémie mixte (protéinurie, œdèmes) ; l'insuffisance rénale chronique donne une HTG ou une hyperlipidémie mixte (créatinine).","if":"Si oui → protéinurie, créatinine","flag":"orientation","src":"223 p. 69"},{"ask":"« Buvez-vous de l'alcool ? Combien ? Votre glycémie est-elle bien équilibrée ? »","why":"Alcoolisme (interrogatoire) et diabète (glycémie, HbA1c) donnent une hypertriglycéridémie.","if":"Si oui → HTG secondaire","flag":"orientation","src":"223 p. 69"},{"ask":"« Prenez-vous des œstrogènes, de la cortisone, des rétinoïdes, des antirétroviraux, de la ciclosporine, un antipsychotique ? »","why":"Hyperlipidémies iatrogènes : œstrogènes (HTG), corticoïdes (HLM/HTG), rétinoïdes (HTG), antirétroviraux (HTG), ciclosporine (HCH/HLM), antipsychotiques (HLM/HTG).","if":"Si oui → médicament en cause","flag":"orientation","src":"223 p. 69"},{"ask":"« Avez-vous des dépôts jaunes sur les tendons, sous les yeux, autour de l'iris ? Y en a-t-il dans la famille ? »","why":"Xanthomes tendineux (tendon calcanéen, extenseurs des membres supérieurs), arc cornéen prématuré, xanthélasma : caractéristiques (inconstants) de l'hypercholestérolémie familiale.","if":"Si oui → hypercholestérolémie familiale, score Dutch-HF","flag":"orientation","src":"222 p. 49, 223 p. 70"},{"ask":"« Avez-vous déjà eu une pancréatite ? »","why":"Le principal autre risque des dyslipidémies est la pancréatite aiguë, en cas d'hypertriglycéridémie supérieure à 10 g/L (risque majeur dans les hyperchylomicronémies).","if":"Si oui → TG > 10 g/L, avis spécialisé","flag":"gravite","src":"223 p. 68, 72, 76"}],"astuce":"Causes secondaires en 6 : thyroïde, foie (cholestase), rein (néphrotique, IRC), alcool, diabète, médicaments. Pour chaque bilan lipidique anormal, passe-les en revue avant d'étiqueter « familial »."},{"key":"examen","title":"Examen clinique ciblé","goal":"Mesurer les paramètres du score et chercher des signes de maladie artérielle dans tous les territoires.","questions":[{"ask":"Mesurer la PA aux deux bras, en conditions standardisées","why":"Une différence > 15 mmHg entre les deux bras, sur plusieurs mesures, doit faire suspecter une sténose unilatérale de l'artère subclavière. La PAS entre dans le calcul de SCORE2.","flag":"orientation","src":"221 p. 41, 222 p. 52"},{"ask":"Peser, mesurer, calculer l'IMC ; mesurer le périmètre abdominal (ombilical)","why":"Surpoids IMC 25-29,9 ; obésité ≥ 30 ; obésité centrale à partir de 94 cm chez l'homme, 80 cm chez la femme (critère du syndrome métabolique).","flag":"terrain","src":"222 p. 51"},{"ask":"Rechercher des xanthomes tendineux (tendon d'Achille), un arc cornéen, un xanthélasma","why":"Dépôts de cholestérol caractéristiques de l'hypercholestérolémie familiale hétérozygote ; xanthomes dès l'enfance dans la forme homozygote.","flag":"orientation","src":"223 p. 70"},{"ask":"Examen clinique de tous les territoires : auscultation carotidienne, cardiaque, abdominale, fémorale ; palpation des pouls","why":"Le bilan clinique systématique de tous les territoires (interrogatoire et examen) cherche souffles, pouls abolis ou amortis ; le Collège donne la vignette d'un souffle fémoral et carotidien avec pouls aval absents (AOMI chez un possible polyvasculaire).","flag":"orientation","src":"221 p. 41, 34"},{"ask":"Palper l'abdomen à la recherche d'une masse battante","why":"Le dépistage d'un anévrisme de l'aorte abdominale est effectué, notamment chez les hommes après 65 ans ; les fumeurs sont plus exposés.","flag":"orientation","src":"221 p. 41, 222 p. 48, 224 p. 92"},{"ask":"Noter le statut tabagique (fumeur actif ou non) et l'âge","why":"Le statut tabagique est un paramètre de SCORE2 (tabagisme actif).","flag":"terrain","src":"222 p. 54"}],"astuce":"Un seul geste manquant coûte cher : la PA aux deux bras. Elle révèle une sténose sous-clavière que l'on ne soupçonnait pas."},{"key":"gravite","title":"Signes de gravité (à chercher d'emblée)","goal":"Repérer ce qui fait sortir du cadre d'une simple consultation de prévention : une maladie déjà expressive, une PA très élevée, des triglycérides très hauts.","questions":[{"ask":"« Avez-vous eu récemment une douleur dans la poitrine ? »","why":"La douleur thoracique est un signe d'appel de complication que l'on apprend aussi au patient ; une rupture de plaque coronarienne peut donner un infarctus ou une mort subite, même sur une plaque peu sténosante.","flag":"gravite","src":"221 p. 39, 42"},{"ask":"« Avez-vous eu un déficit neurologique, même passager ? »","why":"Déficit neurologique : autre signe d'appel de complication (AVC, AIT) à connaître et à enseigner.","flag":"gravite","src":"221 p. 42"},{"ask":"Mesurer la PA : est-elle ≥ 180/110 mmHg ?","why":"HTA de grade 3 : on cherche systématiquement une urgence hypertensive (cf. item 224). L'ancien outil SCORE n'était pas adapté aux hypertendus sévères (PA ≥ 180/110).","flag":"gravite","src":"224 p. 86, 222 p. 52"},{"ask":"LDL-C très élevé : entre 2 et 4 g/L, voire > 5 g/L ?","why":"Une élévation majeure du LDL-C > 5 g/L évoque l'hypercholestérolémie familiale homozygote (dépôts dès l'enfance, complications coronariennes avant 20 ans) ; LDL-C entre 2 et 4 g/L : forme hétérozygote avec complications possibles dès la quarantaine.","flag":"gravite","src":"222 p. 49, 223 p. 70"},{"ask":"Triglycérides > 10 g/L ?","why":"Hypertriglycéridémie majeure : risque de pancréatite aiguë ; avis spécialisé et apport lipidique < 30 g/jour en cas d'hyperchylomicronémie.","flag":"gravite","src":"223 p. 72, 76"},{"ask":"Un patient diabétique avec atteinte d'organe cible (insuffisance rénale, microangiopathie sur 3 sites) ou une maladie cardiovasculaire établie ?","why":"Risque très élevé : cible de LDL-C < 0,55 g/L ; le traitement médicamenteux est en général indiqué d'emblée, avec le traitement diététique.","flag":"gravite","src":"223 p. 73, 76"}],"astuce":"Rien n'oblige à attendre trois mois de régime en prévention secondaire : risque très élevé = traitement d'emblée, fortes doses de statine."},{"key":"examens","title":"Examens de 1re intention et calcul du risque","goal":"Objectiver chaque paramètre, classer le risque et fixer l'objectif de LDL-C.","questions":[{"ask":"Exploration d'une anomalie lipidique à jeun : cholestérol total, HDL-C, triglycérides, LDL-C calculé","why":"LDL-C = CT − HDL-C − TG/5 (g/L), valable seulement si TG < 3,5 g/L. Bilan normal chez un sujet sans autre facteur de risque : LDL-C < 1,6 ; HDL-C > 0,4 ; TG < 1,5 g/L.","flag":"terrain","src":"222 p. 49, 223 p. 68-69"},{"ask":"Glycémie à jeun (et HbA1c si diabète)","why":"Un bilan biologique de référence avec glycémie et bilan lipidique complet à jeun détecte les anomalies métaboliques.","flag":"terrain","src":"222 p. 58"},{"ask":"Créatininémie avec DFG estimé et rapport albuminurie/créatinurie sur échantillon d'urine","why":"La microalbuminurie est un marqueur précoce de néphropathie et prédit le risque d'insuffisance rénale et cardiovasculaire ; dépistage de l'IRC chez le diabétique au moins une fois par an.","flag":"terrain","src":"222 p. 54, 56"},{"ask":"Si bilan lipidique anormal : TSH, bilirubine et phosphatases alcalines, créatinine, protéinurie, glycémie / HbA1c","why":"Moyens diagnostiques des hyperlipidémies secondaires : hypothyroïdie (TSH), cholestase (bilirubine, PAL), syndrome néphrotique (protéinurie), IRC (créatinine), diabète (glycémie, HbA1c).","flag":"orientation","src":"223 p. 69"},{"ask":"ECG de repos systématique et IPS aux membres inférieurs chez le patient athéromateux","why":"Dans le bilan d'extension d'un patient polyvasculaire, l'ECG est systématique et l'IPS réalisé aux membres inférieurs ; le dépistage n'a d'intérêt que s'il modifie la prise en charge.","flag":"orientation","src":"221 p. 40-41"},{"ask":"Calculer le risque à 10 ans : SCORE2 (40-69 ans), SCORE2-OP (≥ 70 ans), SCORE2-Diabetes (diabète de type 2 sans maladie cardiovasculaire)","why":"SCORE2 : sexe, âge, tabagisme actif, PAS, cholestérol non-HDL (CT − HDL) ; événements fatals et non fatals (infarctus, AVC) pour la France (pays à bas risque). SCORE2-Diabetes ajoute âge au diagnostic, HbA1c, DFGe.","flag":"orientation","src":"222 p. 52-54, 223 p. 72"},{"ask":"Classer en catégorie : < 50 ans <2,5 % / 2,5 à <7,5 % / ≥7,5 % ; 50-69 ans <5 % / 5 à <10 % / ≥10 % ; ≥70 ans <7,5 % / 7,5 à <15 % / ≥15 %","why":"Faible à modéré (traitement généralement non indiqué), élevé (le plus souvent indiqué), très élevé (généralement indiqué). Chez le diabétique : faible < 5 %, modéré 5-<10, élevé 10-<20, très élevé ≥ 20 % ou maladie CV / atteinte d'organe cible. Bornes du tableau 2.3 (222 p. 55) ; le tableau 3.4 (223 p. 73) les écrit 2,5-7,5 / > 7,5, 5-10 / > 10, 7,5-15 / > 15.","flag":"orientation","src":"222 p. 55 ; 223 p. 73"},{"ask":"Fixer l'objectif de LDL-C : risque faible < 1,15 g/L ; modéré < 1 ; élevé < 0,70 ; très élevé et prévention secondaire < 0,55 g/L","why":"Le LDL-C reste l'objectif principal car les preuves de bénéfice reposent sur son abaissement. Conseils de mode de vie toujours ; médicament après ≥ 3 mois en prévention primaire, d'emblée si risque très élevé.","flag":"orientation","src":"223 p. 73-75"},{"ask":"Programmer le contrôle : bilan lipidique 8 à 12 semaines après chaque changement de traitement ; surveillance des myalgies et des transaminases","why":"Efficacité évaluée à 8-12 semaines ; effet indésirable fréquent des statines = myalgies ; CPK seulement si symptômes ou terrain à risque ; ALAT avant, à 8-12 semaines puis annuellement si < 3 N.","flag":"terrain","src":"223 p. 77"}],"astuce":"Ne demande pas de CRP, d'homocystéine, de score calcique ou d'épaisseur intima-média en routine : ce sont des marqueurs, pas des facteurs, et le Collège ne les recommande pas pour évaluer le risque."}],"synthese":"Homme de 58 ans, fumeur à 20 cigarettes/jour depuis 35 ans, sans antécédent cardiovasculaire, dont le père a eu un infarctus à 52 ans, vu pour un bilan de prévention. PA à 148/88 aux deux bras, IMC 29, LDL-C à 1,8 g/L, HDL-C 0,38 g/L, glycémie à jeun 1,05 g/L, pas de claudication ni d'angor, pas de souffle ; pas de cause secondaire de dyslipidémie. Hypothèses : prévention primaire, risque cardiovasculaire à classer par SCORE2 (probablement élevé à très élevé) ; syndrome métabolique à discuter ; maladie athéromateuse encore silencieuse à dépister ; objectif LDL-C selon la catégorie et sevrage tabagique prioritaire.","hypotheses":[{"dx":"Prévention secondaire (maladie CV documentée) : risque très élevé","pour":"Antécédent d'infarctus, AVC/AIT, AOMI, ou lésion athéromateuse sévère : LDL-C < 0,55 g/L, BASIC","danger":true,"src":"222 p. 52, 57, 223 p. 73, 221 p. 40"},{"dx":"Malade polyathéromateux","pour":"Atteinte athéromateuse d'au moins deux territoires (ex. AOMI + coronaire) ; plaque non sténosante < 50 % ne compte pas","danger":true,"src":"221 p. 40"},{"dx":"Hypercholestérolémie familiale hétérozygote","pour":"LDL-C 2-4 g/L, xanthomes tendineux, arc cornéen, antécédents familiaux précoces ; risque élevé, dépistage en cascade","danger":true,"src":"223 p. 70, 77"},{"dx":"Hypertriglycéridémie sévère (risque de pancréatite)","pour":"TG > 10 g/L ; avis spécialisé","danger":true,"src":"223 p. 72, 76"},{"dx":"Prévention primaire : risque élevé ou très élevé","pour":"SCORE2/SCORE2-OP au-dessus des seuils par âge, ou diabète avec facteur de risque ou > 10 ans, ou insuffisance rénale","danger":false,"src":"222 p. 55, 223 p. 72-73"},{"dx":"Prévention primaire : risque faible à modéré","pour":"SCORE2 < 2,5 % (< 50 ans), < 5 % (50-69 ans), < 7,5 % (≥ 70 ans) ; mesures hygiénodiététiques, traitement en général non indiqué","danger":false,"src":"222 p. 55"},{"dx":"Dyslipidémie secondaire","pour":"Hypothyroïdie, cholestase, syndrome néphrotique, IRC, alcool, diabète, médicaments","danger":false,"src":"223 p. 69"},{"dx":"Syndrome métabolique","pour":"Périmètre abdominal ≥ 94 cm (H) / 80 cm (F) + au moins 2 critères : TG > 1,5 g/L, HDL-C bas, PA ≥ 130/85, glycémie > 1 g/L ou DT2","danger":false,"src":"222 p. 51"}],"pieges":["SCORE2 ne s'applique pas si maladie CV, diabète, IRC, hypercholestérolémie familiale : risque d'emblée élevé ou très élevé.","Antécédents familiaux et facteurs psychosociaux : réels, mais absents des scores.","Prévention secondaire : ne jamais oublier aspirine et statine (notion inacceptable).","Friedewald invalide si TG ≥ 3,5 g/L.","Plaque carotidienne < 50 % non compliquée = pas un polyvasculaire."],"src":"221 p. 35-43 ; 222 p. 46-61 ; 223 p. 68-77"}];
